window.ETSDATA=window.ETSDATA||{};window.ETSDATA[10]={"lc":{"p1":[{"n":1,"opts":["He’s reaching for the ceiling.","He’s carrying a bucket of paint.","He’s fixing a doorway.","He’s climbing down a ladder."],"vi":["Anh ấy đang với tay lên trần nhà.","Anh ấy đang mang theo một xô sơn.","Anh ấy đang sửa một khung cửa.","Anh ấy đang trèo xuống một chiếc thang."],"ans":"D","a":"E26-T10-01.mp3","img":"q1.jpg"},{"n":2,"opts":["She’s reading a poster on the wall.","A chair is propped against the door.","A laptop has been left open.","She’s speaking into a microphone."],"vi":["Cô ấy đang đọc một tấm áp phích trên tường.","Một chiếc ghế được dựng tựa vào cửa.","Một chiếc máy tính xách tay đang được để mở.","Cô ấy đang nói vào micro."],"ans":"C","a":"E26-T10-02.mp3","img":"q2.jpg"},{"n":3,"opts":["They’re strolling in a park.","They’re shaking hands.","He’s holding up an umbrella.","She’s handing him a phone."],"vi":["Họ đang dạo bộ trong công viên.","Họ đang bắt tay nhau.","Anh ấy đang cầm một chiếc ô giơ lên.","Cô ấy đang đưa cho anh ấy một chiếc điện thoại."],"ans":"C","a":"E26-T10-03.mp3","img":"q3.jpg"},{"n":4,"opts":["A car is being towed down a street.","Some men are removing a tire from a truck.","One of the men is unloading equipment from a truck.","A building has a clock tower on top of it."],"vi":["Một chiếc xe hơi đang được kéo đi trên đường phố.","Một số người đàn ông đang tháo một chiếc lốp khỏi xe tải.","Một trong những người đàn ông đang dỡ thiết bị từ xe tải xuống.","Một tòa nhà có tháp đồng hồ ở trên đỉnh."],"ans":"D","a":"E26-T10-04.mp3","img":"q4.jpg"},{"n":5,"opts":["Some of the bicycles are being repaired.","The bicycles are lined up in a row.","One of the bicycles is leaning against a traffic sign.","A bicycle path is being painted."],"vi":["Một số chiếc xe đạp đang được sửa chữa.","Những chiếc xe đạp được xếp thành một hàng.","Một trong những chiếc xe đạp đang tựa vào biển báo giao thông.","Một làn đường dành cho xe đạp đang được sơn."],"ans":"B","a":"E26-T10-05.mp3","img":"q5.jpg"},{"n":6,"opts":["Some ships are moving under a bridge.","Some boats are docked near a shore.","A ferryboat is traveling through a marina.","There are buildings along the side of a street."],"vi":["Một số con tàu đang di chuyển bên dưới cây cầu.","Một số chiếc thuyền đang neo đậu gần bờ.","Một chiếc phà đang di chuyển qua bến du thuyền.","Có các tòa nhà dọc theo một con phố."],"ans":"B","a":"E26-T10-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"Would you like me to order some more business cards for you?","qvi":"Bạn có muốn tôi đặt thêm danh thiếp cho bạn không?","opts":["Sure, that’d be great.","They’ll be busy at that time.","No, it wasn’t."],"vi":["Có, như vậy thì tuyệt quá.","Họ sẽ bận vào thời điểm đó.","Không, không phải vậy."],"ans":"A","a":"E26-T10-07.mp3"},{"n":8,"q":"Why don’t you ask Ms. Kim for help?","qvi":"Tại sao bạn không nhờ cô Kim giúp?","opts":["Because she’s on a conference call.","There’s no more paper in the cabinet.","I’ve already seen that one."],"vi":["Vì cô ấy đang tham gia một cuộc gọi hội nghị.","Không còn giấy trong tủ nữa.","Tôi đã xem cái đó rồi."],"ans":"A","a":"E26-T10-08.mp3"},{"n":9,"q":"Do you want to review the report together, or on your own?","qvi":"Bạn muốn cùng xem lại báo cáo hay tự xem một mình?","opts":["No, I don’t need any more copies.","I’d prefer to look it over myself.","A fifteen-page document."],"vi":["Không, tôi không cần thêm bản sao nào nữa.","Tôi muốn tự xem lại một mình.","Một tài liệu dài mười lăm trang."],"ans":"B","a":"E26-T10-09.mp3"},{"n":10,"q":"When’s the marketing conference?","qvi":"Hội nghị tiếp thị diễn ra khi nào?","opts":["The convention center downtown.","Sometime next month.","I need a room with a projector."],"vi":["Ở trung tâm hội nghị trong trung tâm thành phố.","Vào khoảng tháng sau.","Tôi cần một phòng có máy chiếu."],"ans":"B","a":"E26-T10-10.mp3"},{"n":11,"q":"Where are the safety goggles kept?","qvi":"Kính bảo hộ an toàn được để ở đâu?","opts":["I’m visiting an eye doctor soon.","They’re in the first-floor supply closet.","Sure, I’ll try them on."],"vi":["Tôi sắp đi khám mắt.","Chúng ở trong phòng chứa đồ tầng một.","Được, tôi sẽ thử chúng."],"ans":"B","a":"E26-T10-11.mp3"},{"n":12,"q":"When did this restaurant change its name?","qvi":"Nhà hàng này đổi tên khi nào?","opts":["Yes, it is well-known.","I’m not sure.","It’s my favorite type of cuisine."],"vi":["Vâng, nó rất nổi tiếng.","Tôi không chắc.","Đó là loại ẩm thực tôi yêu thích nhất."],"ans":"B","a":"E26-T10-12.mp3"},{"n":13,"q":"Did we complete the inventory, or is there more to do?","qvi":"Chúng ta đã hoàn tất việc kiểm kê chưa, hay vẫn còn việc phải làm?","opts":["OK, that’d be fine.","We’re not quite finished.","About 1,000 dollars."],"vi":["Được, như vậy cũng ổn.","Chúng ta vẫn chưa hoàn thành xong.","Khoảng 1.000 đô la."],"ans":"B","a":"E26-T10-13.mp3"},{"n":14,"q":"Can you get me a sandwich from the café down the street?","qvi":"Bạn có thể mua giúp tôi một chiếc bánh mì từ quán cà phê ở cuối đường không?","opts":["He left an hour ago.","The street signs will be replaced next week.","I’m just about to start a meeting."],"vi":["Anh ấy rời đi cách đây một giờ.","Các biển báo đường phố sẽ được thay vào tuần tới.","Tôi sắp bắt đầu một cuộc họp."],"ans":"C","a":"E26-T10-14.mp3"},{"n":15,"q":"How can we interest the client in our business?","qvi":"Làm thế nào để chúng ta thu hút khách hàng quan tâm đến doanh nghiệp của mình?","opts":["By sharing positive customer reviews.","No, I didn't go this year.","At the meeting last Wednesday."],"vi":["Bằng cách chia sẻ những đánh giá tích cực từ khách hàng.","Không, tôi không đi năm nay.","Tại cuộc họp vào thứ Tư tuần trước."],"ans":"A","a":"E26-T10-15.mp3"},{"n":16,"q":"Are you planning to work at home tomorrow?","qvi":"Bạn có dự định làm việc tại nhà vào ngày mai không?","opts":["Yes, in the city directory.","Every day at three o'clock.","No, I'll be going into the office."],"vi":["Có, trong danh bạ thành phố.","Mỗi ngày vào lúc ba giờ.","Không, tôi sẽ đến văn phòng."],"ans":"C","a":"E26-T10-16.mp3"},{"n":17,"q":"Don't you have the promotional materials with you?","qvi":"Bạn không mang theo tài liệu quảng bá sao?","opts":["Thanks, that's great news.","Yes, they're in my bag.","It's lightweight but durable."],"vi":["Cảm ơn, đó là tin rất tốt.","Có, chúng ở trong túi của tôi.","Nó nhẹ nhưng bền."],"ans":"B","a":"E26-T10-17.mp3"},{"n":18,"q":"The projector needs to be fixed before our presentation.","qvi":"Máy chiếu cần được sửa trước buổi thuyết trình của chúng ta.","opts":["A technician has been notified.","The quarterly sales figures.","These pens have our logo on them."],"vi":["Một kỹ thuật viên đã được thông báo.","Các số liệu bán hàng theo quý.","Những cây bút này có logo của công ty chúng ta."],"ans":"A","a":"E26-T10-18.mp3"},{"n":19,"q":"What’s the price of this printer?","qvi":"Giá của chiếc máy in này là bao nhiêu?","opts":["I don’t work here.","It’s on Washington Avenue.","Yes, I like it a lot."],"vi":["Tôi không làm việc ở đây.","Nó ở trên đại lộ Washington.","Vâng, tôi rất thích nó."],"ans":"A","a":"E26-T10-19.mp3"},{"n":20,"q":"How many people are attending the orientation session?","qvi":"Có bao nhiêu người tham dự buổi định hướng?","opts":["There should be 21 people.","Maybe next week.","I can’t see the screen."],"vi":["Sẽ có khoảng 21 người.","Có lẽ vào tuần tới.","Tôi không nhìn thấy màn hình."],"ans":"A","a":"E26-T10-20.mp3"},{"n":21,"q":"There’s a free shuttle bus to the airport, right?","qvi":"Có xe buýt trung chuyển miễn phí ra sân bay, đúng không?","opts":["She has an overnight flight.","Yes, it stops right outside.","No, I don’t have any."],"vi":["Cô ấy có chuyến bay qua đêm.","Đúng vậy, nó dừng ngay bên ngoài.","Không, tôi không có cái nào."],"ans":"B","a":"E26-T10-21.mp3"},{"n":22,"q":"Who has time to edit this article?","qvi":"Ai có thời gian chỉnh sửa bài viết này?","opts":["The library is on Walton Street.","To meet the client.","It was checked this morning."],"vi":["Thư viện ở đường Walton.","Để gặp khách hàng.","Nó đã được kiểm tra vào sáng nay."],"ans":"C","a":"E26-T10-22.mp3"},{"n":23,"q":"What time does the factory shift end?","qvi":"Ca làm việc ở nhà máy kết thúc lúc mấy giờ?","opts":["Because it’s too far.","I’m glad you like it.","The schedule is posted in the break room."],"vi":["Vì nó quá xa.","Tôi rất vui vì bạn thích nó.","Lịch làm việc được dán trong phòng nghỉ."],"ans":"C","a":"E26-T10-23.mp3"},{"n":24,"q":"These train tickets are expensive.","qvi":"Những vé tàu này đắt thật.","opts":["Just a one-way ticket, please.","Did you complete the training?","Yes, it’s an express train."],"vi":["Cho tôi một vé một chiều thôi.","Bạn đã hoàn thành khóa đào tạo chưa?","Vâng, đó là tàu tốc hành."],"ans":"C","a":"E26-T10-24.mp3"},{"n":25,"q":"Isn’t this television prototype supposed to have more advanced features?","qvi":"Chẳng phải mẫu tivi thử nghiệm này được cho là có nhiều tính năng tiên tiến hơn sao?","opts":["He has an advanced degree in economics.","We’re already over budget.","I really enjoyed that television program."],"vi":["Anh ấy có bằng cấp cao về kinh tế.","Chúng ta đã vượt quá ngân sách rồi.","Tôi thực sự rất thích chương trình truyền hình đó."],"ans":"B","a":"E26-T10-25.mp3"},{"n":26,"q":"What should we do to prepare for the sales meeting?","qvi":"Chúng ta nên làm gì để chuẩn bị cho cuộc họp bán hàng?","opts":["Let’s discuss it after lunch.","With the sixteen summer interns.","The conference center on Mill Street."],"vi":["Hãy thảo luận sau bữa trưa.","Với mười sáu thực tập sinh mùa hè.","Trung tâm hội nghị trên đường Mill."],"ans":"A","a":"E26-T10-26.mp3"},{"n":27,"q":"Do you think Ms. Wang would be interested in joining the event planning committee?","qvi":"Bạn có nghĩ cô Vương sẽ quan tâm đến việc tham gia ủy ban tổ chức sự kiện không?","opts":["Let’s reserve the hotel ballroom.","She’ll be on vacation for the next month.","I’d love a cup of tea."],"vi":["Hãy đặt trước phòng khiêu vũ của khách sạn.","Cô ấy sẽ đi nghỉ trong tháng tới.","Tôi rất muốn một tách trà."],"ans":"B","a":"E26-T10-27.mp3"},{"n":28,"q":"Dr. Marino has the survey results on his desk.","qvi":"Bác sĩ Marino có kết quả khảo sát trên bàn làm việc của ông ấy.","opts":["His office door is locked.","He passed his driving test.","The pharmacy on Maple Street."],"vi":["Cửa văn phòng của ông ấy bị khóa.","Ông ấy đã vượt qua kỳ thi lái xe.","Hiệu thuốc trên đường Maple."],"ans":"A","a":"E26-T10-28.mp3"},{"n":29,"q":"The keynote speech wasn’t very inspiring, was it?","qvi":"Bài phát biểu chính không mấy truyền cảm hứng, đúng không?","opts":["It was too technical.","No, the one on the right side.","Some receipts for expenses."],"vi":["Nó quá mang tính kỹ thuật.","Không, cái ở phía bên phải.","Một số hóa đơn chi phí."],"ans":"A","a":"E26-T10-29.mp3"},{"n":30,"q":"Our company is upgrading its bookkeeping software.","qvi":"Công ty chúng ta đang nâng cấp phần mềm kế toán.","opts":["No, I took a different flight.","How was your business trip to Shanghai?","I signed up for a training session this morning."],"vi":["Không, tôi đã đi chuyến bay khác.","Chuyến công tác Thượng Hải của bạn thế nào?","Tôi đã đăng ký một buổi đào tạo sáng nay."],"ans":"C","a":"E26-T10-30.mp3"},{"n":31,"q":"Should we set up the buffet table for tomorrow’s luncheon indoors or outdoors?","qvi":"Chúng ta nên sắp xếp bàn tiệc cho bữa trưa ngày mai ở trong nhà hay ngoài trời?","opts":["I haven't seen her.","We won't need any more copies.","It’s supposed to be a beautiful day."],"vi":["Tôi chưa gặp cô ấy.","Chúng ta sẽ không cần thêm bản sao nào nữa.","Trời được dự báo là sẽ rất đẹp."],"ans":"C","a":"E26-T10-31.mp3"}],"p3":[{"ns":[32,34],"script":[["M","Bianca, the retail space next door to us will become available in June. That means we can begin the store expansion we've been planning.","Bianca, không gian bán lẻ bên cạnh chúng ta sẽ có sẵn vào tháng Sáu. Điều đó có nghĩa là chúng ta có thể bắt đầu mở rộng cửa hàng mà chúng ta đã lên kế hoạch."],["W","That's great news! After we increase our space, we can finally do more than just sell musical instruments.","Thật là tin tuyệt vời! Sau khi mở rộng không gian, cuối cùng chúng ta có thể làm nhiều thứ hơn là chỉ bán nhạc cụ."],["M","I knew you'd be happy to hear the news. We'll be able to add practice rooms so we can offer private music lessons by the end of the year.","Anh biết em sẽ vui khi nghe tin này. Chúng ta sẽ có thể thêm các phòng luyện tập để cung cấp các lớp học nhạc riêng vào cuối năm."]],"qs":[{"n":32,"q":"What is the speakers’ business planning to do in June?","qvi":"Doanh nghiệp của hai người nói đang dự định làm gì vào tháng Sáu?","opts":["Expand a space","Take product inventory","Plan an annual sale","Change a window display"],"vi":["Mở rộng một không gian","Kiểm kê hàng hóa","Lên kế hoạch cho một đợt giảm giá hằng năm","Thay đổi trưng bày cửa sổ"],"ans":"A"},{"n":33,"q":"Where do the speakers most likely work?","qvi":"Hai người nói có khả năng làm việc ở đâu nhất?","opts":["At a dance studio","At a culinary school","At a music shop","At an arts and crafts store"],"vi":["Tại một phòng tập khiêu vũ","Tại một trường dạy nấu ăn","Tại một cửa hàng nhạc cụ","Tại một cửa hàng đồ thủ công mỹ nghệ"],"ans":"C"},{"n":34,"q":"What does the man say he would like to do by the end of the year?","qvi":"Người đàn ông nói rằng anh ấy muốn làm điều gì trước cuối năm?","opts":["Advertise a contest","Offer private lessons","Increase operating hours","Provide repair services"],"vi":["Quảng bá một cuộc thi","Cung cấp các buổi học riêng","Tăng giờ mở cửa","Cung cấp dịch vụ sửa chữa"],"ans":"B"}],"a":"E26-T10-32-34.mp3"},{"ns":[35,37],"script":[["M","Hi. I'm working on renovating the lobby of my office, and I'd like to get some paint for the walls.","Chào. Tôi đang cải tạo sảnh văn phòng và muốn mua một ít sơn cho các bức tường."],["W","Sure. What do you have in mind?","Vâng. Anh đang nghĩ đến màu gì?"],["M","Well, I want to paint the walls with one of the colors from our new logo, either green or red.","À, tôi muốn sơn các bức tường bằng một trong các màu từ logo mới của chúng tôi, hoặc màu xanh lá hoặc màu đỏ."],["W","Hmm... I wouldn't choose red—it will fade too fast.","Ừm… Tôi sẽ không chọn màu đỏ—nó sẽ phai quá nhanh."],["M","Oh, OK. Then let's go with green.","Ồ, được rồi. Vậy thì chúng ta chọn màu xanh lá."],["W","Do you have a copy of the logo with you? If I have the image, I can mix a custom paint to match it.","Anh có mang theo bản logo không? Nếu tôi có hình ảnh, tôi có thể pha sơn theo màu phù hợp."],["M","Actually, I don't.","Thực ra là không."],["W","Well, if you e-mail me a picture of the logo, I can have the paint ready for you by Friday.","Vậy, nếu anh gửi cho tôi một bức ảnh của logo qua email, tôi có thể chuẩn bị sơn cho anh vào thứ Sáu."]],"qs":[{"n":35,"q":"What type of project is the man working on?","qvi":"Người đàn ông đang làm loại dự án nào?","opts":["Restoring a piece of art","Designing a logo","Renovating a lobby","Developing a hair dye"],"vi":["Phục chế một tác phẩm nghệ thuật","Thiết kế một logo","Tân trang lại sảnh đợi","Phát triển một loại thuốc nhuộm tóc"],"ans":"C"},{"n":36,"q":"Why does the woman recommend avoiding the color red?","qvi":"Tại sao người phụ nữ khuyên nên tránh màu đỏ?","opts":["It is expensive to produce.","It fades quickly.","It is too bright.","It is very popular."],"vi":["Sản xuất nó rất tốn kém.","Nó phai màu nhanh.","Nó quá sáng.","Nó rất phổ biến."],"ans":"B"},{"n":37,"q":"What does the woman ask the man to do?","qvi":"Người phụ nữ yêu cầu người đàn ông làm gì?","opts":["Pay a deposit","Send a picture","Test a product","Schedule a consultation"],"vi":["Trả tiền đặt cọc","Gửi một bức ảnh","Kiểm tra thử một sản phẩm","Đặt lịch tư vấn"],"ans":"B"}],"a":"E26-T10-35-37.mp3"},{"ns":[38,40],"script":[["W","Welcome to the Western Airlines customer service desk. How can I assist you?","Chào mừng đến với quầy dịch vụ khách hàng của Western Airlines. Tôi có thể giúp gì cho quý khách?"],["M","Hi. I flew in yesterday from Canada and was told that my luggage was accidentally put on a flight arriving this morning.","Chào. Tôi đã bay đến từ Canada ngày hôm qua và được thông báo rằng hành lý của tôi bị vô tình gửi nhầm sang chuyến bay đến vào sáng nay."],["W","OK. Do you have your boarding pass?","Vâng. Anh có mang theo thẻ lên máy bay không?"],["M","Yes—here it is. Can I go to the unclaimed baggage area and pick up my luggage?","Có—đây ạ. Tôi có thể đến khu vực hành lý thất lạc để lấy hành lý không?"],["W","That area is past security. I can use information on the boarding pass to locate the luggage for you.","Khu vực đó nằm sau kiểm soát an ninh. Tôi có thể dùng thông tin trên thẻ lên máy bay để tìm hành lý cho anh."]],"qs":[{"n":38,"q":"What is the man trying to do?","qvi":"Người đàn ông đang cố gắng làm gì?","opts":["Join a tour group","Pick up some luggage","Call a taxi","Buy some gifts"],"vi":["Tham gia một nhóm tham quan","Nhận lại hành lý","Gọi taxi","Mua vài món quà"],"ans":"B"},{"n":39,"q":"What does the woman ask to see?","qvi":"Người phụ nữ yêu cầu xem gì?","opts":["Photo identification","A valid visa","A customs declaration","A boarding pass"],"vi":["Giấy tờ tùy thân có ảnh","Visa hợp lệ","Tờ khai hải quan","Thẻ lên máy bay"],"ans":"D"},{"n":40,"q":"Why does the woman say, “That area is past security”?","qvi":"Tại sao người phụ nữ nói: “Khu vực đó nằm sau cổng an ninh”?","opts":["To clarify a policy","To express surprise","To reject a request","To describe a floor plan"],"vi":["Để làm rõ một quy định","Để bày tỏ sự ngạc nhiên","Để từ chối một yêu cầu","Để mô tả sơ đồ mặt bằng"],"ans":"C"}],"a":"E26-T10-38-40.mp3"},{"ns":[41,43],"script":[["M","We're so happy to have you join our office as our new dental hygienist, Maria. As you know, you'll be cleaning our patients' teeth before I come in to complete the exam.","Chúng tôi rất vui khi bạn gia nhập văn phòng của chúng tôi với vai trò là nha sĩ vệ sinh răng miệng mới, Maria. Như bạn đã biết, bạn sẽ làm sạch răng cho bệnh nhân trước khi tôi vào để hoàn tất kiểm tra."],["W","I'll also be responsible for updating the patients' files and scheduling their next appointments, right?","Tôi cũng sẽ chịu trách nhiệm cập nhật hồ sơ bệnh nhân và lên lịch hẹn tiếp theo cho họ, đúng không?"],["M","Yes. We use a software program called DentalX for all our patient records. Have you used it before?","Đúng rồi. Chúng tôi sử dụng một phần mềm có tên DentalX cho tất cả hồ sơ bệnh nhân. Bạn đã từng sử dụng nó chưa?"],["W","Yes, I'm familiar with that software.","Có, tôi quen với phần mềm đó."],["M","Great. Also, remember that our office closes every day from twelve to one thirty for lunch, so please be mindful of that when scheduling patients.","Tuyệt. Ngoài ra, hãy nhớ rằng văn phòng của chúng ta đóng cửa mỗi ngày từ 12 giờ đến 1 giờ 30 để nghỉ trưa, nên hãy lưu ý khi lên lịch hẹn cho bệnh nhân."]],"qs":[{"n":41,"q":"Where do the speakers most likely work?","qvi":"Hai người có khả năng làm việc ở đâu nhất?","opts":["At a bookstore","At a marketing firm","At an electronics manufacturer","At a dental office"],"vi":["Tại một hiệu sách","Tại một công ty marketing","Tại nhà máy sản xuất điện tử","Tại phòng khám nha khoa"],"ans":"D"},{"n":42,"q":"What does the woman say she is familiar with?","qvi":"Người phụ nữ nói rằng cô ấy quen thuộc với điều gì?","opts":["A university course","A software program","An industry conference","A safety procedure"],"vi":["Một khóa học đại học","Một phần mềm","Một hội nghị trong ngành","Một quy trình an toàn"],"ans":"B"},{"n":43,"q":"What does the man remind the woman about?","qvi":"Người đàn ông nhắc người phụ nữ về điều gì?","opts":["A lunch break","A dress code","A parking policy","A benefits program"],"vi":["Giờ nghỉ trưa","Quy định trang phục","Chính sách đỗ xe","Chương trình phúc lợi"],"ans":"A"}],"a":"E26-T10-41-43.mp3"},{"ns":[44,46],"script":[["M","Next, I wanted to check with the design team about our water-permeable bricks for walkways. I think the bricks will be popular in areas with water drainage problems. But I'm concerned that the final design won't be ready in time for the trade show.","Tiếp theo, tôi muốn trao đổi với nhóm thiết kế về các viên gạch thấm nước cho lối đi. Tôi nghĩ loại gạch này sẽ được ưa chuộng ở những khu vực có vấn đề về thoát nước. Nhưng tôi lo rằng thiết kế cuối cùng sẽ không kịp hoàn thành cho hội chợ thương mại."],["W1","Right, we still need to finish the durability testing. Camille, how's that going?","Đúng rồi, chúng ta vẫn cần hoàn tất việc kiểm tra độ bền. Camille, tiến độ thế nào rồi?"],["W2","So far, they seem to be as durable as we anticipated. But we still have a few more tests to run.","Cho đến nay, chúng có vẻ bền như chúng ta dự đoán. Nhưng chúng ta vẫn còn một vài bài kiểm tra nữa."],["M","Great. Please keep me posted on your progress. In the meantime, we should start putting together a promotional video to show at our booth at the trade show. Who'd like to help me with that project?","Tuyệt. Hãy cập nhật cho tôi về tiến độ nhé. Trong khi đó, chúng ta nên bắt đầu chuẩn bị một video quảng cáo để trình chiếu tại gian hàng ở hội chợ. Ai muốn giúp tôi thực hiện dự án này?"]],"qs":[{"n":44,"q":"What is the man concerned about?","qvi":"Người đàn ông lo lắng về điều gì?","opts":["A staff shortage","A design budget","A project timeline","A weather forecast"],"vi":["Thiếu nhân sự","Ngân sách thiết kế","Tiến độ dự án","Dự báo thời tiết"],"ans":"C"},{"n":45,"q":"What is Camille working on?","qvi":"Camille đang làm việc trên điều gì?","opts":["Durability testing","Contract negotiations","A marketing presentation","A product manual"],"vi":["Kiểm tra độ bền","Đàm phán hợp đồng","Một bài thuyết trình marketing","Một hướng dẫn sử dụng sản phẩm"],"ans":"A"},{"n":46,"q":"What would the man like assistance with?","qvi":"Người đàn ông muốn được hỗ trợ điều gì?","opts":["Interviewing a job candidate","Making a video","Booking a venue","Packing some materials"],"vi":["Phỏng vấn ứng viên","Làm một video","Đặt một địa điểm tổ chức","Đóng gói một số vật dụng"],"ans":"B"}],"a":"E26-T10-44-46.mp3"},{"ns":[47,49],"script":[["M","Excuse me—officer? Do you happen to know where rideshare drivers park to wait for passengers? It's my first time at this airport.","Xin lỗi—cảnh sát ạ? Ngài có biết các tài xế dịch vụ đi chung xe đậu ở đâu để chờ khách không? Đây là lần đầu tôi đến sân bay này."],["W","Yes. Drive to the pickup area by terminal A. Look out for the orange sign that says \"rideshare.\" I'm sure you'll see other drivers there. By the way, I recommend taking the terminal bypass. That bridge will take you there faster.","Có chứ. Lái xe đến khu vực đón khách bên nhà ga A. Nhìn theo biển màu cam có chữ \"rideshare\". Tôi chắc là bạn sẽ thấy các tài xế khác ở đó. Nhân tiện, tôi khuyên bạn nên đi đường vòng quanh nhà ga. Cây cầu đó sẽ đưa bạn đến nhanh hơn."],["M","Great. Thank you. Oh—is there a fuel station near the airport? My tank is almost empty.","Tuyệt quá. Cảm ơn chị. À—có trạm xăng nào gần sân bay không? Bình xăng của tôi gần hết rồi."],["W","You'll see one by the rental-car lot on your way out.","Bạn sẽ thấy một trạm gần bãi xe thuê xe khi ra khỏi sân bay."]],"qs":[{"n":47,"q":"What most likely is the man’s job?","qvi":"Công việc của người đàn ông có khả năng là gì nhất?","opts":["Gift shop worker","Flight attendant","Security guard","Rideshare driver"],"vi":["Nhân viên cửa hàng quà tặng","Tiếp viên hàng không","Nhân viên an ninh","Tài xế dịch vụ gọi xe"],"ans":"D"},{"n":48,"q":"How does the woman recommend getting to terminal A?","qvi":"Người phụ nữ khuyên nên đến nhà ga A bằng cách nào?","opts":["By taking a shuttle bus","By riding an escalator","By using a bridge","By crossing a street"],"vi":["Bằng xe buýt trung chuyển","Bằng thang cuốn","Bằng cách đi qua một cây cầu","Bằng cách băng qua đường"],"ans":"C"},{"n":49,"q":"What does the woman say is by the rental-car lot?","qvi":"Người phụ nữ nói rằng cạnh bãi cho thuê xe có gì?","opts":["A department store","A bank","A restaurant","A fuel station"],"vi":["Một cửa hàng bách hóa","Một ngân hàng","Một nhà hàng","Một trạm nhiên liệu"],"ans":"D"}],"a":"E26-T10-47-49.mp3"},{"ns":[50,52],"script":[["M","This traffic is really terrible.","Giao thông hôm nay thật tệ."],["W","I know. We've been stuck in this bus for hours now! It's frustrating. I wonder what's going on.","Tôi biết. Chúng ta đã kẹt trong chiếc xe buýt này mấy giờ rồi! Thật bực mình. Tôi tự hỏi chuyện gì đang xảy ra."],["M","I heard the Day Street Bridge is being worked on.","Tôi nghe nói cầu Day Street đang được sửa chữa."],["W","Oh, really? I didn't know that.","Thật sao? Tôi không biết điều đó."],["M","Yes. I think it's down to just one lane for the next couple of weeks.","Đúng rồi. Tôi nghĩ hiện chỉ còn một làn xe trong vài tuần tới."],["W","That's good to know. I'll take the train into the city tomorrow instead, so I won't be late for my appointments.","Biết vậy cũng tốt. Ngày mai tôi sẽ đi tàu vào thành phố thay vì đi xe, để không bị trễ các cuộc hẹn."]],"qs":[{"n":50,"q":"Where are the speakers?","qvi":"Hai người đang ở đâu?","opts":["On a bus","On a boat","At a car dealership","At a train station"],"vi":["Trên xe buýt","Trên thuyền","Tại đại lý ô tô","Tại ga tàu"],"ans":"A"},{"n":51,"q":"Why does the man say, “I heard the Day Street Bridge is being worked on”?","qvi":"Tại sao người đàn ông nói: “Tôi nghe nói cầu Day Street đang sửa chữa”?","opts":["To confirm some information","To make a correction","To explain a delay","To recommend leaving early"],"vi":["Để xác nhận thông tin","Để chỉnh lại thông tin","Để giải thích một sự chậm trễ","Để khuyên nên đi sớm"],"ans":"C"},{"n":52,"q":"What does the woman say she will do tomorrow?","qvi":"Người phụ nữ nói rằng cô ấy sẽ làm gì vào ngày mai?","opts":["Purchase a monthly pass","Download a map","Check a schedule","Use alternate transportation"],"vi":["Mua vé tháng","Tải xuống một bản đồ","Kiểm tra lịch trình","Sử dụng phương tiện thay thế"],"ans":"D"}],"a":"E26-T10-50-52.mp3"},{"ns":[53,55],"script":[["W","Girard Electronics. How can I help you?","Girard Electronics. Tôi có thể giúp gì cho quý khách?"],["M","Hi. I bought a camera from your store last week, but I'm having trouble with it now.","Chào. Tôi đã mua một chiếc máy ảnh từ cửa hàng của bạn tuần trước, nhưng bây giờ tôi gặp sự cố với nó."],["W","What's the problem?","Vấn đề là gì vậy?"],["M","Well, I changed the lens from the standard to a telephoto one today, and now an error message pops up on the LCD screen.","Hôm nay tôi đã thay ống kính từ ống kính tiêu chuẩn sang ống kính tele, và bây giờ một thông báo lỗi xuất hiện trên màn hình LCD."],["W","Hmm. I'm sorry, but I can't know for sure without looking at it, as it could be caused by a few things.","Ừm… Tôi xin lỗi, nhưng tôi không thể chắc chắn nếu không xem trực tiếp, vì nguyên nhân có thể do một vài thứ."],["M","I could come by this afternoon.","Tôi có thể ghé qua vào chiều nay."],["W","OK. I won't be here, but one of the other employees can definitely help you. Let me just write a note down.","Được thôi. Tôi sẽ không có ở đây, nhưng một trong những nhân viên khác chắc chắn có thể giúp anh. Để tôi ghi chú lại."],["M","Thanks.","Cảm ơn."]],"qs":[{"n":53,"q":"What product is the man calling about?","qvi":"Người đàn ông đang gọi về sản phẩm nào?","opts":["A portable game system","A printer","A camera","A tablet computer"],"vi":["Máy chơi game cầm tay","Máy in","Máy ảnh","Máy tính bảng"],"ans":"C"},{"n":54,"q":"Why will the man go to a store?","qvi":"Tại sao người đàn ông sẽ đến cửa hàng?","opts":["To purchase an extended warranty","To resolve a problem","To receive a refund","To pick up some accessories"],"vi":["Để mua bảo hành mở rộng","Để giải quyết một vấn đề","Để nhận tiền hoàn","Để lấy một số phụ kiện"],"ans":"B"},{"n":55,"q":"Who will the woman most likely give a note to?","qvi":"Người phụ nữ có khả năng sẽ đưa ghi chú cho ai?","opts":["A parking attendant","A product designer","A customer","A colleague"],"vi":["Nhân viên bãi đỗ xe","Nhà thiết kế sản phẩm","Khách hàng","Đồng nghiệp"],"ans":"D"}],"a":"E26-T10-53-55.mp3"},{"ns":[56,58],"script":[["M","Hi. I have a delivery of medical supplies addressed to Eun-Mi Park.","Chào. Tôi có một lô vật tư y tế gửi đến Eun-Mi Park."],["W1","That's Eun-Mi sitting at the desk over there.","Người đang ngồi tại bàn kia là Eun-Mi đó."],["W2","I'm Eun-Mi, I've been waiting for these sterile pads and bandages.","Tôi là Eun-Mi, tôi đang chờ các miếng gạc và băng vô trùng này."],["M","Great. I just need you to sign here to confirm the delivery.","Tuyệt. Tôi chỉ cần bạn ký vào đây để xác nhận việc giao hàng."],["W2","OK, sure. Oh, Claudia, do you have time to help me carry these boxes to the storage closet?","Được, chắc chắn rồi. À, Claudia, bạn có thời gian giúp tôi mang mấy thùng này vào tủ lưu trữ không?"],["W1","Of course. I have a patient at one o'clock, but I have a few minutes now.","Dĩ nhiên. Tôi có một bệnh nhân lúc 1 giờ, nhưng giờ tôi có vài phút rảnh."]],"qs":[{"n":56,"q":"Where do the women most likely work?","qvi":"Hai người phụ nữ có khả năng làm việc ở đâu nhất?","opts":["At a medical clinic","At a department store","At a hotel","At a manufacturing plant"],"vi":["Tại phòng khám","Tại cửa hàng bách hóa","Tại khách sạn","Tại nhà máy"],"ans":"A"},{"n":57,"q":"What does the man request?","qvi":"Người đàn ông yêu cầu điều gì?","opts":["A schedule","A list of employees","A facility tour","A signature"],"vi":["Một lịch trình","Danh sách nhân viên","Một chuyến tham quan cơ sở","Một chữ ký"],"ans":"D"},{"n":58,"q":"What will the women most likely do next?","qvi":"Hai người phụ nữ có khả năng sẽ làm gì tiếp theo?","opts":["Attend a staff meeting","Check some reports","Take a lunch break","Move some boxes"],"vi":["Tham dự cuộc họp nhân viên","Kiểm tra vài báo cáo","Nghỉ trưa","Di chuyển vài thùng hàng"],"ans":"D"}],"a":"E26-T10-56-58.mp3"},{"ns":[59,61],"script":[["M","Dula Commercial Cleaners. How can I help you?","Dula Commercial Cleaners. Tôi có thể giúp gì cho quý khách?"],["W","Hi, I'm running a new bed-and-breakfast in town, and I'm looking for a company to wash, dry, and fold our linens. I have a few questions.","Chào, tôi đang vận hành một nhà nghỉ kiểu bed-and-breakfast mới trong thị trấn, và tôi đang tìm một công ty để giặt, sấy và gấp đồ vải. Tôi có vài câu hỏi."],["M","Sure.","Vâng, được."],["W","How do you work in terms of scheduling?","Quý công ty làm việc thế nào về lịch trình?"],["M","We work around the clock to guarantee a 24-hour turnaround. We run three separate shifts.","Chúng tôi làm việc 24/7 để đảm bảo hoàn thành trong vòng 24 giờ. Chúng tôi có ba ca làm việc riêng biệt."],["W","That's good to hear.","Nghe tốt quá."],["M","Could I ask where you're located?","Tôi có thể hỏi quý vị ở đâu không?"],["W","Oh, we're at 647 Pond Street.","À, chúng tôi ở 647 Pond Street."],["M","In that case, pickup and delivery will not add to your service charge, since you're within a fifteen-kilometer radius of our company.","Trong trường hợp đó, việc lấy và giao hàng sẽ không tính thêm phí dịch vụ, vì quý vị nằm trong bán kính 15km của công ty chúng tôi."]],"qs":[{"n":59,"q":"Why is the woman calling?","qvi":"Tại sao người phụ nữ gọi điện?","opts":["To inquire about a service","To arrange an interview","To request a refund","To make a reservation"],"vi":["Để hỏi về một dịch vụ","Để sắp xếp một buổi phỏng vấn","Để yêu cầu hoàn tiền","Để đặt chỗ"],"ans":"A","note":"Lời thoại trong đáp án gốc bị ghi ngược nhãn người nói (W/M). Theo câu hỏi trong đề, người đàn ông là nhân viên Dula Commercial Cleaners nghe máy, còn người phụ nữ là khách gọi đến hỏi dịch vụ, nên ở đây đã đổi lại nhãn M/W cho đúng."},{"n":60,"q":"What does the man say about his company?","qvi":"Người đàn ông nói gì về công ty của anh ấy?","opts":["It ensures customer satisfaction.","It has been in business for three years.","It operates 24 hours a day.","It is family owned."],"vi":["Công ty đảm bảo sự hài lòng của khách hàng.","Công ty đã hoạt động được ba năm.","Công ty hoạt động 24 giờ mỗi ngày.","Công ty là doanh nghiệp gia đình."],"ans":"C"},{"n":61,"q":"According to the man, what will his company provide?","qvi":"Theo người đàn ông, công ty của anh ấy sẽ cung cấp điều gì?","opts":["Directions to a facility","Pickup and delivery","A member discount","An updated receipt"],"vi":["Chỉ đường đến cơ sở","Dịch vụ nhận và giao hàng","Giảm giá cho thành viên","Hóa đơn cập nhật"],"ans":"B"}],"a":"E26-T10-59-61.mp3"},{"ns":[62,64],"script":[["M","Welcome to Centerville Fitness Center.","Chào mừng đến với Trung tâm Thể hình Centerville."],["W","Hi. I hear you're having a fund-raising campaign.","Chào. Tôi nghe nói trung tâm đang tổ chức một chiến dịch gây quỹ."],["M","Yes, today's the start of our annual fund-raiser. All proceeds go toward the purchase of new sports equipment for the center. You'll be entered into a raffle to win a prize based on your donation amount.","Đúng rồi, hôm nay là ngày khởi động gây quỹ thường niên của chúng tôi. Toàn bộ số tiền thu được sẽ dùng để mua thiết bị thể thao mới cho trung tâm. Quý vị sẽ được tham gia rút thăm trúng thưởng dựa trên số tiền đóng góp."],["W","Sounds great. I'd like to donate $50.","Nghe tuyệt quá. Tôi muốn đóng góp 50 đô la."],["M","Wonderful! Just fill out the donation form, and I'll get you your raffle ticket.","Tuyệt vời! Chỉ cần điền vào mẫu đóng góp, và tôi sẽ đưa vé rút thăm cho bạn."],["W","How will I find out if I won?","Làm thế nào tôi biết mình có trúng thưởng không?"],["M","The drawing's on Friday, and winners will receive a phone call from the organizers.","Buổi rút thăm sẽ diễn ra vào thứ Sáu, và những người trúng thưởng sẽ nhận được cuộc gọi từ ban tổ chức."]],"qs":[{"n":62,"q":"Where is the conversation taking place?","qvi":"Cuộc hội thoại diễn ra ở đâu?","opts":["At a department store","At a fitness center","At a library","At a restaurant"],"vi":["Ở cửa hàng bách hóa","Ở trung tâm thể hình","Ở thư viện","Ở nhà hàng"],"ans":"B"},{"n":63,"q":"Look at the graphic. Which prize could the woman win?","qvi":"Nhìn vào biểu đồ. Người phụ nữ có thể thắng giải nào?","opts":["A bicycle","Theater tickets","A camera","A weekend getaway"],"vi":["Xe đạp","Vé xem kịch","Máy ảnh","Chuyến nghỉ cuối tuần"],"ans":"A"},{"n":64,"q":"How will winners be notified?","qvi":"Người thắng cuộc sẽ được thông báo bằng cách nào?","opts":["By telephone","By text message","By e-mail","By letter"],"vi":["Bằng điện thoại","Bằng tin nhắn","Bằng email","Bằng thư"],"ans":"A"}],"a":"E26-T10-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["W","Hi. Some of us at work decided to get together to buy some flowers here. They're for a colleague who just received a promotion.","Chào. Một vài người trong công ty chúng tôi quyết định cùng nhau mua hoa ở đây. Hoa dành cho một đồng nghiệp vừa được thăng chức."],["M","We have a nice selection of arrangements that are appropriate for an event like that. Here's a list of the most popular, in a range of prices.","Chúng tôi có nhiều mẫu hoa đẹp phù hợp cho sự kiện như vậy. Đây là danh sách những mẫu phổ biến nhất, với nhiều mức giá khác nhau."],["W","Oh, I have enough money for the Harmony arrangement. Can you make that while I wait?","À, tôi có đủ tiền cho mẫu Harmony. Bạn có thể làm ngay trong khi tôi chờ không?"],["M","Sure, I'll have it made for you now. And will you want a greeting card to go with that?","Chắc chắn rồi, tôi sẽ làm ngay cho bạn. Và bạn có muốn kèm theo một tấm thiệp không?"],["W","Actually, no card is needed. We already have one that we've all signed.","Thực ra không cần thiệp. Chúng tôi đã có một tấm mà tất cả mọi người đã ký rồi."]],"qs":[{"n":65,"q":"Why does the woman want to purchase flowers?","qvi":"Tại sao người phụ nữ muốn mua hoa?","opts":["To decorate a building lobby","To observe a company anniversary","To mark the completion of a work project","To celebrate a coworker's promotion"],"vi":["Để trang trí sảnh tòa nhà","Để kỷ niệm ngày thành lập công ty","Để đánh dấu hoàn thành dự án","Để chúc mừng đồng nghiệp thăng chức"],"ans":"D"},{"n":66,"q":"Look at the graphic. How much will the woman pay for the flower arrangement?","qvi":"Nhìn vào biểu đồ. Người phụ nữ sẽ trả bao nhiêu cho bó hoa?","opts":["$45","$60","$75","$110"],"vi":["$45","$60","$75","$110"],"ans":"C"},{"n":67,"q":"What additional item do the speakers discuss?","qvi":"Hai người nói thảo luận thêm món gì?","opts":["A chocolate bar","A greeting card","A bunch of balloons","A decorative bow"],"vi":["Thanh socola","Thiệp chúc mừng","Chùm bóng bay","Nơ trang trí"],"ans":"B"}],"a":"E26-T10-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["W","Hi, Andrew. How have you enjoyed your first week here at Jebreen Farms?","Chào Andrew. Bạn cảm thấy thế nào trong tuần đầu tiên ở Jebreen Farms?"],["M","It's been great. I'm definitely learning a lot about commercial agriculture.","Rất tuyệt. Tôi chắc chắn học được nhiều điều về nông nghiệp thương mại."],["W","So glad to hear that. Let's go over to where we'll store the upcoming corn harvest. As you know, we sell a lot of corn as feed for livestock farms in the area.","Thật vui khi nghe vậy. Chúng ta hãy đi đến nơi sẽ lưu trữ vụ thu hoạch ngô sắp tới. Như bạn biết, chúng tôi bán rất nhiều ngô làm thức ăn cho các trang trại chăn nuôi trong khu vực."],["M","Yes. I'm eager to get some hands-on experience with drying and storing the corn.","Vâng. Tôi háo hức muốn có kinh nghiệm thực tế về việc sấy và lưu trữ ngô."],["W","Good. If the process is done right, it can be stored for long periods, but conditions inside the grain bin have to be just right.","Tốt. Nếu quá trình này được thực hiện đúng cách, ngô có thể được lưu trữ trong thời gian dài, nhưng điều kiện bên trong silo phải hoàn hảo."],["M","How long will the drying process take after the harvest?","Quá trình sấy sau thu hoạch sẽ mất bao lâu?"],["W","About four to six weeks.","Khoảng bốn đến sáu tuần."]],"qs":[{"n":68,"q":"Who most likely is the man?","qvi":"Người đàn ông có khả năng là ai?","opts":["A new employee","An investor","A university professor","A business owner"],"vi":["Nhân viên mới","Nhà đầu tư","Giáo sư đại học","Chủ doanh nghiệp"],"ans":"A"},{"n":69,"q":"Look at the graphic. Where will the upcoming harvest be stored?","qvi":"Nhìn vào biểu đồ. Vụ thu hoạch sắp tới sẽ được lưu trữ ở đâu?","opts":["Bin 1","Bin 2","Bin 3","Bin 4"],"vi":["Thùng 1","Thùng 2","Thùng 3","Thùng 4"],"ans":"C"},{"n":70,"q":"What does the man ask about?","qvi":"Người đàn ông hỏi về điều gì?","opts":["When some work will begin","How long a process will take","Who will buy a product","When a delivery will arrive"],"vi":["Khi nào một công việc sẽ bắt đầu","Một quy trình sẽ mất bao lâu","Ai sẽ mua sản phẩm","Khi nào hàng giao đến"],"ans":"B"}],"a":"E26-T10-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["M","Welcome to your first day of work at Schneider Technology. Our navigation devices enable vehicles to direct drivers to their destination by taking into consideration a variety of factors such as distance, weather, and traffic conditions. Moritz Schneider, the president of the company, will be here in person at ten o'clock to welcome you and tell you all about the company's history. But first, I'll help you set up your computer accounts. Cybersecurity is very important to us, so we've added extra steps to verify your identity.","Chào mừng bạn đến với ngày làm việc đầu tiên tại Schneider Technology. Các thiết bị định vị của chúng tôi giúp phương tiện hướng dẫn lái xe đến điểm đến, đồng thời xem xét nhiều yếu tố như khoảng cách, thời tiết và tình trạng giao thông. Moritz Schneider, chủ tịch công ty, sẽ có mặt trực tiếp lúc mười giờ để chào mừng bạn và giới thiệu về lịch sử công ty. Nhưng trước tiên, tôi sẽ giúp bạn thiết lập tài khoản máy tính. An ninh mạng rất quan trọng đối với chúng tôi, vì vậy chúng tôi đã thêm các bước xác minh bổ sung để đảm bảo danh tính của bạn."]],"qs":[{"n":71,"q":"What does Schneider Technology produce?","qvi":"Schneider Technology sản xuất gì?","opts":["Automobile engines","Audio equipment","Navigation devices","Medical equipment"],"vi":["Động cơ ô tô","Thiết bị âm thanh","Thiết bị dẫn đường","Thiết bị y tế"],"ans":"C"},{"n":72,"q":"Who will the listeners meet with at ten o’clock?","qvi":"Người nghe sẽ gặp ai vào lúc 10 giờ?","opts":["An important client","The company president","The head of security","A government official"],"vi":["Một khách hàng quan trọng","Chủ tịch công ty","Trưởng bộ phận an ninh","Một quan chức chính phủ"],"ans":"B"},{"n":73,"q":"What will the listeners do next?","qvi":"Người nghe sẽ làm gì tiếp theo?","opts":["Set up their computer accounts","Receive their security badges","Tour a facility","Watch a demonstration"],"vi":["Cài đặt tài khoản máy tính","Nhận thẻ an ninh","Tham quan cơ sở","Xem một buổi trình diễn"],"ans":"A"}],"a":"E26-T10-71-73.mp3"},{"ns":[74,76],"script":[["W","Good afternoon. This is Captain Jeong giving you a heads-up on our plane's departure status. As you can see, there's a light dusting of snow on the ground. Air traffic control is holding us here at the gate while the snowplows clear the runway. It should take just a few minutes, then we'll be cleared for takeoff. I apologize for the delay. And a reminder: please ensure that children remain seated with their seat belts fastened throughout the flight.","Chào buổi chiều. Tôi là cơ trưởng Jeong, thông báo tình trạng khởi hành của chuyến bay. Như quý vị có thể thấy, trên mặt đất có một lớp tuyết mỏng. Kiểm soát không lưu đang giữ chúng ta tại cổng trong khi xe dọn tuyết làm sạch đường băng. Quá trình này chỉ mất vài phút, sau đó chúng ta sẽ được phép cất cánh. Tôi xin lỗi vì sự chậm trễ. Và xin nhắc lại: vui lòng đảm bảo trẻ em ngồi yên tại chỗ với dây an toàn thắt chặt trong suốt chuyến bay."]],"qs":[{"n":74,"q":"Where does the announcement most likely take place?","qvi":"Thông báo khả năng cao diễn ra ở đâu?","opts":["On a train","On a ship","On an airplane","On a bus"],"vi":["Trên tàu hỏa","Trên tàu thủy","Trên máy bay","Trên xe buýt"],"ans":"C"},{"n":75,"q":"What is causing a delay?","qvi":"Điều gì đang gây ra sự chậm trễ?","opts":["Weather conditions","Heavy traffic","Malfunctioning equipment","A staff shortage"],"vi":["Điều kiện thời tiết","Giao thông đông đúc","Thiết bị bị trục trặc","Thiếu nhân viên"],"ans":"A"},{"n":76,"q":"What does the speaker remind the listeners to do?","qvi":"Người nói nhắc người nghe làm gì?","opts":["Store luggage in overhead compartments","Show tickets to an attendant","Avoid eating and drinking","Keep children in their seats"],"vi":["Cất hành lý vào khoang phía trên","Xuất trình vé cho nhân viên","Tránh ăn uống","Giữ trẻ em ngồi yên tại chỗ"],"ans":"D"}],"a":"E26-T10-74-76.mp3"},{"ns":[77,79],"script":[["M","Good morning, and thanks for tuning in to News at Four. We've just learned that the Natural Zoological Museum, one of Springfield's most popular museums, will soon close for a renovation project. To those who are planning to visit the exhibits in person, be aware that the workers arrive in six weeks. But if you miss that window, don't worry. You can still visit the museum virtually during the renovation period. Video tours will soon be available on the museum's Web site, and videos showing the progress of the project will also be posted regularly.","Chào buổi sáng, và cảm ơn quý vị đã theo dõi bản Tin tức Lúc Bốn Giờ. Chúng tôi vừa nhận được thông tin rằng Bảo tàng Động vật Học Tự nhiên, một trong những bảo tàng nổi tiếng nhất của Springfield, sẽ sớm đóng cửa để thực hiện dự án cải tạo. Những ai có kế hoạch tham quan trực tiếp các triển lãm, xin lưu ý rằng công nhân sẽ bắt đầu đến sau sáu tuần nữa. Nhưng nếu bạn bỏ lỡ khoảng thời gian đó, đừng lo lắng. Bạn vẫn có thể tham quan bảo tàng trực tuyến trong suốt thời gian cải tạo. Các chuyến tham quan bằng video sẽ sớm có trên trang web của bảo tàng, và các video cập nhật tiến độ dự án cũng sẽ được đăng thường xuyên."]],"qs":[{"n":77,"q":"What project does the speaker mention?","qvi":"Người nói đề cập đến dự án nào?","opts":["The addition of traffic lights","The renovation of a museum","The expansion of a sports stadium","The construction of a bridge"],"vi":["Lắp thêm đèn giao thông","Tân trang một bảo tàng","Mở rộng sân vận động","Xây dựng một cây cầu"],"ans":"B"},{"n":78,"q":"What does the speaker imply when he says, “the workers arrive in six weeks”?","qvi":"Người nói ngụ ý điều gì khi nói “các công nhân sẽ đến trong sáu tuần nữa”?","opts":["The listeners should attend a welcome reception.","Some training will be offered soon.","The listeners have a limited amount of time.","A hiring need has already been fulfilled."],"vi":["Người nghe nên tham dự buổi chào đón","Sẽ có một khóa đào tạo sớm","Người nghe chỉ còn ít thời gian","Nhu cầu tuyển dụng đã được đáp ứng"],"ans":"C"},{"n":79,"q":"What does the speaker assure the listeners of?","qvi":"Người nói đảm bảo với người nghe điều gì?","opts":["Videos will be available online.","Prices will not increase.","Roads will remain open.","A schedule will not change."],"vi":["Video sẽ có trên mạng","Giá sẽ không tăng","Đường sá sẽ vẫn mở","Lịch trình sẽ không thay đổi"],"ans":"A"}],"a":"E26-T10-77-79.mp3"},{"ns":[80,82],"script":[["W","At Jin-Ah's Jewelers, we create custom-made jewelry that showcases your style and celebrates the most important moments in your life. Meet for a video consultation with one of our talented artists, who can design earrings, bracelets, and more, just for you. And unlike our competitors, who only send you a sketch, we'll send you a simple metal prototype. You can approve or request changes to the sample before your final piece is made. To get your order started, just enter your information on our Web site, and one of our designers will contact you.","Tại Jin-Ah's Jewelers, chúng tôi tạo ra những món trang sức làm theo yêu cầu, thể hiện phong cách của bạn và kỷ niệm những khoảnh khắc quan trọng nhất trong cuộc sống. Hẹn gặp trực tuyến với một trong những nghệ nhân tài năng của chúng tôi, người có thể thiết kế bông tai, vòng tay và nhiều món khác chỉ dành riêng cho bạn. Và khác với các đối thủ cạnh tranh, những người chỉ gửi bạn bản phác thảo, chúng tôi sẽ gửi một mẫu kim loại đơn giản. Bạn có thể duyệt hoặc yêu cầu thay đổi mẫu trước khi sản phẩm cuối cùng được chế tác. Để bắt đầu đơn hàng, chỉ cần nhập thông tin của bạn trên trang web, và một trong những nhà thiết kế của chúng tôi sẽ liên hệ với bạn."]],"qs":[{"n":80,"q":"What does the company make?","qvi":"Công ty sản xuất gì?","opts":["Clothing","Jewelry","Eyeglass frames","Ceramic vases"],"vi":["Quần áo","Trang sức","Gọng kính","Lọ gốm sứ"],"ans":"B"},{"n":81,"q":"How is the company different from its competitors?","qvi":"Công ty khác đối thủ như thế nào?","opts":["It uses eco-friendly materials.","It offers online consultations.","It promises one-week delivery.","It provides product prototypes."],"vi":["Sử dụng vật liệu thân thiện môi trường","Cung cấp tư vấn trực tuyến","Hứa giao hàng trong một tuần","Cung cấp mẫu sản phẩm thử"],"ans":"D"},{"n":82,"q":"Why should the listeners visit a Web site?","qvi":"Người nghe nên truy cập trang web để làm gì?","opts":["To enter a contest","To receive a discount code","To start an order","To view some photographs"],"vi":["Tham gia cuộc thi","Nhận mã giảm giá","Bắt đầu một đơn đặt hàng","Xem một số hình ảnh"],"ans":"C"}],"a":"E26-T10-80-82.mp3"},{"ns":[83,85],"script":[["M","On today's episode of our podcast, we'll be talking to Rebecca Taylor, the chair and founder of Real Estate Investments LLC. As we know, the housing market has had its ups and downs in recent years. Ms. Taylor is widely known for her ability to correctly predict trends in the real estate market. Her opinion is highly valued. We are fortunate to be able to interview her today before she travels to the National Real Estate Conference in Chicago, where she has been invited to deliver the keynote speech.","Trong tập podcast hôm nay, chúng tôi sẽ trò chuyện với Rebecca Taylor, chủ tịch kiêm người sáng lập Real Estate Investments LLC. Như chúng ta biết, thị trường bất động sản đã trải qua những thăng trầm trong những năm gần đây. Bà Taylor nổi tiếng với khả năng dự đoán chính xác các xu hướng trên thị trường bất động sản. Ý kiến của bà được đánh giá rất cao. Chúng tôi thật may mắn khi có cơ hội phỏng vấn bà hôm nay trước khi bà tham dự Hội nghị Bất động sản Quốc gia tại Chicago, nơi bà được mời đọc bài phát biểu chính."]],"qs":[{"n":83,"q":"What is the focus of the podcast?","qvi":"Chủ đề chính của podcast là gì?","opts":["Real estate","Food services","Graphic design","Tourism"],"vi":["Bất động sản","Dịch vụ ăn uống","Thiết kế đồ họa","Du lịch"],"ans":"A"},{"n":84,"q":"What does the speaker say Rebecca Taylor is known for?","qvi":"Người nói cho biết Rebecca Taylor nổi tiếng với điều gì?","opts":["Organizing workshops","Providing technology support","Promoting products","Predicting market trends"],"vi":["Tổ chức các buổi hội thảo","Cung cấp hỗ trợ kỹ thuật","Quảng bá sản phẩm","Dự đoán xu hướng thị trường"],"ans":"D"},{"n":85,"q":"According to the speaker, what will Ms. Taylor do in Chicago?","qvi":"Theo người nói, cô Taylor sẽ làm gì ở Chicago?","opts":["Release a book","Speak at a conference","Appear on television","Announce an award winner"],"vi":["Phát hành một cuốn sách","Nói chuyện tại hội nghị","Xuất hiện trên truyền hình","Công bố người chiến thắng giải thưởng"],"ans":"B"}],"a":"E26-T10-83-85.mp3"},{"ns":[86,88],"script":[["W","The topic for today's workshop is writing business correspondence. Business correspondence has different guidelines than the informal type of writing you use when writing to a friend. For example, when writing to a friend you might address them by their first name or perhaps include emojis. You know—symbols like smiley faces that are commonly used to express feelings. However, emojis are considered inappropriate in business writing. Also, business correspondence should always include the recipient's title and last name. Remember, we don't want to offend our clients. Now, I will project some slides of informally worded e-mails. In your notebooks, rewrite the e-mails using wording and style appropriate for business correspondence.","Chủ đề của buổi hội thảo hôm nay là viết thư từ công việc. Thư từ công việc có những hướng dẫn khác với cách viết không chính thức mà bạn dùng khi viết cho bạn bè. Ví dụ, khi viết cho bạn bè, bạn có thể gọi họ bằng tên riêng hoặc thậm chí dùng emoji—những biểu tượng như mặt cười thường được dùng để thể hiện cảm xúc. Tuy nhiên, emoji được coi là không phù hợp trong văn bản công việc. Ngoài ra, thư từ công việc luôn phải bao gồm chức danh và họ của người nhận. Hãy nhớ, chúng ta không muốn gây khó chịu cho khách hàng. Bây giờ, tôi sẽ trình chiếu một số email được viết theo cách không chính thức. Trong sổ tay của mình, hãy viết lại các email đó sử dụng cách diễn đạt và phong cách phù hợp với thư từ công việc."]],"qs":[{"n":86,"q":"What is the main topic of the workshop?","qvi":"Chủ đề chính của buổi hội thảo là gì?","opts":["Creating new advertisements","Designing Web sites","Giving effective presentations","Writing for business communication"],"vi":["Tạo quảng cáo mới","Thiết kế trang web","Thuyết trình hiệu quả","Viết trong giao tiếp doanh nghiệp"],"ans":"D"},{"n":87,"q":"Why does the speaker say, “we don’t want to offend our clients”?","qvi":"Tại sao người nói nói “chúng ta không muốn làm phật lòng khách hàng”?","opts":["To stress the importance of some guidelines","To announce a change","To request feedback","To propose that a meeting be rescheduled"],"vi":["Để nhấn mạnh tầm quan trọng của các hướng dẫn","Để thông báo một thay đổi","Để yêu cầu phản hồi","Để đề nghị dời cuộc họp"],"ans":"A"},{"n":88,"q":"What are the listeners asked to do?","qvi":"Người nghe được yêu cầu làm gì?","opts":["Update some contact information","Rewrite some e-mails","Do an online search","Download some software"],"vi":["Cập nhật một số thông tin liên lạc","Viết lại một số email","Tìm kiếm trực tuyến","Tải phần mềm"],"ans":"B"}],"a":"E26-T10-86-88.mp3"},{"ns":[89,91],"script":[["W","In the world of business, athletic retailer Clementine Stores has filed a complaint against software firm Stephion. Clementine claims that the Stephion logo, which is round and orange, is too similar to its own. However, a Stephion public relations representative, Friedrich Weber, responded by saying that the two company logos were similar but not similar enough to confuse consumers. Furthermore, Weber maintained that the Stephion design was not problematic because the two companies are in completely different markets. Our in-house legal analyst will join us next.","Trong thế giới kinh doanh, chuỗi cửa hàng thể thao Clementine Stores đã nộp đơn khiếu nại đối với công ty phần mềm Stephion. Clementine cho rằng logo của Stephion, có hình tròn và màu cam, quá giống với logo của họ. Tuy nhiên, đại diện quan hệ công chúng của Stephion, Friedrich Weber, trả lời rằng hai logo có sự tương đồng nhưng không đủ để làm khách hàng nhầm lẫn. Hơn nữa, Weber khẳng định thiết kế của Stephion không gây vấn đề vì hai công ty hoạt động hoàn toàn trong các thị trường khác nhau. Chuyên viên phân tích pháp lý nội bộ của chúng tôi sẽ tham gia cùng chúng tôi ngay sau đây."]],"qs":[{"n":89,"q":"Why is Clementine Stores in the news report?","qvi":"Tại sao Clementine Stores xuất hiện trên bản tin?","opts":["It filed a complaint.","It closed some factories.","It merged with another company.","It started an internship program."],"vi":["Họ đã nộp đơn khiếu nại","Họ đã đóng cửa một số nhà máy","Họ đã sáp nhập với công ty khác","Họ đã khởi động một chương trình thực tập"],"ans":"A"},{"n":90,"q":"According to the report, what do the companies have in common?","qvi":"Theo bản tin, các công ty có điểm gì giống nhau?","opts":["They have international clients.","They are family-owned businesses.","They sell athletic clothing.","They have similar logos."],"vi":["Có khách hàng quốc tế","Là doanh nghiệp gia đình","Bán quần áo thể thao","Có logo tương tự"],"ans":"D"},{"n":91,"q":"Who is Friedrich Weber?","qvi":"Friedrich Weber là ai?","opts":["A news reporter","A public relations associate","A corporate attorney","A graphic designer"],"vi":["Một phóng viên tin tức","Một nhân viên quan hệ công chúng","Một luật sư doanh nghiệp","Một nhà thiết kế đồ họa"],"ans":"B"}],"a":"E26-T10-89-91.mp3"},{"ns":[92,94],"script":[["M","Thanks for coming in early this morning. I wanted to update you on the café refrigerators that our customers use. We recently installed a new temperature monitoring system. I've noticed that every increase in temperature can be traced to the refrigerator doors being left open for extended periods of time. This is alarming because it compromises the freshness and safety of our food. We all know that customers often take a while to make their selection. I'll be meeting with the management team to discuss ways to address this.","Cảm ơn các bạn đã đến sớm sáng nay. Tôi muốn cập nhật cho các bạn về tủ lạnh tại quán cà phê mà khách hàng thường sử dụng. Gần đây, chúng tôi đã lắp đặt một hệ thống giám sát nhiệt độ mới. Tôi nhận thấy rằng mỗi lần nhiệt độ tăng đều có nguyên nhân từ việc cửa tủ lạnh bị để mở trong thời gian dài. Điều này đáng lo ngại vì nó ảnh hưởng đến độ tươi và an toàn của thực phẩm. Chúng ta đều biết rằng khách hàng thường mất một lúc để chọn món. Tôi sẽ họp với ban quản lý để thảo luận các cách giải quyết vấn đề này."]],"qs":[{"n":92,"q":"Where does the speaker most likely work?","qvi":"Người nói nhiều khả năng làm việc ở đâu?","opts":["At a café","At an appliance store","At a food manufacturing plant","At a repair shop"],"vi":["Quán cà phê","Cửa hàng điện gia dụng","Nhà máy chế biến thực phẩm","Tiệm sửa chữa"],"ans":"A"},{"n":93,"q":"What is the speaker concerned about?","qvi":"Người nói lo lắng điều gì?","opts":["Package labeling","Increased temperature readings","Product costs","Limited business hours"],"vi":["Nhãn bao bì","Chỉ số nhiệt độ tăng","Chi phí sản phẩm","Giờ mở cửa hạn chế"],"ans":"B"},{"n":94,"q":"Why does the speaker say, “customers often take a while to make their selection”?","qvi":"Tại sao người nói nói “khách hàng thường mất thời gian để chọn hàng”?","opts":["To recommend rearranging a display","To encourage staff to be attentive","To emphasize a problem","To remind staff of a policy"],"vi":["Để khuyến nghị thay đổi cách trưng bày","Để khuyến khích nhân viên chú ý hơn","Để nhấn mạnh một vấn đề","Để nhắc nhân viên về một quy định"],"ans":"C"}],"a":"E26-T10-92-94.mp3"},{"ns":[95,97],"script":[["W","First, I'd like to welcome our new employees. Won-Sang Kwon has joined the human resources department as a junior associate, and So-Jin Cho is our newest chief of building security. Welcome! Next, I want to inform everyone about an upcoming recommended safety workshop. Links to the registration form have been e-mailed. When filling out the registration form, you do not need to fill in the street address. Leave that field blank. Do enter your work e-mail in the appropriate place. Finally, don't forget that the cafeteria will be closed next week, so you'll need to bring your lunch.","Trước tiên, tôi muốn chào mừng các nhân viên mới. Won-Sang Kwon đã gia nhập phòng nhân sự với vai trò cộng sự cấp dưới, và So-Jin Cho là trưởng bộ phận an ninh tòa nhà mới nhất của chúng ta. Chào mừng các bạn! Tiếp theo, tôi muốn thông báo đến mọi người về một buổi hội thảo về an toàn sắp tới được khuyến nghị. Liên kết đến mẫu đăng ký đã được gửi qua email. Khi điền vào mẫu đăng ký, bạn không cần điền địa chỉ đường phố. Hãy để trống ô đó. Nhưng hãy nhập email công việc của bạn vào vị trí thích hợp. Cuối cùng, đừng quên rằng căng tin sẽ đóng cửa vào tuần tới, vì vậy bạn sẽ cần mang theo bữa trưa."]],"qs":[{"n":95,"q":"How does the speaker begin the meeting?","qvi":"Người nói bắt đầu buổi họp bằng cách nào?","opts":["By announcing contest winners","By reading a new policy","By distributing a sign-up sheet","By introducing new employees"],"vi":["Công bố người thắng cuộc thi","Đọc một chính sách mới","Phát danh sách đăng ký","Giới thiệu nhân viên mới"],"ans":"D"},{"n":96,"q":"Look at the graphic. Which section does the speaker say the listeners should leave blank?","qvi":"Nhìn vào biểu mẫu. Người nói yêu cầu để trống mục nào?","opts":["Section 1","Section 2","Section 3","Section 4"],"vi":["Mục 1","Mục 2","Mục 3","Mục 4"],"ans":"B"},{"n":97,"q":"What does the speaker say will happen next week?","qvi":"Người nói cho biết điều gì sẽ xảy ra vào tuần tới?","opts":["A cafeteria will be closed.","Free snacks will be provided.","Certificates will be distributed.","New ID badges will be issued."],"vi":["Một căng tin sẽ đóng cửa","Có phục vụ đồ ăn nhẹ miễn phí","Sẽ phát chứng nhận","Sẽ cấp thẻ ID mới"],"ans":"A"}],"a":"E26-T10-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["M","Hi, Marta. This is Oleg from Sola Salon returning your call. You wanted to know about my availability for haircuts—yes, I am accepting new clients. This week, I can fit you in on Wednesday at four o'clock. Please let me know whether that day and time work for you. And in case you didn't know, there's a parking garage with reasonable rates right under our building. A full styling session takes about one and a half hours, so you won't need to park for more than two hours in the garage.","Chào Marta. Tôi là Oleg từ Sola Salon, gọi lại cho bạn. Bạn muốn biết về lịch rảnh của tôi để cắt tóc—vâng, tôi đang nhận khách mới. Tuần này, tôi có thể sắp xếp cho bạn vào lúc 4 giờ chiều thứ Tư. Hãy cho tôi biết liệu ngày giờ đó có phù hợp với bạn không. Và nếu bạn chưa biết, có một bãi đậu xe với mức phí hợp lý ngay dưới tòa nhà của chúng tôi. Một buổi làm tóc đầy đủ mất khoảng một tiếng rưỡi, vì vậy bạn không cần phải gửi xe hơn hai tiếng trong bãi."]],"qs":[{"n":98,"q":"Where does the speaker work?","qvi":"Người nói làm việc ở đâu?","opts":["At a hair salon","At a doctor’s office","At a talent agency","At a photographer’s studio"],"vi":["Tiệm làm tóc","Phòng khám","Công ty đào tạo tài năng","Studio nhiếp ảnh"],"ans":"A"},{"n":99,"q":"What does the speaker ask the listener to do?","qvi":"Người nói yêu cầu người nghe làm gì?","opts":["Write an online review","Confirm an appointment","Submit a form","Download an application"],"vi":["Viết đánh giá trực tuyến","Xác nhận lịch hẹn","Gửi một biểu mẫu","Tải một ứng dụng"],"ans":"B"},{"n":100,"q":"Look at the graphic. How much will the listener most likely pay for parking?","qvi":"Nhìn vào bảng giá. Người nghe có thể sẽ trả bao nhiêu tiền gửi xe?","opts":["$3.00","$5.00","$7.00","$9.00"],"vi":["$3.00","$5.00","$7.00","$9.00"],"ans":"B"}],"a":"E26-T10-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"Sophia Hollinger was commended for ------- work on the Kala account.","opts":["her","she","hers","herself"],"ans":"A","xp":"Sau “for” cần tính từ sở hữu để bổ sung cho danh từ “work”\nShe: thường là chủ ngữ đứng đầu câu → Sai ngữ pháp\nHers: Đại từ sở hữu, đứng 1 mình, không đi kèm danh từ → Sai\nHerself: Đại từ phản thân → ko phù hợp\n→ Chọn(A)\nHer = tính từ sở hữu → her work( công việc của cô ấy)\nDịch: Sophia Hollinger đã được khen ngợi vì công việc của cô ấy trong việc xử lý tài khoản Kala."},{"n":102,"q":"Last summer, jazz musician Jay Deswani ------- on the main concert stage at Waterfront Park.","opts":["located","requested","supplied","performed"],"ans":"D","xp":"performed on a stage = đã biểu diễn trên sân khấu = collocation\nLocated: định vị, đặt ở (không dùng cho người biểu diễn )\nRequested: yêu cầu( không liên quan)\nSupplied: cung cấp ( không phù hợp với chủ ngữ là nhạc công)\n→ Chọn ( D)\nDịch: Mùa hè năm ngoái, nhạc công jazz Jay Deswani đã biểu diễn trên sân khấu hòa nhạc chính tại Công viên Waterfront."},{"n":103,"q":"The purchasing department ordered six ------- cases of ink toner.","opts":["add","additional","additionally","adding"],"ans":"B","xp":"“Cases” là danh từ→ cần 1 tính từ đứng trước để bổ nghĩa\n→ Chọn (B)\nadditional + noun = thêm / bổ sung\nDịch: Bộ phận mua hàng đã đặt thêm sáu thùng mực in."},{"n":104,"q":"Please complete the questionnaire to help our team ------- understand the financial services you are interested in.","opts":["better","more","very","surely"],"ans":"A","xp":"Từ cần điền phải bổ nghĩa cho động từ “understand”\nMore( understand): không tự nhiên trong văn cảnh này\nVery: không đứng trước động từ Surely( adv) chắc chắn-> không đúng về mặt ngữ pháp và ý nghĩa\n→ chọn ( A)\nhelp + someone + (adverb) + verb\nDịch: Vui lòng hoàn thành bảng câu hỏi để giúp nhóm của chúng tôi hiểu rõ hơn về các dịch vụ tài chính mà bạn quan tâm."},{"n":105,"q":"------- of the garments will begin two weeks after the contract is signed.","opts":["Product","Produce","Produced","Production"],"ans":"D","xp":"Vị trí đầu câu cần một danh từ làm chủ ngữ\nProduct (v) : sản phẩm ( vật cụ thể) không phải quá trình\nProduce(n) : động hoặc danh từ chỉ nông sản\n→ không phù hợp với cấu trúc\nProduced (n) : quá khứ phận từ, không thể làm chủ ngữ độc lập ở đây\n→ Chọn (D)\nProduction of + noun + will begin/start\nDịch: Việc sản xuất các mặt hàng may mặc sẽ bắt đầu hai tuần sau khi hợp đồng được ký kết."},{"n":106,"q":"The minutes of last week’s board meeting had only three ------- errors.","opts":["junior","minor","soft","light"],"ans":"B","xp":"Collocation phổ biến trong TOEIC: minor errors = lỗi nhỏ, không đáng kể\n→ Chọn (B)\nDịch: Biên bản cuộc họp hội đồng quản trị tuần trước chỉ có ba lỗi nhỏ."},{"n":107,"q":"Patrons are asked to silence their phones ------- the show begins.","opts":["when","which","what","why"],"ans":"A","xp":"Câu cần liên từ chỉ thời gian để nối hai mệnh đề\nWhich : đại từ quan hệ, không dùng để nối mệnh đề chỉ thời gian\nWhat: không đúng trong cấu trúc này\nWhy: hỏi lý do, ko phù hợp làm ngữ nghĩa\n→ Chọn (A)\nWhen=khi - diễn tả thời điểm trước/tại lúc buổi biểu biễn bắt đâu\nDịch: Khán giả được yêu cầu tắt hoặc để im lặng điện thoại khi buổi biểu diễn bắt đầu."},{"n":108,"q":"The majority of the company’s employees commute to work ------- train.","opts":["on","by","in","from"],"ans":"B","xp":"Cấu trúc cố định: by + phương tiện giao thông\n→ Chọn ( B)\nDịch: Phần lớn nhân viên của công ty đi làm bằng tàu hỏa."},{"n":109,"q":"Line 73 is the oldest ------- operating bus line in Raymo City’s history.","opts":["continues","continued","continuous","continuously"],"ans":"D","xp":"Trong ngữ cảnh này, \"operating\" đóng vai trò như một tính từ (hiện tại phân từ) để bổ nghĩa cho \"bus line\". Để bổ nghĩa cho một tính từ hoặc một động từ dạng V-ing, chúng ta phải sử dụng một trạng từ (adverb).\n→ Chọn (D)\nDịch: Tuyến số 73 là tuyến xe buýt hoạt động liên tục lâu đời nhất trong lịch sử thành phố Raymo."},{"n":110,"q":"This message is a ------- to pick up your package at your local post office as soon as possible.","opts":["promotion","reminder","process","report"],"ans":"B","xp":"Promotion: quảng cáo/ khuyển mãi( không liên quan)\nProcess: không phù hợp với ngữ nghĩa\nReport: báo cáo, không phải thông báo nhắc nhở\n→ Chọn (B)\nA reminder to + V: một lời nhắc để làm gì đó\nDịch: Tin nhắn này là một lời nhắc để bạn đến nhận bưu kiện của mình tại bưu điện địa phương sớm nhất có thể."},{"n":111,"q":"Pet Orbit customers ------- want receipts delivered by e-mail can opt for this service.","opts":["whose","who","those","whoever"],"ans":"B","xp":"Sau customers là một mệnh đề có động từ “want”, nhưng chưa có chủ ngữ cho động từ đó. Cần một từ vừa thay thế cho “customers” vừa làm chủ ngữ cho “want”\nWhose: chỉ sở hữu, cần thêm danh từ theo sau\nThose: đại từ chỉ người/vật\nWhoever: bất cứ ai, không phù hợp trong câu xác định nhóm\n→ Chọn (B)\nDịch: Những khách hàng của Pet Orbit muốn nhận hóa đơn qua email có thể chọn dịch vụ này."},{"n":112,"q":"Mr. Takajian may be an entry-level employee, ------- he does not hesitate to take initiative.","opts":["but","or","equally","accordingly"],"ans":"A","xp":"Dựa vào nghĩa của câu để chọn đáp án entry-level employee (nhân viên mới, cấp thấp) does not hesitate to take initiative (chủ động, không ngần ngại) Hai câu trái ngược nhau → cần liên từ chỉ sự tương phản\n→ Chọn (A)\nDịch: Mặc dù ông Takajian chỉ là một nhân viên mới vào nghề, nhưng ông ấy không hề ngần ngại trong việc chủ động đảm nhận công việc."},{"n":113,"q":"Carter Department Store allows customers ------- items on hold for up to 24 hours.","opts":["place","to place","placing","to be placed"],"ans":"B","xp":"Ta có cấu trúc: allow + someone + to + V customers là tân ngữ → sau đó phải là to + động từ nguyên mẫu\n→ Chọn (B)\nallow / permit / enable + s.one + to + V\nDịch: Cửa hàng bách hóa Carter cho phép khách hàng giữ hàng trong tối đa 24 giờ."},{"n":114,"q":"Using unique colors and styles, the decor experts at Mamie’s Interiors bring a ------- look to homes.","opts":["brief","dependent","motivational","fashionable"],"ans":"D","xp":"Brief: ngắn gọn( không dùng để mô tả phong cách trang trí)\nDependent: phụ thuộc→ không liên quan\nMotivational: mang tính truyền cảm hứng không hợp với look\n→ Chọn (D)\nfashionable look = phong cách thời thượng, hợp mốt\nDịch: Bằng cách sử dụng các màu sắc và phong cách độc đáo, các chuyên gia trang trí tại Mamie’s Interiors mang đến cho các ngôi nhà một diện mạo thời thượng."},{"n":115,"q":"------- efficient project management, Sparksware’s latest software program was released on time.","opts":["Along with","Regarding","Because of","Subsequent"],"ans":"C","xp":"Phía sau là cụm danh từ , câu cần giới từ/ cụm từ chỉ nguyên nhân\nAlong with:cùng với →không diễn tả nguyên nhân\nRegarding: về / liên quan đến→ không phù hợp ngữ nghĩa\nSubsequent : tính từ (kế tiếp)--> không thể đứng đầu câu như một liên từ/giới từ\n→ Chọn ( C)\nBecause of + noun\nDịch: Nhờ vào việc quản lý dự án hiệu quả, chương trình phần mềm mới nhất của Sparksware đã được phát hành đúng thời hạn."},{"n":116,"q":"The summer line of outdoor furniture will be available ------- select stores as early as February.","opts":["until","at","over","before"],"ans":"B","xp":"Until: chỉ mốc thời gian kết thúc, không đi với địa điểm\nOver: trong suốt …→ không phù hợp\nBefore: chỉ thời gian\n→ Chọn (B)\navailable at + place ( điểm bán cụ thể)\nDịch: Dòng sản phẩm nội thất ngoài trời mùa hè sẽ có mặt tại một số cửa hàng được chọn sớm nhất là vào tháng Hai."},{"n":117,"q":"There has been a ------- decrease in requests for customer support this quarter.","opts":["notice","noticing","noticeable","noticeably"],"ans":"C","xp":"Cấu trúc: A + adjective + noun decrease là danh từ → cần tính từ đứng trước để bổ nghĩa\nnoticeable = dễ nhận thấy, rõ rệt\n→ Chọn (C)\na noticeable decrease (một sự sụt giảm đáng kể)→ collocation phổ biến\nDịch: Trong quý này đã có một sự sụt giảm đáng kể trong số lượng yêu cầu hỗ trợ khách hàng."},{"n":118,"q":"Bina Dal always wanted to become a diplomat, ------- she studied international relations at university.","opts":["so","once","overall","whereas"],"ans":"A","xp":"Dựa vào nghĩa và ngữ pháp của câu để đáp án\nOnce: chỉ thời gian → không hợp ngữ nghĩa\nOverall: trạng từ mang nghĩa “ nhìn chung”--> không dùng nối hai mệnh đề\nwhereas : chỉ sự tương phản, trong khi hai ý không đối lập\n→ Chọn (A)\nnguyên nhân → kết quả\nDịch: Bina Dal luôn muốn trở thành một nhà ngoại giao, vì vậy cô ấy đã theo học ngành quan hệ quốc tế tại đại học"},{"n":119,"q":"Thank you for responding ------- with information about the T-Max 400 printer and scanner.","opts":["prompt","promptly","prompted","prompts"],"ans":"B","xp":"“Responding” là động từ → cần trạng từ để bổ nghĩa. Ta có cấu trúc: respond + adverb\n→ Chọn (B)\nDịch: Cảm ơn bạn đã phản hồi nhanh chóng với thông tin về máy in và máy quét T-Max 400."},{"n":120,"q":"Owing to the weather, we need to ------- your appointment for tree removal service.","opts":["reschedule","borrow","contain","reconstruct"],"ans":"A","xp":"Dựa vào ngữ nghĩa để chọn đáp án\nBorrow: Mượn\nContain: Chứa đựng\nReconstruct: xây dựng lại\n→ Chọn ( A)\nOwing to the weather = Do thời tiết\n→ cần dời / sắp xếp lại lịch hẹn.\nreschedule = lên lịch lại, dời lịch\nDịch: Do thời tiết, chúng tôi cần dời lịch hẹn dịch vụ chặt/cắt cây của bạn."},{"n":121,"q":"It will require a ------- effort between the two countries to complete the railway line.","opts":["coordinate","coordinates","coordinated","coordination"],"ans":"C","xp":"Cấu trúc: a + adj + danh từ Cần tính từ bổ nghĩa cho effort\ncoordinate (v): không bổ nghĩa cho danh từ\ncoordinates (động từ chia / danh từ số nhiều): sai loại từ\ncoordination (n ): a coordination effort (không dùng kiểu này)\n→ Chọn ( C)\na coordinated effort = nỗ lực phối hợp chặt chẽ\nDịch: Việc hoàn thành tuyến đường sắt sẽ đòi hỏi một nỗ lực phối hợp giữa hai quốc gia."},{"n":122,"q":"According to the restaurant’s -------, guests must wait to be seated by the front-of-house staff.","opts":["offerings","funds","bill","policy"],"ans":"D","xp":"Dựa vào ngữ nghĩa để chọn đáp án\nofferings: món ăn/dịch vụ cung cấp → không liên quan quy định\nfunds: quỹ, tiền → sai ngữ cảnh\nbill: hóa đơn → không phải thứ “quy định” hành vi\n→ Chọn (D)\n- policy: chính sách/quy định\nDịch: Theo quy định của nhà hàng, khách phải chờ được nhân viên lễ tân sắp xếp chỗ ngồi."},{"n":123,"q":"Tickets for Saturday’s football game sold out on Thursday, much sooner than organizers -------.","opts":["will anticipate","had anticipated","anticipating","to anticipate"],"ans":"B","xp":"- Xác định mốc thời gian: sold out on Thursday → sự việc đã xảy ra\n- Cụm so sánh: much sooner than organizers\n→ Việc dự đoán (anticipate) xảy ra trước khi bán hết vé Khi 2 hành động đều ở quá khứ và một hành động xảy ra trước → ta dùng Past Perfect (had + V3)\n→ Chọn (B)\nDịch: Vé cho trận bóng đá vào thứ Bảy đã bán hết từ thứ Năm, sớm hơn rất nhiều so với dự đoán của ban tổ chức."},{"n":124,"q":"Renewing your auto registration online ------- at the motor vehicle office will save you time.","opts":["just","neither","at any rate","rather than"],"ans":"D","xp":"Dựa vào ngữ nghĩa đề chọn đáp án Câu đang so sánh/ đối chiếu 2 cách làm\n- renewing online : gia hạn trực tuyến\n- renewing at the motor vehicle office: gia hạn tại văn phòng phương tiện giao thông\n→ Chọn (D)\n- rather than = thay vì\nDịch: Gia hạn đăng ký xe trực tuyến thay vì đến văn phòng đăng ký xe sẽ giúp bạn tiết kiệm thời gian."},{"n":125,"q":"------- Latoya Model Management’s sound reputation, aspiring models can expect a flourishing career.","opts":["Given","Ahead of","Preferably","Provided that"],"ans":"A","xp":"Dựa vào ngữ nghĩa để chọn đáp án Ahead of = trước (về thời gian / vị trí)\n→ không mang nghĩa nguyên nhân Preferably(adv) tốt nhất → không đúng\nProvided that: với điều kiện là → không đi với danh từ câu này\n→ Chọn (A)\n- Given + noun phrase\nDịch: Xét đến danh tiếng vững chắc của Latoya Model Management, các người mẫu trẻ có thể kỳ vọng một sự nghiệp phát triển."},{"n":126,"q":"Employees are asked to update their contact information ------- the staff directory can be finalized.","opts":["so that","as though","namely","likewise"],"ans":"A","xp":"Dựa vào ngữ nghĩa để chọn đáp án Nhân viên được yêu cầu cập nhật thông tin Mục đích: hoàn tất danh bạ nhân sự\n→ Quan hệ mục đích - kết quả\nAs though: như thể là → Dùng cho so sánh giả định, không phải mục đích\nNamely: cụ thể là → không dùng nối mệnh đề mục đích\nLikewise: tương tự như vậy→ không phù hợp ngữ cảnh\n→ Chọn (A)\nSo that: để mà/nhằm → dùng để tả mục đích\nDịch: Nhân viên được yêu cầu cập nhật thông tin liên hệ để danh bạ nhân sự có thể được hoàn thiện."},{"n":127,"q":"Glistonford Manufacturing cautions consumers not to buy inferior ------- of its adjustable desks.","opts":["imitates","imitative","imitated","imitations"],"ans":"D","xp":"Sau inferior (tính từ) cần danh từ\n→ Chọn ( D)\nimitations (danh từ số nhiều): hàng nhái, bản sao inferior imitations = hàng nhái kém chất lượng\nDịch: Công ty Glistonford Manufacturing cảnh báo người tiêu dùng không nên mua các sản phẩm nhái kém chất lượng của dòng bàn làm việc điều chỉnh của hãng."},{"n":128,"q":"------- the fact that the use of social media is widespread, many people still rely on newspapers for fact-checked information.","opts":["Opposite","Without","Unlike","Despite"],"ans":"D","xp":"Opposite: đối diện/ trái ngược → không hợp nghĩa\nWithout: Không có → sai nghĩa\nUnlike: không giống như → So sánh nhưng không diễn tả sự tương phản logic\n→ Chọn (D)\n- Despite + the fact that\nDịch: Mặc dù việc sử dụng mạng xã hội rất phổ biến, nhiều người vẫn dựa vào báo in để có thông tin đã được kiểm chứng."},{"n":129,"q":"Citing energy efficiency and cost reductions, the presenter made several ------- arguments for installing solar panels.","opts":["absent","affordable","convincing","intrigued"],"ans":"C","xp":"Dựa vào ngữ nghĩa của câu để chọn đáp án\nabsent = vắng mặt → sai nghĩa\naffordable = có thể chi trả → không liên quan\nintrigued = bị tò mò→ không dùng cho arguments\n→ Chọn ( C)\nconvincing arguments: những lập luận / lý lẽ thuyết phục\nDịch: Dựa trên hiệu quả năng lượng và việc giảm chi phí, người thuyết trình đã đưa ra nhiều lập luận thuyết phục để lắp đặt pin năng lượng mặt trời."},{"n":130,"q":"After leaving his official government role, Dr. Beasly was ------- Director of the Nanboro Youth Farming Program.","opts":["hired","named","admitted","established"],"ans":"B","xp":"Cấu trúc: be named + chức danh = được bổ nhiệm / được chỉ định làm gì\n→ Chọn (B)\nDịch: Sau khi rời vị trí chính thức trong chính phủ, Tiến sĩ Beasly được bổ nhiệm làm Giám đốc Chương trình Nông nghiệp Thanh niên Nanboro."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following memo.","passage":"<div class=\"hdr\"><p><b>To:</b> All Warehouse Employees</p><p><b>From:</b> Paul Wandayi, Warehouse Manager</p><p><b>Date:</b> 15 March</p><p><b>Re:</b> New crates coming</p></div><p>Beginning 1 April, Windquest Farms will use Flexmerge crates to transport our fruits and vegetables. These <span class=\"blank\" data-n=\"131\">-------</span> will simplify work and shrink operational costs.</p><p>Flexmerge crates are collapsible, which means they are easy to stack and they save space. <span class=\"blank\" data-n=\"132\">-------</span>. They are also highly durable. This feature minimizes the need <span class=\"blank\" data-n=\"133\">-------</span> frequent replacement of crates. Finally, they are designed with ergonomic features, thereby <span class=\"blank\" data-n=\"134\">-------</span> the risk of injuries. Safety is our top priority here at Windquest Farms.</p>","vi":"Gửi: Tất cả nhân viên kho\nTừ: Paul Wandayi, Quản lý kho\nNgày: 15 tháng 3\nV/v: Các thùng chứa mới sắp được đưa vào sử dụng\n\nBắt đầu từ ngày 1 tháng 4, Windquest Farms sẽ sử dụng các thùng Flexmerge để vận chuyển trái cây và rau củ của chúng ta. Những (131) ------- này sẽ giúp đơn giản hóa công việc và giảm chi phí vận hành.\n\nCác thùng Flexmerge có thể gấp gọn, nghĩa là chúng dễ xếp chồng và giúp tiết kiệm không gian. (132) -------. Chúng cũng có độ bền rất cao. Đặc điểm này giúp giảm thiểu nhu cầu (133) ------- việc thay thế thùng thường xuyên. Cuối cùng, chúng được thiết kế với các đặc điểm công thái học, từ đó (134) ------- nguy cơ chấn thương. An toàn là ưu tiên hàng đầu của chúng ta tại Windquest Farms.","qs":[{"n":131,"opts":["desks","programs","agencies","containers"],"ans":"D","xp":"Giải thích: Câu trước đề cập đến \"Flexmerge crates\" (thùng/kiện hàng Flexmerge). Trong các lựa chọn, containers (vật chứa/thùng chứa) là danh từ chung phù hợp nhất để thay thế cho từ \"crates\".\nPhân tích đáp án sai:\n(A) desks: bàn làm việc.\n(B) programs: chương trình.\n(C) agencies: đại lý/cơ quan.\nDịch: \"Những thùng chứa này sẽ đơn giản hóa công việc và cắt giảm chi phí vận hành.\""},{"n":132,"opts":["We will need more of them in the months ahead.","More of them were bought by farmers and wholesalers.","Accordingly, more of them can be loaded onto trucks when empty.","Soon more of them will be available on our Web site."],"ans":"C","xp":"Giải thích: Câu ngay trước đó cho biết \"Flexmerge crates are collapsible\" (có thể gập lại được), giúp tiết kiệm diện tích. Do đó, câu (C) là hệ quả logic: vì gập lại được nên khi trống rỗng, có thể xếp được nhiều thùng hơn lên xe tải.\nPhân tích đáp án sai:\n(A) Chúng tôi sẽ cần nhiều hơn trong những tháng tới (không liên quan tính năng gập).\n(B) Nhiều thùng được mua bởi nông dân và nhà bán buôn (thông tin bán hàng, không phù hợp mạch văn).\n(D) Sớm có mặt trên website (không liên quan).\nDịch: \"Theo đó, có thể xếp được nhiều thùng hơn lên xe tải khi chúng trống rỗng.\""},{"n":133,"opts":["to","for","among","besides"],"ans":"B","xp":"Giải thích: Cấu trúc danh từ \"need for something\" (nhu cầu cho cái gì/việc gì). Ở đây là \"need for frequent replacement\" (nhu cầu thay thế thường xuyên).\nPhân tích đáp án sai: Các giới từ (A) to, (C) among, (D) besides không đi với danh từ \"need\" trong ngữ cảnh này.\nDịch: \"Đặc điểm này giúp giảm thiểu nhu cầu cho việc thay thế thùng thường xuyên.\""},{"n":134,"opts":["reducing","reduces","reduced","reducer"],"ans":"A","xp":"Giải thích: Sau trạng từ thereby (bằng cách đó/nhờ đó), chúng ta thường sử dụng dạng V-ing để chỉ kết quả của hành động phía trước. Đây là cấu trúc rút gọn mệnh đề quan hệ chỉ kết quả.\nDịch: \"...nhờ đó giảm thiểu rủi ro chấn thương.\""}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following article.","passage":"<h3>Popular TV Show Returns for Third Season</h3><p>Sunday marks the start of the third season of the award-winning TV series <i>King of the Meer</i>. This political thriller <span class=\"blank\" data-n=\"135\">-------</span> on the book <i>Whispered Illusions</i> by Noriaki Arishima.</p><p>Some reviewers of the television series believe that the third season might be even better than the previous ones. <span class=\"blank\" data-n=\"136\">-------</span>, other reviewers argue that the series might lose its appeal with the introduction of so many new characters, resulting in a complicated and confusing plotline.</p><p>Director Amber Randolph has responded to that <span class=\"blank\" data-n=\"137\">-------</span>. “The abundance of new characters can make the story challenging to follow,” she said. “<span class=\"blank\" data-n=\"138\">-------</span>. We’ll see what the fans of the show think.”</p>","vi":"Chương trình truyền hình ăn khách trở lại với mùa thứ ba\n\nChủ nhật đánh dấu sự khởi đầu của mùa thứ ba của loạt phim truyền hình đoạt giải thưởng King of the Meer. Bộ phim chính trị – giật gân này (135) ------- dựa trên cuốn sách Whispered Illusions của Noriaki Arishima.\n\nMột số nhà phê bình của loạt phim truyền hình tin rằng mùa thứ ba thậm chí có thể còn hay hơn các mùa trước. (136) -------, những nhà phê bình khác lại cho rằng loạt phim có thể mất đi sức hấp dẫn khi giới thiệu quá nhiều nhân vật mới, dẫn đến một cốt truyện phức tạp và khó hiểu.\n\nĐạo diễn Amber Randolph đã phản hồi lại (137) ------- đó. “Sự xuất hiện dồi dào của các nhân vật mới có thể khiến câu chuyện trở nên khó theo dõi,” cô nói. “(138) -------. Chúng ta sẽ xem người hâm mộ của bộ phim nghĩ gì.”","qs":[{"n":135,"opts":["basing","will be based","was based","is based"],"ans":"D","xp":"Giải thích: Câu này diễn tả một sự thật hiển nhiên (nội dung bộ phim dựa trên sách). Chúng ta dùng thì hiện tại đơn ở dạng bị động: is/am/are + V3/ed. Vì chủ ngữ là \"This political thriller\" (số ít) nên dùng is based.\nDịch: \"Bộ phim tâm lý chính trị này dựa trên cuốn sách Whispered Illusions của Noriaki Arishima.\""},{"n":136,"opts":["From here on","In contrast","To be specific","To sum up"],"ans":"B","xp":"Giải thích: Câu trước nói về ý kiến tích cực (phim sẽ hay hơn các mùa trước). Câu sau nói về ý kiến tiêu cực (phim có thể mất đi sức hút). Do đó, ta cần trạng từ liên kết chỉ sự đối lập In contrast (Ngược lại).\nPhân tích đáp án sai:\n(A) From here on: Kể từ đây trở đi.\n(C) To be specific: Cụ thể là.\n(D) To sum up: Tóm lại là.\nDịch: \"Ngược lại, những nhà phê bình khác lại tranh luận rằng loạt phim có thể mất đi sức hút với việc giới thiệu quá nhiều nhân vật mới.\""},{"n":137,"opts":["advertisement","treatment","criticism","need"],"ans":"C","xp":"Giải thích: Dựa vào nội dung câu 136, các nhà phê bình đang đưa ra những ý kiến lo ngại/chỉ trích về cốt truyện mới. Vì vậy, đạo diễn sẽ phản hồi lại lời criticism (sự chỉ trích/phê bình) đó.\nPhân tích đáp án sai:\n(A) advertisement: quảng cáo.\n(B) treatment: sự đối xử/điều trị.\n(D) need: nhu cầu.\nDịch: \"Đạo diễn Amber Randolph đã phản hồi lại lời phê bình đó.\""},{"n":138,"opts":["But they succeeded despite many difficulties.","But they bring greater depth to the narrative.","But it will be a useful learning experience.","But it brought them closer together."],"ans":"B","xp":"Giải thích: Ở câu trước, đạo diễn thừa nhận việc có nhiều nhân vật mới có thể gây thách thức khi theo dõi. Câu (B) bắt đầu bằng \"But\" (nhưng) để đưa ra mặt tích cực của việc này (mang lại chiều sâu cho câu chuyện), tạo nên lập luận phản bác lại sự lo ngại ở trên.\nPhân tích đáp án sai:\n(A) Họ đã thành công bất chấp khó khăn (không liên quan đến việc giải thích số lượng nhân vật).\n(C) Nó sẽ là một trải nghiệm học tập hữu ích (quá chung chung).\n(D) Nó mang họ lại gần nhau hơn (thường dùng cho con người, không dùng cho cốt truyện).\nDịch: \"'Việc có quá nhiều nhân vật mới có thể khiến câu chuyện trở nên thách thức để theo dõi', bà ấy nói. 'Nhưng chúng mang lại chiều sâu lớn hơn cho nội dung câu chuyện. Chúng ta hãy cùng chờ xem người hâm mộ nghĩ gì'.\""}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Jee-Wah Cho &lt;cho8876@sunmail.com&gt;</p><p><b>From:</b> Ken Belfant &lt;kenbelfant@fluffytimeindustries.com&gt;</p><p><b>Date:</b> 6 April</p><p><b>Subject:</b> Recipe contest</p></div><p>Dear Ms. Cho,</p><p>Thank you for <span class=\"blank\" data-n=\"139\">-------</span> your interesting recipe that uses our low-fat, sugar-free Fluffy Time Whipped Topping. <span class=\"blank\" data-n=\"140\">-------</span> has been entered into our upcoming contest. The winning recipes will appear on our product’s packaging. <span class=\"blank\" data-n=\"141\">-------</span>. In the meantime, I will be sending you a coupon for 25 percent off your next purchase of any Fluffy Time product via a separate e-mail that you should receive <span class=\"blank\" data-n=\"142\">-------</span>.</p><p>We are so glad you enjoy our products. Best of luck in the contest!</p><p>With gratitude,</p><p>Ken Belfant, Promotions Coordinator<br>Fluffy Time Industries</p>","vi":"Gửi: Jee-Wah Cho <cho8876@sunmail.com>\nTừ: Ken Belfant <kenbelfant@fluffytimeindustries.com>\nNgày: 6 tháng 4\nChủ đề: Cuộc thi công thức nấu ăn\n\nKính gửi cô Cho,\n\nCảm ơn cô vì (139) ------- công thức thú vị của mình sử dụng sản phẩm kem phủ đánh bông Fluffy Time ít béo, không đường của chúng tôi. (140) ------- đã được đưa vào cuộc thi sắp tới của chúng tôi. Các công thức chiến thắng sẽ xuất hiện trên bao bì sản phẩm của chúng tôi. (141) -------. Trong thời gian chờ đợi, tôi sẽ gửi cho cô một phiếu giảm giá 25% cho lần mua tiếp theo của bất kỳ sản phẩm Fluffy Time nào thông qua một email riêng mà cô sẽ nhận được (142) -------.\n\nChúng tôi rất vui vì cô yêu thích các sản phẩm của chúng tôi. Chúc cô may mắn trong cuộc thi!\n\nTrân trọng,\n\nKen Belfant, Điều phối viên khuyến mãi\nFluffy Time Industries","qs":[{"n":139,"opts":["share","shared","sharing","shares"],"ans":"C","xp":"Giải thích: Đứng sau giới từ \"for\", chúng ta cần sử dụng một danh từ hoặc một danh động từ (V-ing). Ở đây, hành động \"chia sẻ công thức\" đóng vai trò là tân ngữ của giới từ.\nDịch: \"Cảm ơn bà vì đã chia sẻ công thức thú vị của mình có sử dụng sản phẩm Kem phủ Whipped Topping Fluffy Time không đường, ít béo của chúng tôi.\""},{"n":140,"opts":["It","One","Each","Theirs"],"ans":"A","xp":"Giải thích: Đại từ It (Nó) được dùng để thay thế cho danh từ số ít đã nhắc ở câu trước là \"your interesting recipe\" (công thức thú vị của bà).\nPhân tích đáp án sai:\n(B) One: một cái (thường dùng khi chọn một trong nhiều cái không xác định).\n(C) Each: mỗi (đi với danh từ số ít, không dùng làm chủ ngữ thay thế trực tiếp ở đây).\n(D) Theirs: của họ (đại từ sở hữu).\nDịch: \"Nó (công thức) đã được đưa vào cuộc thi sắp tới của chúng tôi.\""},{"n":141,"opts":["Fluffy Time is a favorite of children everywhere.","Contest winners will be notified in June.","We are sorry that you were disappointed.","You may want to try our chocolate cream recipe."],"ans":"B","xp":"Giải thích: Câu trước đề cập đến việc những công thức thắng cuộc sẽ xuất hiện trên bao bì sản phẩm. Câu (B) cung cấp thêm thông tin về thời gian thông báo kết quả cuộc thi, hoàn toàn khớp với tiến trình của một cuộc thi nấu ăn.\nPhân tích đáp án sai:\n(A) Fluffy Time là sản phẩm yêu thích của trẻ em (thông tin quảng cáo chung chung, không liên quan đến cuộc thi).\n(C) Chúng tôi rất tiếc vì bà đã thất vọng (không phù hợp vì đây là email cảm ơn tích cực).\n(D) Bà có thể muốn thử công thức kem sô-cô-la của chúng tôi (lạc đề).\nDịch: \"Những người thắng cuộc sẽ được thông báo vào tháng Sáu.\""},{"n":142,"opts":["briefly","concisely","temporarily","shortly"],"ans":"D","xp":"Giải thích: Trạng từ shortly có nghĩa là \"sớm/ngay sau đây\". Trong ngữ cảnh gửi email tự động hoặc email riêng biệt, chúng ta dùng \"shortly\" để chỉ thời gian người nhận sẽ nhận được thư trong tương lai gần.\nPhân tích đáp án sai:\n(A) briefly: ngắn gọn/tóm tắt.\n(B) concisely: súc tích.\n(C) temporarily: tạm thời.\nDịch: \"...qua một email riêng biệt mà bà sẽ nhận được sớm thôi.\""}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following brochure.","passage":"<p>Bingo Imprint creates designs for promotional products such as notebooks, refrigerator magnets, and apparel. We allow our clients to determine their level of involvement in the design process. <span class=\"blank\" data-n=\"143\">-------</span>, some submit a detailed sketch of the design. Others are <span class=\"blank\" data-n=\"144\">-------</span> content to leave the development and creation of the design up to our graphic artists. Once the invention has been finalized, it will be shared with the client for approval. <span class=\"blank\" data-n=\"145\">-------</span>. We guarantee that all work will be completed within five business days from when the order is placed.</p><p>You can count <span class=\"blank\" data-n=\"146\">-------</span> Bingo Imprint for unique designs, competitive pricing, and timely delivery.</p>","vi":"Bingo Imprint tạo ra các thiết kế cho các sản phẩm quảng bá như sổ tay, nam châm dán tủ lạnh và quần áo. Chúng tôi cho phép khách hàng quyết định mức độ tham gia của họ trong quá trình thiết kế. (143) -------, một số khách hàng gửi bản phác thảo chi tiết của thiết kế. Những người khác lại (144) ------- hài lòng khi để việc phát triển và sáng tạo thiết kế cho các họa sĩ đồ họa của chúng tôi. Khi bản thiết kế đã được hoàn thiện, nó sẽ được chia sẻ với khách hàng để phê duyệt. (145) -------. Chúng tôi đảm bảo rằng mọi công việc sẽ được hoàn thành trong vòng năm ngày làm việc kể từ khi đơn hàng được đặt.\n\nBạn có thể tin cậy (146) ------- Bingo Imprint về những thiết kế độc đáo, mức giá cạnh tranh và dịch vụ giao hàng đúng hạn.","qs":[{"n":143,"opts":["Similarly","However","As a result","In the meantime"],"ans":"C","xp":"Chọn (C) As a result = Kết quả là\nGiải thích: Câu trước nói về việc khách hàng có thể quyết định mức độ tham gia vào quá trình thiết kế. Câu sau nói về việc khách hàng gửi bản phác thảo. Nên câu sau là kết quả của câu trước. Chọn C là hợp lý nhất.\nPhân tích đáp án sai:\n(A) Similarly: Tương tự như vậy.\n(B) However: Tuy nhiên.\n(D) In the meantime: Trong lúc đó.\nDịch: \"Chúng tôi cho phép khách hàng quyết định mức độ tham gia của họ vào quá trình thiết kế. Kết quả là, một số người chọn nộp bản phác thảo chi tiết về thiết kế.\""},{"n":144,"opts":["perfect","perfected","perfection","perfectly"],"ans":"D","xp":"Giải thích: Ở đây chúng ta cần một trạng từ bổ nghĩa cho tính từ content (hài lòng/mãn nguyện). Cụm từ \"be perfectly content to do something\" có nghĩa là hoàn toàn hài lòng khi làm việc gì đó.\nDịch: \"...Những người khác thì hoàn toàn hài lòng khi để việc phát triển và sáng tạo thiết kế cho các họa sĩ đồ họa của chúng tôi.\""},{"n":145,"opts":["This step facilitates communication among employees.","This step ensures that the product satisfies expectations.","Customers appreciate the company’s suggested alternative.","Customers have greeted this measure with great concern."],"ans":"B","xp":"Giải thích: Câu phía trước đề cập đến việc gửi thiết kế cho khách hàng để phê duyệt (shared with the client for approval). Câu (B) giải thích mục đích của bước này: để đảm bảo sản phẩm đáp ứng đúng kỳ vọng của khách, tạo nên sự mạch lạc về quy trình làm việc.\nPhân tích đáp án sai:\n(A) Bước này tạo điều kiện giao tiếp giữa các nhân viên (sai đối tượng, đây là giao tiếp với khách hàng).\n(C) Khách hàng đánh giá cao sự thay thế gợi ý của công ty (không liên quan đến việc phê duyệt thiết kế gốc).\n(D) Khách hàng đón nhận biện pháp này với sự lo ngại lớn (nghĩa tiêu cực, không phù hợp với brochure quảng cáo).\nDịch: \"Bước này đảm bảo rằng sản phẩm thỏa mãn các kỳ vọng. Chúng tôi đảm bảo rằng mọi công việc sẽ được hoàn thành trong vòng năm ngày làm việc kể từ khi đơn hàng được đặt.\""},{"n":146,"opts":["along","down","off","on"],"ans":"D","xp":"Giải thích: Đây là một cụm động từ (phrasal verb) cố định: count on someone/something có nghĩa là tin tưởng vào ai/cái gì hoặc trông cậy vào điều gì.\nPhân tích đáp án sai: Các giới từ (A) along, (B) down, (C) off không đi với \"count\" để tạo thành nghĩa tin tưởng.\nDịch: \"Bạn có thể tin tưởng vào Bingo Imprint cho những thiết kế độc đáo, giá cả cạnh tranh và giao hàng kịp thời.\""}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following form.","passages":["<h3>Crystal Brothers</h3><h4>Satisfaction Survey</h4><p>Thank you for hiring Crystal Brothers to clean your building. Please circle the appropriate numbers, ranging from 5, “Excellent,” to 1, “Poor.” Circle “NP” for a type of room that is not present in the location that was cleaned.</p><p><b>Customer:</b> Geraldine Hwang &nbsp;&nbsp; <b>Date:</b> February 22</p><p><i>[Circled answers are shown in bold, e.g. <b>(4)</b>.]</i></p><table><tr><th colspan=\"7\">Cleaning Services</th></tr><tr><td>Living room</td><td>5</td><td><b>(4)</b></td><td>3</td><td>2</td><td>1</td><td>NP</td></tr><tr><td>Kitchen</td><td><b>(5)</b></td><td>4</td><td>3</td><td>2</td><td>1</td><td>NP</td></tr><tr><td>Dining room</td><td>5</td><td><b>(4)</b></td><td>3</td><td>2</td><td>1</td><td>NP</td></tr><tr><td>Bedroom(s)</td><td><b>(5)</b></td><td>4</td><td>3</td><td>2</td><td>1</td><td>NP</td></tr><tr><td>Lobby</td><td>5</td><td>4</td><td>3</td><td>2</td><td>1</td><td><b>(NP)</b></td></tr><tr><td>Conference room(s)</td><td>5</td><td>4</td><td>3</td><td>2</td><td>1</td><td><b>(NP)</b></td></tr><tr><th colspan=\"7\">Other Information</th></tr><tr><td>Was it easy to make an appointment?</td><td>5</td><td>4</td><td>3</td><td>2</td><td><b>(1)</b></td></tr><tr><td>Did our staff follow your specific instructions?</td><td><b>(5)</b></td><td>4</td><td>3</td><td>2</td><td>1</td></tr><tr><td>Did our staff provide information before the visit?</td><td>5</td><td><b>(4)</b></td><td>3</td><td>2</td><td>1</td></tr><tr><td>Was the cost of the service what you expected?</td><td><b>(5)</b></td><td>4</td><td>3</td><td>2</td><td>1</td></tr></table>"],"vi":"Crystal Brothers\nKhảo sát mức độ hài lòng\n\nCảm ơn quý khách đã thuê Crystal Brothers để vệ sinh tòa nhà của mình. Vui lòng khoanh tròn số phù hợp, từ 5 = “Rất tốt” đến 1 = “Kém”. Khoanh tròn “NP” đối với những loại phòng không có tại địa điểm được vệ sinh.\n\nKhách hàng: Geraldine Hwang — Ngày: 22 tháng 2\n\nDịch vụ vệ sinh: Phòng khách (4) – Nhà bếp (5) – Phòng ăn (4) – Phòng ngủ (5) – Sảnh (NP) – Phòng họp (NP)\n\nThông tin khác:\n- Việc đặt lịch hẹn có dễ dàng không? (1)\n- Nhân viên của chúng tôi có làm theo đúng hướng dẫn cụ thể của quý khách không? (5)\n- Nhân viên có cung cấp thông tin trước khi đến không? (4)\n- Chi phí dịch vụ có đúng như quý khách mong đợi không? (5)","qs":[{"n":147,"q":"What type of building did Crystal Brothers clean?","qvi":"Crystal Brothers đã vệ sinh loại tòa nhà nào?","opts":["A hotel","A warehouse","An office building","A home"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Các phòng được chấm điểm là Living room, Kitchen, Dining room, Bedroom(s) (phòng khách, bếp, phòng ăn, phòng ngủ), còn Lobby và Conference room(s) được khoanh “NP” (không có) → đây là một ngôi nhà.\n(A) Một khách sạn\n(B) Một nhà kho\n(C) Một tòa văn phòng\n(D) Một ngôi nhà"},{"n":148,"q":"What part of the cleaning service was Ms. Hwang least satisfied with?","qvi":"Ms. Hwang không hài lòng nhất với phần nào của dịch vụ vệ sinh?","opts":["The price","The scheduling","The customizing","The staff’s punctuality"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: “Was it easy to make an appointment?” (Đặt lịch hẹn có dễ không?) chỉ được 1 điểm (Kém) – điểm thấp nhất → không hài lòng nhất với việc đặt lịch (scheduling).\n(A) Giá cả\n(B) Việc đặt lịch\n(C) Việc tùy chỉnh dịch vụ\n(D) Sự đúng giờ của nhân viên"}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following Web page.","passages":["<p>https://www.hamptonlandscaping.com/productdelivery</p><h3>Product Delivery</h3><p>Hampton Landscaping offers customers the option of having landscaping products delivered to their residences or businesses. This includes topsoil, compost, gravel, bark dust, firewood, and planting mixes. For your convenience, we offer large- and small-volume deliveries Monday through Saturday. Delivery rates vary based on volume, product, and location. Please call us at 904-555-0132 for detailed pricing. You do not need to be home for delivery. Please note that the requested delivery area must be accessible for our trucks. In the event that this requirement is not met, a $50 restocking fee will be charged.</p>"],"vi":"Giao hàng sản phẩm\n\nHampton Landscaping cung cấp cho khách hàng tùy chọn giao các sản phẩm cảnh quan đến nhà ở hoặc cơ sở kinh doanh. Các sản phẩm này bao gồm đất mặt, phân trộn, sỏi, mùn vỏ cây, củi đốt và hỗn hợp trồng cây. Để thuận tiện cho quý khách, chúng tôi cung cấp dịch vụ giao hàng với khối lượng lớn và nhỏ từ thứ Hai đến thứ Bảy. Phí giao hàng thay đổi tùy theo khối lượng, loại sản phẩm và địa điểm. Vui lòng gọi số 904-555-0132 để biết chi tiết về giá. Quý khách không cần có mặt tại nhà khi giao hàng. Tuy nhiên, xin lưu ý rằng khu vực giao hàng được yêu cầu phải có lối vào phù hợp cho xe tải của chúng tôi. Trong trường hợp không đáp ứng được yêu cầu này, sẽ áp dụng phí nhập kho lại 50 đô la Mỹ.","qs":[{"n":149,"q":"What is true about Hampton Landscaping?","qvi":"Điều gì đúng về Hampton Landscaping?","opts":["It serves only private residences.","It delivers orders of varying sizes.","It charges one standard delivery fee.","It makes deliveries seven days a week."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: “we offer large- and small-volume deliveries” (giao hàng khối lượng lớn và nhỏ) → giao đơn hàng nhiều kích cỡ. (A) sai vì giao cả “businesses”; (C) sai vì “Delivery rates vary”; (D) sai vì chỉ “Monday through Saturday”.\n(A) Công ty chỉ phục vụ nhà ở tư nhân.\n(B) Công ty giao các đơn hàng với kích cỡ khác nhau.\n(C) Công ty tính một mức phí giao hàng cố định.\n(D) Công ty giao hàng cả bảy ngày trong tuần."},{"n":150,"q":"In what situation would a customer be billed $50?","qvi":"Trong tình huống nào khách hàng sẽ bị tính phí 50 đô la?","opts":["When the products to be delivered exceed a specific weight","When the customer is not present to receive an order","When the delivery address is not within the metro area","When a delivery driver cannot access a drop-off location"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: “the requested delivery area must be accessible for our trucks. In the event that this requirement is not met, a $50 restocking fee will be charged.” (khu vực giao hàng phải để xe tải vào được; nếu không, tính phí 50 đô) → tài xế không tiếp cận được điểm giao hàng. (B) sai vì “You do not need to be home for delivery”.\n(A) Khi hàng hóa giao vượt quá một mức cân nặng quy định\n(B) Khi khách hàng không có mặt để nhận hàng\n(C) Khi địa chỉ giao hàng nằm ngoài khu vực thành phố\n(D) Khi tài xế không thể tiếp cận địa điểm giao hàng"}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Hannah Fisk (1:18 P.M.)</b></p><p>Hi, Frank. I was wondering if you could check the budget report I’ve been working on before I submit it to Accounting later this afternoon. I want to make sure that my estimates are sound.</p></div><div class=\"msg\"><p><b>Frank Gerlin (1:20 P.M.)</b></p><p>Can you give me 45 minutes or so? I’m in the middle of my monthly performance update. It’s taking a little longer than I had expected.</p></div><div class=\"msg\"><p><b>Hannah Fisk (1:22 P.M.)</b></p><p>Oh, that’s fine! I’ll double-check the cost data in the meantime.</p></div><div class=\"msg\"><p><b>Frank Gerlin (1:24 P.M.)</b></p><p>Good idea. Those estimates can be tricky!</p></div><div class=\"msg\"><p><b>Hannah Fisk (1:25 P.M.)</b></p><p>Can I stop by your office at 2:30?</p></div><div class=\"msg\"><p><b>Frank Gerlin (1:26 P.M.)</b></p><p>Perfect. See you then.</p></div>"],"vi":"Hannah Fisk (1:18 chiều): Chào Frank. Tôi đang tự hỏi liệu anh có thể kiểm tra giúp tôi báo cáo ngân sách mà tôi đang làm trước khi tôi nộp cho phòng Kế toán vào cuối chiều nay không. Tôi muốn chắc chắn rằng các ước tính của mình là hợp lý.\n\nFrank Gerlin (1:20 chiều): Cô có thể cho tôi khoảng 45 phút được không? Tôi đang dở tay cập nhật báo cáo hiệu suất hàng tháng. Việc này mất nhiều thời gian hơn tôi dự kiến.\n\nHannah Fisk (1:22 chiều): Ồ, không sao cả! Trong thời gian đó tôi sẽ kiểm tra lại dữ liệu chi phí.\n\nFrank Gerlin (1:24 chiều): Ý hay đấy. Những ước tính đó có thể khá khó nhằn!\n\nHannah Fisk (1:25 chiều): Tôi có thể ghé văn phòng anh lúc 2:30 được không?\n\nFrank Gerlin (1:26 chiều): Hoàn hảo. Hẹn gặp cô lúc đó.","qs":[{"n":151,"q":"At 1:20 P.M., what does Mr. Gerlin imply when he writes, “Can you give me 45 minutes or so”?","qvi":"Lúc 1:20 chiều, khi viết “Can you give me 45 minutes or so” (Cô có thể cho tôi khoảng 45 phút không?), Mr. Gerlin ngụ ý điều gì?","opts":["He is willing to assist Ms. Fisk later.","His performance update was due yesterday.","Compiling cost estimates should take less than an hour.","He will complete the budget report himself."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Ms. Fisk nhờ kiểm tra báo cáo ngân sách; Mr. Gerlin đang bận cập nhật báo cáo hiệu suất nên xin khoảng 45 phút → anh ấy đồng ý giúp, nhưng để sau. Sau đó hai người hẹn gặp lúc 2:30.\n(A) Anh ấy sẵn sàng giúp Ms. Fisk sau đó.\n(B) Bản cập nhật hiệu suất của anh ấy lẽ ra phải xong từ hôm qua.\n(C) Việc tổng hợp ước tính chi phí sẽ mất chưa đến một giờ.\n(D) Anh ấy sẽ tự hoàn thành báo cáo ngân sách."},{"n":152,"q":"What will Ms. Fisk most likely do next?","qvi":"Ms. Fisk nhiều khả năng sẽ làm gì tiếp theo?","opts":["She will work on her monthly performance update.","She will ask Accounting to extend a deadline.","She will contact another colleague for advice.","She will review a portion of the budget report."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: “I’ll double-check the cost data in the meantime.” (Trong lúc đó tôi sẽ kiểm tra lại dữ liệu chi phí) → dữ liệu chi phí là một phần của báo cáo ngân sách. (A) sai vì báo cáo hiệu suất là việc của Mr. Gerlin.\n(A) Làm bản cập nhật hiệu suất hằng tháng của mình\n(B) Đề nghị phòng Kế toán gia hạn\n(C) Liên hệ đồng nghiệp khác để xin lời khuyên\n(D) Xem lại một phần của báo cáo ngân sách"}]},{"ns":[153,154],"head":"Questions 153-154 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Seo-Yun Jang &lt;s_jang@lazulinamail.com&gt;</p><p><b>From:</b> Travel Today &lt;team@traveltoday.com&gt;</p><p><b>Date:</b> March 18</p><p><b>Subject:</b> Price alert</p></div><p>Hello, Travel Today Subscriber,</p><p>You recently signed up for airfare notifications. Please see the information below for price cuts on your preferred trips. Remember that airlines usually offer a limited number of the lowest fares, so you may want to make a reservation soon to take advantage of these prices.</p><p>If you have questions or need assistance making reservations, please contact us at 210-555-0137.</p><p>Thank you,<br>Your Travel Today Team</p><table><tr><th colspan=\"2\">Trip 1: Seattle to Chicago<br>July 28<br>One way, 1 adult, economy seat</th></tr><tr><td>Nomata Airlines<br>1 stop (Denver)<br>2:42 P.M.–11:05 P.M.</td><td>Average price: $401<br>Current price: $315</td></tr><tr><td>Blue Range Airways<br>Nonstop<br>4:40 P.M.–10:40 P.M.</td><td>Average price: $439<br>Current price: $376</td></tr></table><table><tr><th colspan=\"2\">Trip 2: Los Angeles to New York<br>August 15<br>One way, 1 adult, comfort-plus seat</th></tr><tr><td>Nomata Airlines<br>1 stop (Houston)<br>6:00 A.M.–5:32 P.M.</td><td>Average price: $465<br>Current price: $385</td></tr><tr><td>Blue Range Airways<br>Nonstop<br>11:30 A.M.–8:00 P.M.</td><td>Average price: $518<br>Current price: $436</td></tr></table>"],"vi":"Đến: Seo-Yun Jang\nTừ: Travel Today\nNgày: 18 tháng 3\nTiêu đề: Thông báo giá vé\n\nXin chào Quý khách đăng ký Travel Today,\n\nGần đây, bạn đã đăng ký nhận thông báo về giá vé máy bay. Vui lòng xem thông tin bên dưới về việc giảm giá cho những chuyến đi mà bạn quan tâm. Hãy lưu ý rằng các hãng hàng không thường chỉ cung cấp số lượng giới hạn vé có giá thấp nhất, vì vậy bạn có thể muốn đặt chỗ sớm để tận dụng các mức giá này.\n\nNếu bạn có câu hỏi hoặc cần hỗ trợ đặt vé, vui lòng liên hệ với chúng tôi theo số 210-555-0137.\n\nTrân trọng,\nĐội ngũ Travel Today\n\nChuyến đi 1: Seattle → Chicago, ngày 28 tháng 7, một chiều, 1 người lớn, ghế hạng phổ thông\n- Nomata Airlines: 1 điểm dừng (Denver) | 2:42 chiều – 11:05 tối | Giá trung bình: 401 USD | Giá hiện tại: 315 USD\n- Blue Range Airways: Bay thẳng | 4:40 chiều – 10:40 tối | Giá trung bình: 439 USD | Giá hiện tại: 376 USD\n\nChuyến đi 2: Los Angeles → New York, ngày 15 tháng 8, một chiều, 1 người lớn, ghế comfort-plus\n- Nomata Airlines: 1 điểm dừng (Houston) | 6:00 sáng – 5:32 chiều | Giá trung bình: 465 USD | Giá hiện tại: 385 USD\n- Blue Range Airways: Bay thẳng | 11:30 sáng – 8:00 tối | Giá trung bình: 518 USD | Giá hiện tại: 436 USD","qs":[{"n":153,"q":"What is the purpose of the e-mail?","qvi":"Mục đích của e-mail là gì?","opts":["To confirm a purchase","To provide cost information","To request a seat upgrade","To cancel a reservation"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Tiêu đề “Price alert” và câu “Please see the information below for price cuts on your preferred trips” (Vui lòng xem thông tin giảm giá cho các chuyến bạn quan tâm) → e-mail cung cấp thông tin giá vé.\n(A) Xác nhận một giao dịch mua\n(B) Cung cấp thông tin về chi phí\n(C) Yêu cầu nâng hạng chỗ ngồi\n(D) Hủy đặt chỗ"},{"n":154,"q":"What do both trips have in common?","qvi":"Hai chuyến đi có điểm gì chung?","opts":["The departure date","The destination city","The choice of airlines","The type of seating"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Cả hai chuyến đều có lựa chọn Nomata Airlines và Blue Range Airways. Ngày (July 28/August 15), điểm đến (Chicago/New York) và loại ghế (economy/comfort-plus) đều khác nhau.\n(A) Ngày khởi hành\n(B) Thành phố điểm đến\n(C) Các hãng hàng không để lựa chọn\n(D) Loại chỗ ngồi"}]},{"ns":[155,157],"head":"Questions 155-157 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> rogelio.garza@gerimail.net</p><p><b>From:</b> sasha_lombardo@onyxmail.com</p><p><b>Date:</b> January 18</p><p><b>Subject:</b> My cookbook</p><p><b>Attachment:</b> Draft manuscript</p></div><p>Rogelio,</p><p>Here is the latest draft of the cookbook I will be self-publishing. Thank you for reviewing my recipes to ensure they are easy to follow. Your input is much appreciated. — <span class=\"pos\">[1]</span> —. This project has taken a lot of my energy over the past few years, and I am thrilled it is finally coming together. — <span class=\"pos\">[2]</span> —.</p><p>I already received feedback from a few others and was told that the instructions in some places were confusingly worded. — <span class=\"pos\">[3]</span> —. I am interested to know if you think so as well. I do have one request—when you respond, can you please include your comments in the margins so they are all in this one document? — <span class=\"pos\">[4]</span> —.</p><p>You’ll also notice that some pages have special boxes marked with a big red X. You can ignore those. I did not take great pictures of certain steps, so the Xs are reminders to take better ones to insert later.</p><p>Thanks again!</p><p>Sasha</p>"],"vi":"Đến: rogelio.garza@gerimail.net\nTừ: sasha_lombardo@onyxmail.com\nNgày: 18 tháng 1\nTiêu đề: Sách nấu ăn của tôi\nĐính kèm: Bản thảo (bản nháp)\n\nRogelio,\n\nĐây là bản nháp mới nhất của cuốn sách nấu ăn mà tôi sẽ tự xuất bản. Cảm ơn anh đã xem xét các công thức của tôi để đảm bảo rằng chúng dễ làm theo. Ý kiến đóng góp của anh thực sự rất đáng trân trọng. — [1] —. Dự án này đã tiêu tốn rất nhiều năng lượng của tôi trong vài năm qua, và tôi rất vui vì cuối cùng mọi thứ cũng đang dần hoàn thiện. — [2] —.\n\nTôi đã nhận được phản hồi từ một vài người khác và được cho biết rằng hướng dẫn ở một số chỗ khá khó hiểu. — [3] —. Tôi rất muốn biết anh có nghĩ vậy không. Tôi có một yêu cầu nhỏ — khi anh phản hồi, anh có thể vui lòng ghi nhận xét của mình ở phần lề để tất cả đều nằm trong cùng một tài liệu này không? — [4] —.\n\nAnh cũng sẽ thấy một số trang có các khung đặc biệt được đánh dấu bằng chữ X đỏ lớn. Anh có thể bỏ qua chúng. Tôi đã không chụp được những bức ảnh đẹp cho một số bước nhất định, vì vậy các dấu X là lời nhắc để chụp ảnh tốt hơn và chèn vào sau.\n\nCảm ơn anh một lần nữa!\nSasha","qs":[{"n":155,"q":"What does Ms. Lombardo ask Mr. Garza to do?","qvi":"Ms. Lombardo nhờ Mr. Garza làm gì?","opts":["Make sure her recipes are clear","Create an index of all her ingredients","Suggest possible publishers for her book","Help her format a final manuscript"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: “Thank you for reviewing my recipes to ensure they are easy to follow.” (Cảm ơn anh đã xem các công thức để đảm bảo chúng dễ làm theo) và “I am interested to know if you think so as well” (về hướng dẫn khó hiểu) → nhờ kiểm tra công thức có rõ ràng không. (C) sai vì cô tự xuất bản (self-publishing).\n(A) Đảm bảo các công thức nấu ăn của cô rõ ràng\n(B) Lập bảng tra cứu tất cả nguyên liệu\n(C) Gợi ý các nhà xuất bản có thể in sách cho cô\n(D) Giúp cô định dạng bản thảo cuối cùng"},{"n":156,"q":"What do boxes marked with a red X indicate?","qvi":"Các khung được đánh dấu X đỏ biểu thị điều gì?","opts":["Ideas for formatting modifications","Suggestions for inserting page breaks","Images that need to be replaced","Terms that should be defined"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: “I did not take great pictures of certain steps, so the Xs are reminders to take better ones to insert later.” (Tôi chụp ảnh một số bước chưa đẹp, nên dấu X nhắc tôi chụp ảnh tốt hơn để chèn vào sau) → hình ảnh cần thay thế.\n(A) Ý tưởng chỉnh sửa định dạng\n(B) Gợi ý vị trí chèn ngắt trang\n(C) Hình ảnh cần được thay thế\n(D) Các thuật ngữ cần được định nghĩa"},{"n":157,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“Otherwise it is hard to keep track of all the changes.”","qvi":"Câu sau phù hợp nhất với vị trí nào trong [1], [2], [3], [4]?\n“Nếu không thì rất khó theo dõi tất cả các thay đổi.”","opts":["[1]","[2]","[3]","[4]"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Câu thêm vào giải thích lý do cần ghi nhận xét chung trong một tài liệu → đặt ngay sau yêu cầu “can you please include your comments in the margins so they are all in this one document?” (anh ghi nhận xét ở lề để tất cả nằm trong một tài liệu) → vị trí [4]. “Otherwise” = nếu không làm vậy."}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following letter.","passages":["<p>Priscilla Yamaguchi<br>Falkenweg 19<br>10719 Berlin</p><p>23 March</p><p>Dear Ms. Yamaguchi,</p><p>I am writing to you to share the exciting news that Aqua Voyage Cruise Lines will be expanding its fleet next July. As part of our plan, we would welcome the opportunity to form a partnership with you.</p><p>You have established a solid reputation regarding your restaurant chain, Saffron Moon. Your commitment to offering your customers across Europe unique and delicious menu items aligns with our vision for providing cruise-ship passengers with distinct restaurant options.</p><p>There are several benefits of entering into a partnership with us. Since our cruise excursions attract a diverse group of people, an even more extensive group will become familiar with your restaurant chain. Aqua Voyage Cruise Lines will mention your top-rated chain in our brochures and feature it on our Web site. Through our network of suppliers, we can help negotiate exceptionally low rates for recipe ingredients and restaurant equipment, thereby reducing your expenses.</p><p>If you are interested in pursuing this proposition and wish to discuss the details, you can reach me at kbasrawi@aquavoyagecruiselines.de or by phone at 30-23125 032.</p><p>Sincerely,</p><p><i>Khalid Basrawi</i></p><p>Khalid Basrawi, Vice President of Corporate Development<br>Aqua Voyage Cruise Lines</p>"],"vi":"Priscilla Yamaguchi\nFalkenweg 19\n10719 Berlin\n\nNgày 23 tháng 3\n\nKính gửi bà Yamaguchi,\n\nTôi viết thư này để chia sẻ tin vui rằng Aqua Voyage Cruise Lines sẽ mở rộng đội tàu vào tháng Bảy tới. Trong kế hoạch đó, chúng tôi rất mong có cơ hội hợp tác với bà.\n\nBà đã xây dựng được uy tín vững chắc với chuỗi nhà hàng Saffron Moon. Cam kết của bà trong việc mang đến cho khách hàng trên khắp châu Âu những món ăn độc đáo và ngon miệng rất phù hợp với tầm nhìn của chúng tôi trong việc cung cấp cho hành khách tàu du lịch những lựa chọn nhà hàng khác biệt.\n\nViệc hợp tác với chúng tôi mang lại nhiều lợi ích. Do các chuyến du lịch bằng tàu thu hút nhiều đối tượng khách đa dạng, sẽ có thêm rất nhiều người biết đến chuỗi nhà hàng của bà. Aqua Voyage Cruise Lines sẽ giới thiệu chuỗi nhà hàng được đánh giá hàng đầu của bà trong các tờ quảng cáo và trên website. Thông qua mạng lưới nhà cung cấp của chúng tôi, chúng tôi có thể giúp đàm phán mức giá đặc biệt thấp cho nguyên liệu nấu ăn và thiết bị nhà hàng, từ đó giảm chi phí cho bà.\n\nNếu bà quan tâm đến đề xuất này và muốn trao đổi chi tiết, bà có thể liên hệ với tôi qua kbasrawi@aquavoyagecruiselines.de hoặc qua điện thoại số 30-23125 032.\n\nTrân trọng,\nKhalid Basrawi, Phó Chủ tịch phụ trách Phát triển Doanh nghiệp\nAqua Voyage Cruise Lines","qs":[{"n":158,"q":"What is suggested about Ms. Yamaguchi?","qvi":"Điều gì được gợi ý về Ms. Yamaguchi?","opts":["She has won several business awards.","She has scheduled a cruise vacation in July.","She operates restaurants in multiple European locations.","She is planning to revise her restaurant chain’s menu."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: “your restaurant chain, Saffron Moon” (chuỗi nhà hàng) và “offering your customers across Europe unique and delicious menu items” (phục vụ khách hàng khắp châu Âu) → bà điều hành nhà hàng ở nhiều địa điểm tại châu Âu.\n(A) Bà đã thắng nhiều giải thưởng kinh doanh.\n(B) Bà đã lên lịch một chuyến du thuyền vào tháng Bảy.\n(C) Bà điều hành nhà hàng ở nhiều nơi tại châu Âu.\n(D) Bà đang định sửa đổi thực đơn của chuỗi nhà hàng."},{"n":159,"q":"The word “solid” in paragraph 2, line 1, is closest in meaning to","qvi":"Từ “solid” ở đoạn 2, dòng 1 gần nghĩa nhất với","opts":["precise","reliable","compact","thorough"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: “You have established a solid reputation” = bà đã xây dựng uy tín vững chắc, đáng tin cậy → solid ≈ reliable.\n(A) chính xác\n(B) đáng tin cậy\n(C) nhỏ gọn\n(D) kỹ lưỡng"},{"n":160,"q":"What is NOT mentioned as a benefit of the proposed partnership?","qvi":"Điều gì KHÔNG được nêu là lợi ích của việc hợp tác được đề xuất?","opts":["Increased advertising opportunities","Lower cost for food preparation supplies","Exposure to a new customer base","Quality training programs"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: (A) “mention your top-rated chain in our brochures and feature it on our Web site”; (B) “negotiate exceptionally low rates for recipe ingredients”; (C) “an even more extensive group will become familiar with your restaurant chain”. Thư không nhắc đến chương trình đào tạo → (D).\n(A) Thêm cơ hội quảng cáo\n(B) Giảm chi phí nguyên liệu chế biến món ăn\n(C) Tiếp cận nhóm khách hàng mới\n(D) Các chương trình đào tạo chất lượng"}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following article.","passages":["<h3>KMC Scores Major Triumph</h3><p>WESTERN AUSTRALIA (21 June)—On 19 June, Western Australia’s Karinya Medical Centre (KMC) was awarded the Valorcare Foundation’s Stellar Service Merit, regarded as one of the highest honours an Australian hospital can receive. To qualify for the award, hospitals must meet a set of criteria, including timely access to care, superior medical outcomes, extensive staff training, and exceptional patient satisfaction.</p><p>“Congratulations to KMC’s board of directors, management, and staff,” said Lee Cinder, president of the Valorcare Foundation. “The centre has consistently demonstrated dedication to high-quality care; therefore, we are pleased to recognise it this year as one of the nation’s outstanding medical facilities.”</p><p>Dr. Linh Nguyen, who became CEO of KMC last March, said, “We are extremely proud that KMC is among the seven hospitals in the country recognised by the Valorcare Foundation. This award reflects our commitment to putting patient well-being at the forefront of everything we do. Since KMC opened its doors, we have set high patient care standards and strive to maintain this goal every year. For 47 years now, I believe we have been quite successful in this endeavour.”</p>"],"vi":"KMC ĐẠT ĐƯỢC THÀNH TỰU LỚN\n\nTÂY ÚC (21 tháng 6) — Ngày 19 tháng 6, Trung tâm Y tế Karinya (KMC) của bang Tây Úc đã được trao Giải thưởng Stellar Service Merit của Quỹ Valorcare, được xem là một trong những danh hiệu cao quý nhất mà một bệnh viện tại Úc có thể nhận được. Để đủ điều kiện nhận giải thưởng này, các bệnh viện phải đáp ứng một loạt tiêu chí, bao gồm khả năng tiếp cận dịch vụ chăm sóc kịp thời, kết quả điều trị vượt trội, đào tạo nhân viên chuyên sâu và mức độ hài lòng của bệnh nhân đặc biệt cao.\n\n“Xin chúc mừng ban giám đốc, đội ngũ quản lý và toàn thể nhân viên của KMC,” ông Lee Cinder, Chủ tịch Quỹ Valorcare, cho biết. “Trung tâm này đã liên tục thể hiện sự tận tâm đối với dịch vụ chăm sóc chất lượng cao; vì vậy, chúng tôi rất vui mừng công nhận KMC trong năm nay là một trong những cơ sở y tế xuất sắc của cả nước.”\n\nBác sĩ Linh Nguyen, người trở thành Giám đốc điều hành (CEO) của KMC vào tháng Ba năm ngoái, cho biết: “Chúng tôi vô cùng tự hào khi KMC nằm trong số bảy bệnh viện trên toàn quốc được Quỹ Valorcare vinh danh. Giải thưởng này phản ánh cam kết của chúng tôi trong việc đặt sức khỏe của bệnh nhân lên hàng đầu trong mọi việc chúng tôi làm. Kể từ khi KMC mở cửa, chúng tôi đã đặt ra các tiêu chuẩn chăm sóc bệnh nhân cao và luôn nỗ lực duy trì mục tiêu này qua từng năm. Trong suốt 47 năm qua, tôi tin rằng chúng tôi đã khá thành công trong nỗ lực này.”","qs":[{"n":161,"q":"What is one purpose of the article?","qvi":"Một mục đích của bài báo là gì?","opts":["To announce a hospital merger","To offer praise to an organization","To explain the reasons for a leadership change","To emphasize the need for high-quality care"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Bài báo đưa tin KMC “was awarded the Valorcare Foundation’s Stellar Service Merit” (được trao giải thưởng) và trích lời chúc mừng “Congratulations to KMC’s board of directors, management, and staff” → khen ngợi một tổ chức.\n(A) Công bố việc sáp nhập bệnh viện\n(B) Khen ngợi một tổ chức\n(C) Giải thích lý do thay đổi lãnh đạo\n(D) Nhấn mạnh nhu cầu chăm sóc chất lượng cao"},{"n":162,"q":"What is NOT indicated about KMC?","qvi":"Điều gì KHÔNG được nêu về KMC?","opts":["It has been in operation for more than four decades.","It has high patient-satisfaction ratings.","It recently appointed a new leader.","It has received many honors over the years."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: (A) “For 47 years now” → hơn 40 năm; (B) tiêu chí giải thưởng gồm “exceptional patient satisfaction” và KMC đã đạt giải; (C) “Dr. Linh Nguyen, who became CEO of KMC last March” → lãnh đạo mới. Bài chỉ nói về một giải thưởng năm nay, không nói KMC đã nhận nhiều giải qua các năm → (D).\n(A) Đã hoạt động hơn bốn thập kỷ\n(B) Có mức độ hài lòng của bệnh nhân cao\n(C) Gần đây đã bổ nhiệm lãnh đạo mới\n(D) Đã nhận nhiều giải thưởng qua các năm"},{"n":163,"q":"The word “reflects” in paragraph 3, line 5, is closest in meaning to","qvi":"Từ “reflects” ở đoạn 3, dòng 5 gần nghĩa nhất với","opts":["shows","notices","imitates","recommends"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: “This award reflects our commitment to putting patient well-being at the forefront” = giải thưởng này phản ánh / cho thấy cam kết của chúng tôi → reflects ≈ shows.\n(A) cho thấy\n(B) chú ý\n(C) bắt chước\n(D) khuyến nghị"}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Alexa Balog (4:02 P.M.)</b></p><p>I’m on lifeguard duty today at Rosemoor Park. Jamie Kerr asked me to fill in for him. Just letting you know that I’ve had to close the pool several times because of the bad weather.</p></div><div class=\"msg\"><p><b>Maxwell Diego (4:03 P.M.)</b></p><p>Is the weather bad right now?</p></div><div class=\"msg\"><p><b>Alexa Balog (4:03 P.M.)</b></p><p>No, but it was raining heavily about 20 minutes ago.</p></div><div class=\"msg\"><p><b>Maxwell Diego (4:04 P.M.)</b></p><p>Then you’ll have to wait ten more minutes before reopening. As you know, the rule for Pool Guardian lifeguards is to wait for 30 minutes after bad weather passes.</p></div><div class=\"msg\"><p><b>Alexa Balog (4:06 P.M.)</b></p><p>Yes, I understand. But no one has been here since 2:30. Can I close the pool now?</p></div><div class=\"msg\"><p><b>Maxwell Diego (4:07 P.M.)</b></p><p>That would make sense. What’s our policy on that, Mr. Nolan?</p></div><div class=\"msg\"><p><b>Wade Nolan (4:08 P.M.)</b></p><p>Sorry, but we can’t. Our contract says we must supply Rosemoor Park with a lifeguard until 5 P.M. on Thursdays. So Alexa needs to stay.</p></div><div class=\"msg\"><p><b>Alexa Balog (4:09 P.M.)</b></p><p>OK. I’m in the equipment shed. I’ve been cleaning it up and straightening up the pool supplies here.</p></div><div class=\"msg\"><p><b>Wade Nolan (4:10 P.M.)</b></p><p>But if there’s heavy rain again after 4:30, just go ahead and close things up, Alexa.</p></div><div class=\"msg\"><p><b>Maxwell Diego (4:10 P.M.)</b></p><p>It must be spotless now.</p></div><div class=\"msg\"><p><b>Alexa Balog (4:11 P.M.)</b></p><p>It has never looked so good. And thanks, Mr. Nolan.</p></div>"],"vi":"Alexa Balog (4:02 chiều): Hôm nay tôi trực cứu hộ ở Công viên Rosemoor. Jamie Kerr đã nhờ tôi trực thay anh ấy. Tôi chỉ muốn báo cho mọi người biết là tôi đã phải đóng cửa hồ bơi vài lần vì thời tiết xấu.\n\nMaxwell Diego (4:03 chiều): Bây giờ thời tiết có xấu không?\n\nAlexa Balog (4:03 chiều): Không, nhưng khoảng 20 phút trước trời mưa rất to.\n\nMaxwell Diego (4:04 chiều): Vậy thì cô phải chờ thêm mười phút nữa rồi mới mở lại. Như cô biết, quy định đối với nhân viên cứu hộ của Pool Guardian là phải chờ 30 phút sau khi thời tiết xấu qua đi.\n\nAlexa Balog (4:06 chiều): Vâng, tôi hiểu. Nhưng từ 2:30 đến giờ không có ai ở đây cả. Tôi có thể đóng cửa hồ bơi bây giờ không?\n\nMaxwell Diego (4:07 chiều): Nghe cũng hợp lý. Chính sách của chúng ta về việc này thế nào, thưa ông Nolan?\n\nWade Nolan (4:08 chiều): Xin lỗi, nhưng chúng ta không thể. Hợp đồng của chúng ta quy định phải cung cấp nhân viên cứu hộ cho Công viên Rosemoor đến 5 giờ chiều vào các ngày thứ Năm. Vì vậy Alexa cần phải ở lại.\n\nAlexa Balog (4:09 chiều): Được rồi. Tôi đang ở trong kho thiết bị. Tôi đã dọn dẹp kho và sắp xếp lại các vật dụng của hồ bơi ở đây.\n\nWade Nolan (4:10 chiều): Nhưng nếu sau 4:30 lại mưa lớn thì cứ đóng cửa mọi thứ nhé, Alexa.\n\nMaxwell Diego (4:10 chiều): Chắc bây giờ nó sạch bong rồi.\n\nAlexa Balog (4:11 chiều): Nó chưa bao giờ trông đẹp như thế. Và cảm ơn ông, ông Nolan.","qs":[{"n":164,"q":"What can be concluded about Ms. Balog?","qvi":"Có thể kết luận điều gì về Ms. Balog?","opts":["She is afraid of heavy rain.","She was hired to clean the pool.","She is an employee of Pool Guardian.","She works at Rosemoor Park every Thursday."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Mr. Diego nói với cô: “As you know, the rule for Pool Guardian lifeguards is to wait for 30 minutes…” (Như cô biết, quy định cho nhân viên cứu hộ của Pool Guardian…) → cô là nhân viên cứu hộ của Pool Guardian. (D) sai vì hôm nay cô chỉ trực thay Jamie Kerr.\n(A) Cô ấy sợ mưa lớn.\n(B) Cô ấy được thuê để dọn hồ bơi.\n(C) Cô ấy là nhân viên của Pool Guardian.\n(D) Cô ấy làm việc ở Rosemoor Park mỗi thứ Năm."},{"n":165,"q":"Why does Ms. Balog want to close the pool early?","qvi":"Vì sao Ms. Balog muốn đóng cửa hồ bơi sớm?","opts":["Because she has completed all her duties","Because Mr. Kerr has not arrived","Because she is not allowed to swim","Because no guests are currently using the pool"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: “But no one has been here since 2:30. Can I close the pool now?” (Từ 2:30 không có ai ở đây. Tôi đóng cửa hồ bơi bây giờ được không?) → vì không có khách.\n(A) Vì cô đã làm xong mọi nhiệm vụ\n(B) Vì Mr. Kerr chưa đến\n(C) Vì cô không được phép bơi\n(D) Vì hiện không có khách nào dùng hồ bơi"},{"n":166,"q":"What is implied about Rosemoor Park?","qvi":"Điều gì được ngụ ý về Rosemoor Park?","opts":["It has a contract with a company that provides lifeguards.","Its pool has been closed all week.","Its pool has been poorly maintained.","It would like to hire Ms. Balog to work full-time."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Mr. Nolan (Pool Guardian): “Our contract says we must supply Rosemoor Park with a lifeguard until 5 P.M. on Thursdays.” (Hợp đồng quy định chúng ta phải cung cấp nhân viên cứu hộ cho Rosemoor Park) → công viên có hợp đồng với công ty cung cấp nhân viên cứu hộ.\n(A) Công viên có hợp đồng với một công ty cung cấp nhân viên cứu hộ.\n(B) Hồ bơi của công viên đã đóng cửa cả tuần.\n(C) Hồ bơi được bảo trì kém.\n(D) Công viên muốn thuê Ms. Balog làm toàn thời gian."},{"n":167,"q":"At 4:11 P.M., what does Ms. Balog most likely mean when she writes, “It has never looked so good”?","qvi":"Lúc 4:11 chiều, Ms. Balog nhiều khả năng có ý gì khi viết “It has never looked so good” (Nó chưa bao giờ trông đẹp như thế)?","opts":["She washed the pool deck.","She did a good job organizing the equipment shed.","The rain has finally stopped.","The water in the pool is extremely clear."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Cô nói “I’m in the equipment shed. I’ve been cleaning it up and straightening up the pool supplies here.”; Mr. Diego đáp “It must be spotless now.” (Chắc giờ nó sạch bong rồi) → “It” là kho thiết bị, ý cô là đã dọn dẹp, sắp xếp kho rất tốt.\n(A) Cô ấy đã cọ rửa sàn quanh hồ bơi.\n(B) Cô ấy đã sắp xếp kho thiết bị rất tốt.\n(C) Cơn mưa cuối cùng đã tạnh.\n(D) Nước hồ bơi cực kỳ trong."}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following Web page.","passages":["<p>https://www.sagemontservices.com</p><p>Home | <b>About Us</b> | IT Services | Client Testimonials</p><p>At Sagemont Services, we offer custom-tailored information technology solutions to clients in various industries. Founded over twenty years ago, Sagemont Services began as a start-up competing with larger businesses in a crowded field. — <span class=\"pos\">[1]</span> —. Subsequently, we have become a leader in the industry. Our expert staff members are cross-trained in every aspect of our services.</p><p>We have helped several businesses complete technology projects on tight deadlines in the past few months. — <span class=\"pos\">[2]</span> —. For example, with the online retailer Clothing Discounters rapidly expanding, we assisted the company in increasing its call-center capability. Specifically, in just two days, we provided the company with all the equipment and connections needed for newly hired customer-service agents to handle calls from home. — <span class=\"pos\">[3]</span> —.</p><p>To learn more about how we meet the needs of our customers, please visit the Client Testimonials page. — <span class=\"pos\">[4]</span> —.</p>"],"vi":"Trang chủ | Về chúng tôi | Dịch vụ CNTT | Ý kiến khách hàng\n\nTại Sagemont Services, chúng tôi cung cấp các giải pháp công nghệ thông tin được thiết kế riêng cho khách hàng thuộc nhiều ngành nghề khác nhau. Được thành lập hơn hai mươi năm trước, Sagemont Services khởi đầu là một công ty khởi nghiệp, cạnh tranh với các doanh nghiệp lớn hơn trong một lĩnh vực đông đúc. — [1] —. Sau đó, chúng tôi đã trở thành đơn vị dẫn đầu trong ngành. Đội ngũ nhân viên chuyên môn của chúng tôi được đào tạo chéo trong mọi khía cạnh của dịch vụ.\n\nTrong vài tháng gần đây, chúng tôi đã giúp nhiều doanh nghiệp hoàn thành các dự án công nghệ với thời hạn gấp rút. — [2] —. Ví dụ, khi nhà bán lẻ trực tuyến Clothing Discounters đang mở rộng nhanh chóng, chúng tôi đã hỗ trợ công ty này nâng cao năng lực trung tâm chăm sóc khách hàng qua điện thoại. Cụ thể, chỉ trong hai ngày, chúng tôi đã cung cấp cho công ty toàn bộ thiết bị và kết nối cần thiết để các nhân viên dịch vụ khách hàng mới được tuyển có thể nhận cuộc gọi tại nhà. — [3] —.\n\nĐể tìm hiểu thêm về cách chúng tôi đáp ứng nhu cầu của khách hàng, vui lòng truy cập trang Client Testimonials (Ý kiến khách hàng). — [4] —.","qs":[{"n":168,"q":"What kind of business is Sagemont Services?","qvi":"Sagemont Services là loại hình doanh nghiệp gì?","opts":["A technology consulting firm","A telephone service provider","A computer software supplier","An executive recruiting service"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: “we offer custom-tailored information technology solutions to clients in various industries” (cung cấp giải pháp CNTT thiết kế riêng cho khách hàng nhiều ngành) → công ty tư vấn công nghệ.\n(A) Công ty tư vấn công nghệ\n(B) Nhà cung cấp dịch vụ điện thoại\n(C) Nhà cung cấp phần mềm máy tính\n(D) Dịch vụ tuyển dụng nhân sự cấp cao"},{"n":169,"q":"According to the Web page, what has Sagemont Services done recently?","qvi":"Theo trang web, gần đây Sagemont Services đã làm gì?","opts":["It has developed a series of online workshops.","It has hired additional staff members.","It has updated some space in its main office.","It has completed projects within a short time period."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: “We have helped several businesses complete technology projects on tight deadlines in the past few months.” (Vài tháng qua đã giúp nhiều doanh nghiệp hoàn thành dự án với thời hạn gấp) → tight deadlines = short time period. (B) sai vì nhân viên mới được tuyển là của Clothing Discounters.\n(A) Phát triển một loạt hội thảo trực tuyến\n(B) Tuyển thêm nhân viên\n(C) Cải tạo một số không gian ở văn phòng chính\n(D) Hoàn thành các dự án trong thời gian ngắn"},{"n":170,"q":"What is indicated about Clothing Discounters?","qvi":"Điều gì được nêu về Clothing Discounters?","opts":["It has won awards.","It is growing quickly.","It is less than one year old.","It plans to open physical stores."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: “with the online retailer Clothing Discounters rapidly expanding” (Clothing Discounters đang mở rộng nhanh chóng) → rapidly expanding = growing quickly.\n(A) Công ty đã đoạt giải thưởng.\n(B) Công ty đang phát triển nhanh.\n(C) Công ty thành lập chưa đến một năm.\n(D) Công ty định mở cửa hàng thực."},{"n":171,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“This solution eliminated the possibility of business disruption.”","qvi":"Câu sau phù hợp nhất với vị trí nào trong [1], [2], [3], [4]?\n“Giải pháp này đã loại bỏ khả năng gián đoạn kinh doanh.”","opts":["[1]","[2]","[3]","[4]"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: “This solution” phải chỉ một giải pháp vừa được nêu: việc cung cấp trong hai ngày toàn bộ thiết bị và kết nối để nhân viên mới nhận cuộc gọi tại nhà → câu đánh giá hiệu quả của giải pháp này đặt ngay sau ví dụ → vị trí [3]."}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following article.","passages":["<h3>MCAC to Exhibit Alonso’s Works</h3><p>MAURELY CITY (August 29)—Using recycled materials has become popular with artists, and local sculptor Ida Alonso has happily embraced this trend. Her new exhibition, <i>Throwaways into Treasure</i>, runs from today until November 4 at the Maurely City Art Center (MCAC).</p><p>Ms. Alonso had the idea for the project while reading about recycled plastic being made into park benches in the <i>Journal for Professional Landscape Architects</i>. She then began to collect old plastic bottles and cardboard shipping boxes and innovatively combined them with commercially made, recyclable building materials.</p><p>For the exhibition, Ms. Alonso has created a life-size imitation of commercial offices, with cubicles and partitions made from recovered materials. “By means of my synthetic office space, I am hoping to highlight the idea that old, unwanted objects can take on a new purpose,” Ms. Alonso said. Guests who attend the art show will have the opportunity to bring in their own recyclable plastic items and place them in large collection bags set up around the perimeter of the exhibition room. Ms. Alonso also plans to add more recyclable material to her installation as the show progresses.</p><p>Although MCAC will be the only venue for Ms. Alonso’s show, the exhibition is expected to travel in a different sense. On the exhibition’s final day, the works will be dismantled, and all the recyclable materials, including the items brought by visitors, will be transported to a Flyner Industries facility, where they will be shredded and transformed into material for waterproof curtains.</p><p>MCAC is open daily from 10:00 A.M. to 5:00 P.M. Admission to the art center is free. In addition to Ms. Alonso’s show, works by several local art students will be on view in MCAC’s main gallery.</p>"],"vi":"MCAC TRIỂN LÃM CÁC TÁC PHẨM CỦA ALONSO\n\nTHÀNH PHỐ MAURELY (29 tháng 8) — Việc sử dụng vật liệu tái chế đã trở nên phổ biến trong giới nghệ sĩ, và nhà điêu khắc địa phương Ida Alonso đã vui vẻ đón nhận xu hướng này. Triển lãm mới của bà, Throwaways into Treasure, diễn ra từ hôm nay đến ngày 4 tháng 11 tại Trung tâm Nghệ thuật Thành phố Maurely (MCAC).\n\nBà Alonso nảy ra ý tưởng cho dự án này khi đọc về việc nhựa tái chế được dùng để làm ghế công viên trên Tạp chí dành cho Kiến trúc sư Cảnh quan Chuyên nghiệp. Sau đó, bà bắt đầu thu thập chai nhựa cũ và thùng carton vận chuyển, rồi sáng tạo kết hợp chúng với các vật liệu xây dựng có thể tái chế được sản xuất thương mại.\n\nĐối với triển lãm này, bà Alonso đã tạo ra một mô hình kích thước thật mô phỏng các văn phòng thương mại, với các buồng làm việc và vách ngăn làm từ vật liệu thu hồi. “Thông qua không gian văn phòng nhân tạo của mình, tôi hy vọng làm nổi bật ý tưởng rằng những đồ vật cũ, không còn được cần đến có thể mang một mục đích mới,” bà Alonso chia sẻ. Khách tham quan triển lãm sẽ có cơ hội mang theo các vật dụng nhựa có thể tái chế của riêng mình và bỏ chúng vào các túi thu gom lớn đặt quanh chu vi phòng triển lãm. Bà Alonso cũng dự định bổ sung thêm vật liệu tái chế vào tác phẩm sắp đặt của mình khi triển lãm tiếp diễn.\n\nMặc dù MCAC sẽ là địa điểm duy nhất tổ chức triển lãm của bà Alonso, triển lãm này được kỳ vọng sẽ “di chuyển” theo một nghĩa khác. Vào ngày cuối cùng của triển lãm, các tác phẩm sẽ được tháo dỡ, và tất cả vật liệu tái chế, kể cả những vật dụng do khách mang đến, sẽ được chở đến một cơ sở của Flyner Industries, nơi chúng sẽ được nghiền nhỏ và biến thành vật liệu làm rèm chống nước.\n\nMCAC mở cửa hằng ngày từ 10:00 sáng đến 5:00 chiều. Vào cửa trung tâm nghệ thuật miễn phí. Ngoài triển lãm của bà Alonso, các tác phẩm của một số sinh viên nghệ thuật địa phương cũng sẽ được trưng bày tại phòng trưng bày chính của MCAC.","qs":[{"n":172,"q":"What is indicated about Ms. Alonso?","qvi":"Điều gì được nêu về Ms. Alonso?","opts":["She manages her own art gallery.","She previously worked for a shipping company.","She was inspired by an article in a trade publication.","She works part-time as an interior designer."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: “Ms. Alonso had the idea for the project while reading about recycled plastic being made into park benches in the Journal for Professional Landscape Architects.” → tạp chí dành cho kiến trúc sư chuyên nghiệp = trade publication (ấn phẩm chuyên ngành).\n(A) Bà quản lý phòng trưng bày nghệ thuật của riêng mình.\n(B) Bà từng làm cho một công ty vận chuyển.\n(C) Bà được truyền cảm hứng từ một bài viết trên một ấn phẩm chuyên ngành.\n(D) Bà làm bán thời gian như một nhà thiết kế nội thất."},{"n":173,"q":"According to the article, what will visitors to Ms. Alonso’s exhibition be able to do?","qvi":"Theo bài báo, khách tham quan triển lãm của Ms. Alonso sẽ có thể làm gì?","opts":["Meet local artists in person","Drop off recyclable plastics","Operate specialized office equipment","Purchase repurposed paper products"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: “Guests who attend the art show will have the opportunity to bring in their own recyclable plastic items and place them in large collection bags” (khách có thể mang đồ nhựa tái chế đến và bỏ vào túi thu gom) → drop off recyclable plastics.\n(A) Gặp trực tiếp các nghệ sĩ địa phương\n(B) Mang đồ nhựa tái chế đến bỏ lại\n(C) Sử dụng thiết bị văn phòng chuyên dụng\n(D) Mua sản phẩm giấy tái chế"},{"n":174,"q":"What will happen on November 4?","qvi":"Điều gì sẽ xảy ra vào ngày 4 tháng 11?","opts":["Parts of an exhibition will be taken to an industrial plant.","Some films about recycling will be shown.","Winners of a slogan contest will be announced.","An art center will close for renovations."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Triển lãm kéo dài “until November 4” → ngày 4/11 là ngày cuối. “On the exhibition’s final day, the works will be dismantled, and all the recyclable materials… will be transported to a Flyner Industries facility” (tác phẩm được tháo dỡ và vật liệu được chở đến cơ sở của Flyner Industries) → được mang đến nhà máy.\n(A) Các phần của triển lãm sẽ được chở đến một nhà máy.\n(B) Một số phim về tái chế sẽ được chiếu.\n(C) Công bố người thắng cuộc thi khẩu hiệu.\n(D) Một trung tâm nghệ thuật sẽ đóng cửa để sửa chữa."},{"n":175,"q":"What is indicated about MCAC?","qvi":"Điều gì được nêu về MCAC?","opts":["It requires reservations to visit.","It charges an entrance fee.","It displays works by art students.","It sponsors its own art workshops."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: “works by several local art students will be on view in MCAC’s main gallery” (tác phẩm của một số sinh viên nghệ thuật địa phương được trưng bày ở phòng chính) → (C). (B) sai vì “Admission to the art center is free”.\n(A) Phải đặt chỗ trước mới được tham quan.\n(B) Thu phí vào cửa.\n(C) Trưng bày tác phẩm của sinh viên nghệ thuật.\n(D) Tài trợ các buổi workshop nghệ thuật riêng."}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following table and article.","passages":["<h3>Superb Hotels—Lisbon<br>Customer Survey Results / June</h3><table><tr><th>Feature</th><th>Satisfaction Level</th><th>Change from May</th></tr><tr><td>Guest room</td><td>91%</td><td>+8% ↑</td></tr><tr><td>Breakfast</td><td>82%</td><td>+10% ↑</td></tr><tr><td>Reception</td><td>80%</td><td>–5% ↓</td></tr><tr><td>Overall experience</td><td>87%</td><td>+7% ↑</td></tr></table><p>Collected and analysed by Naomi Akdemir, Customer Solutions, Exelrate</p>","<h3>Exelrate Relocates Main Office</h3><p>TORONTO (3 July)—Consumer analysis giant Exelrate will soon begin construction of its new headquarters in Toronto. Many well-known businesses use Exelrate’s services to obtain an accurate understanding of their customers’ experiences. The company’s entry into North American markets is a promising sign of expected growth in the coming years. The recently promoted vice president of development, Rosa Martin, will be directing this expansion once she wraps up her work running the Customer Solutions Team at Exelrate’s current headquarters in Frankfurt at the end of this month.</p><p>The new office building was designed by Frank Tsudama, whose latest project involved Seoul’s futurist Global Trade Centre. Exelrate’s building will feature a ground-level courtyard with seating areas for public use, symbolising its insertion into the community. The establishment of companies like Exelrate will help cement Toronto’s fame as a centre for data and management consulting.</p>"],"vi":"BẢNG\nSuperb Hotels – Lisbon\nKết quả khảo sát khách hàng / Tháng 6\n\nHạng mục | Mức độ hài lòng | Thay đổi so với tháng 5\nPhòng khách | 91% | +8% (tăng)\nBữa sáng | 82% | +10% (tăng)\nLễ tân | 80% | –5% (giảm)\nTrải nghiệm tổng thể | 87% | +7% (tăng)\n\nDữ liệu được thu thập và phân tích bởi Naomi Akdemir, bộ phận Customer Solutions, công ty Exelrate.\n\nBÀI BÁO\nEXELRATE CHUYỂN TRỤ SỞ CHÍNH\n\nTORONTO (ngày 3 tháng 7) — Tập đoàn phân tích người tiêu dùng Exelrate sẽ sớm bắt đầu xây dựng trụ sở mới tại Toronto. Nhiều doanh nghiệp nổi tiếng sử dụng dịch vụ của Exelrate để có được sự hiểu biết chính xác về trải nghiệm của khách hàng. Việc công ty thâm nhập thị trường Bắc Mỹ là một dấu hiệu đầy hứa hẹn cho sự tăng trưởng trong những năm tới. Phó chủ tịch phát triển, bà Rosa Martin, người vừa được thăng chức, sẽ chỉ đạo quá trình mở rộng này sau khi bà hoàn tất công việc điều hành Nhóm Customer Solutions tại trụ sở hiện tại của Exelrate ở Frankfurt vào cuối tháng này.\n\nTòa nhà văn phòng mới được thiết kế bởi Frank Tsudama, người mà dự án gần đây nhất là Trung tâm Thương mại Toàn cầu mang phong cách tương lai của Seoul. Tòa nhà của Exelrate sẽ có khu sân trong ở tầng trệt với chỗ ngồi phục vụ công chúng, thể hiện sự gắn kết của công ty với cộng đồng. Việc các công ty như Exelrate thành lập tại đây sẽ giúp củng cố danh tiếng của Toronto như một trung tâm tư vấn dữ liệu và quản lý.","qs":[{"n":176,"q":"What does the table indicate about customers’ satisfaction with their overall experience?","qvi":"Bảng dữ liệu cho thấy điều gì về sự hài lòng của khách hàng với trải nghiệm tổng thể?","opts":["It is mentioned in marketing materials.","It is better than it was the previous month.","It is reported on a quarterly basis.","It decreased by five percent in June."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Bảng: \"Overall experience | 87% | +7% ↑\" (cột Change from May) → mức hài lòng tổng thể tăng 7% so với tháng 5 (tháng trước). (D) sai: mức giảm 5% là của Reception (Lễ tân).\n(A) Được nhắc đến trong tài liệu marketing\n(B) Tốt hơn so với tháng trước\n(C) Được báo cáo theo quý\n(D) Giảm 5% trong tháng Sáu"},{"n":177,"q":"What is suggested about Exelrate?","qvi":"Điều gì được gợi ý về Exelrate?","opts":["It both collects and analyzes data.","It is a hotel chain.","It renovates industrial buildings.","It was founded in Toronto."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Bảng: \"Collected and analysed by Naomi Akdemir, Customer Solutions, Exelrate\" (Được thu thập và phân tích bởi ... Exelrate) → Exelrate vừa thu thập vừa phân tích dữ liệu. (D) sai: trụ sở hiện tại ở Frankfurt, Toronto chỉ là trụ sở mới.\n(A) Công ty vừa thu thập vừa phân tích dữ liệu\n(B) Là chuỗi khách sạn\n(C) Chuyên sửa chữa các tòa nhà công nghiệp\n(D) Được thành lập tại Toronto"},{"n":178,"q":"In the article, the word “directing” in paragraph 1, line 10, is closest in meaning to","qvi":"Trong bài báo, từ “directing” ở đoạn 1, dòng 10, gần nghĩa nhất với","opts":["aiming","leading","financing","addressing"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"Rosa Martin, will be directing this expansion\" = bà Rosa Martin sẽ chỉ đạo/điều hành việc mở rộng này → directing = leading (dẫn dắt).\n(A) hướng đến, nhắm vào\n(B) dẫn dắt, lãnh đạo\n(C) cấp vốn\n(D) giải quyết, đề cập"},{"n":179,"q":"Where was Ms. Akdemir’s supervisor based in July?","qvi":"Vào tháng 7, cấp trên của bà Akdemir làm việc ở đâu?","opts":["In Toronto","In Lisbon","In Frankfurt","In Seoul"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Câu hỏi kết hợp 2 văn bản. Bảng: Naomi Akdemir làm ở bộ phận Customer Solutions của Exelrate. Bài báo (ngày 3/7): Rosa Martin đang \"running the Customer Solutions Team at Exelrate’s current headquarters in Frankfurt\" cho đến cuối tháng này (tháng 7) → cấp trên của bà Akdemir là Rosa Martin, làm việc ở Frankfurt trong tháng 7.\n(A) Ở Toronto\n(B) Ở Lisbon\n(C) Ở Frankfurt\n(D) Ở Seoul"},{"n":180,"q":"What is Mr. Tsudama’s area of expertise?","qvi":"Lĩnh vực chuyên môn của ông Tsudama là gì?","opts":["Management consulting","Tourism","Architecture","Hospitality"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Bài báo đoạn 2: \"The new office building was designed by Frank Tsudama, whose latest project involved Seoul’s futurist Global Trade Centre\" → ông thiết kế tòa nhà → chuyên môn là kiến trúc.\n(A) Tư vấn quản lý\n(B) Du lịch\n(C) Kiến trúc\n(D) Khách sạn – nhà hàng"}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following notice and review.","passages":["<h3>WELCOME TO RICHMOND SUPERMARKET!</h3><h4>DID YOU KNOW?</h4><p>Richmond Supermarket is now offering cooking classes in our own state-of-the-art kitchen, the same kitchen where we create flavourful soups, salads, and entrées for our prepared foods department. Every Monday evening from 7:00 P.M. to 8:30 P.M. we turn our kitchen over to a guest chef from one of Richmond’s many fine restaurants. Participants learn to prepare a different dish each week. Learn new techniques you can bring home to delight your friends and family! All classes use ingredients you can find right here in the store.</p><p>This month’s classes are as follows:</p><table><tr><td>2 August</td><td>Butter Chicken (India)</td></tr><tr><td>9 August</td><td>Pad Thai (Thailand)</td></tr><tr><td>16 August</td><td>Fish Tacos (Mexico)</td></tr><tr><td>23 August</td><td>Roast Vegetable Lasagna (Italy)</td></tr></table><p>The fee for each class is $55.00. To register, please call us at 604-555-0175 or visit www.richmondsupermarket.ca. There is a limit of 15 students per class. Classes sell out quickly, so reserve your spot today.</p>","<p>https://www.richmondsupermarket.ca/reviews</p><table><tr><td>Online Shopping</td><td>Contact Us</td><td><b>Reviews</b></td><td>Cooking Classes</td></tr></table><p>Thanks to Richmond Supermarket’s new cooking classes, community members can take lessons from some of the best chefs in the area. Last week I learned how to prepare fish tacos with Mateo Bernal, head chef at Bernal’s Restaurant. We made every component of the tacos from scratch, including the corn tortillas, grilled tilapia, and tomatillo salsa. Before leaving, each attendee received a small notebook containing the recipe we made that day as well as a few of Mr. Bernal’s other favourite recipes. I’m going to clear my Monday evenings so I can go back again and again!</p><p>–Astrid Klein</p>"],"vi":"THÔNG BÁO\nCHÀO MỪNG ĐẾN VỚI SIÊU THỊ RICHMOND!\nBẠN CÓ BIẾT KHÔNG?\n\nSiêu thị Richmond hiện đang tổ chức các lớp học nấu ăn trong nhà bếp hiện đại của riêng chúng tôi — cũng chính là nơi chúng tôi chế biến các món súp, salad và món chính đậm đà hương vị cho bộ phận thực phẩm chế biến sẵn. Mỗi tối thứ Hai từ 7:00 tối đến 8:30 tối, chúng tôi nhường nhà bếp cho một đầu bếp khách mời đến từ một trong nhiều nhà hàng danh tiếng của Richmond. Người tham gia sẽ học cách chuẩn bị một món ăn khác nhau mỗi tuần. Hãy học các kỹ thuật mới để mang về nhà làm hài lòng bạn bè và gia đình! Tất cả các lớp học đều sử dụng nguyên liệu bạn có thể tìm thấy ngay tại siêu thị.\n\nCác lớp học trong tháng này gồm:\n2 tháng 8: Gà bơ (Ấn Độ)\n9 tháng 8: Pad Thai (Thái Lan)\n16 tháng 8: Taco cá (Mexico)\n23 tháng 8: Lasagna rau củ nướng (Ý)\n\nHọc phí mỗi lớp là 55 đô la. Để đăng ký, vui lòng gọi 604-555-0175 hoặc truy cập www.richmondsupermarket.ca. Mỗi lớp giới hạn 15 học viên. Các lớp thường hết chỗ nhanh, vì vậy hãy đặt chỗ ngay hôm nay.\n\nTRANG ĐÁNH GIÁ\nhttps://www.richmondsupermarket.ca/reviews\nMua sắm trực tuyến | Liên hệ | Đánh giá | Lớp nấu ăn\n\nNhờ các lớp học nấu ăn mới của Siêu thị Richmond, các thành viên trong cộng đồng có thể học từ một số đầu bếp giỏi nhất trong khu vực. Tuần trước, tôi đã học cách làm taco cá cùng Mateo Bernal, bếp trưởng của Nhà hàng Bernal. Chúng tôi tự làm mọi thành phần của món taco từ đầu, bao gồm bánh tortilla bắp, cá rô phi nướng và sốt salsa tomatillo. Trước khi ra về, mỗi người tham dự đều nhận được một cuốn sổ nhỏ chứa công thức đã làm hôm đó cùng một vài công thức yêu thích khác của ông Bernal. Tôi sẽ dành trống các tối thứ Hai để có thể quay lại nhiều lần nữa!\n\n– Astrid Klein","qs":[{"n":181,"q":"For whom is the notice most likely intended?","qvi":"Thông báo này nhiều khả năng dành cho ai?","opts":["Kitchen workers","Store customers","Restaurant chefs","Cookbook authors"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Thông báo: \"WELCOME TO RICHMOND SUPERMARKET!\", \"All classes use ingredients you can find right here in the store\", \"To register, please call us...\" → thông báo dành cho khách hàng đến mua sắm ở siêu thị.\n(A) Nhân viên bếp\n(B) Khách hàng của cửa hàng\n(C) Đầu bếp nhà hàng\n(D) Tác giả sách nấu ăn"},{"n":182,"q":"What is indicated in the notice about August’s cooking classes at Richmond Supermarket?","qvi":"Thông báo cho biết điều gì về các lớp nấu ăn tháng 8 tại Siêu thị Richmond?","opts":["They feature dishes from different countries.","They are held on different days of the week.","They are taught by supermarket employees.","They require students to register in person."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Danh sách lớp: Butter Chicken (India), Pad Thai (Thailand), Fish Tacos (Mexico), Roast Vegetable Lasagna (Italy) → món ăn từ nhiều nước. (B) sai: lớp luôn vào tối thứ Hai. (C) sai: do đầu bếp khách mời từ nhà hàng dạy. (D) sai: đăng ký qua điện thoại hoặc website.\n(A) Có các món ăn từ nhiều quốc gia khác nhau\n(B) Được tổ chức vào các ngày khác nhau trong tuần\n(C) Được dạy bởi nhân viên siêu thị\n(D) Yêu cầu học viên đăng ký trực tiếp"},{"n":183,"q":"When most likely did Ms. Klein participate in a Richmond Supermarket cooking class?","qvi":"Bà Klein nhiều khả năng đã tham gia lớp nấu ăn của Siêu thị Richmond vào ngày nào?","opts":["On August 2","On August 9","On August 16","On August 23"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Câu hỏi kết hợp 2 văn bản. Bài đánh giá: \"Last week I learned how to prepare fish tacos\". Thông báo: \"16 August – Fish Tacos (Mexico)\" → bà Klein học vào ngày 16/8.\n(A) Ngày 2/8\n(B) Ngày 9/8\n(C) Ngày 16/8\n(D) Ngày 23/8"},{"n":184,"q":"What ingredient is NOT mentioned in the review?","qvi":"Nguyên liệu nào KHÔNG được nhắc đến trong bài đánh giá?","opts":["Corn tortillas","Grilled tilapia","Tomatillo salsa","Shredded cabbage"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Bài đánh giá: \"including the corn tortillas, grilled tilapia, and tomatillo salsa\" → (A), (B), (C) đều được nhắc đến; bắp cải thái sợi (shredded cabbage) không được nhắc.\n(A) Bánh tortilla bắp\n(B) Cá rô phi nướng\n(C) Sốt salsa tomatillo\n(D) Bắp cải thái sợi"},{"n":185,"q":"What does Ms. Klein say she intends to do?","qvi":"Bà Klein nói rằng bà dự định làm gì?","opts":["Take a trip to Mexico","Eat at Bernal’s Restaurant","Attend more cooking classes","Collect recipes in a notebook"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Bài đánh giá: \"I’m going to clear my Monday evenings so I can go back again and again!\" (Tôi sẽ dành trống các tối thứ Hai để quay lại nhiều lần nữa) → bà định tham gia thêm các lớp nấu ăn (lớp diễn ra vào tối thứ Hai).\n(A) Đi du lịch Mexico\n(B) Ăn ở Nhà hàng Bernal\n(C) Tham gia thêm các lớp nấu ăn\n(D) Sưu tầm công thức vào một cuốn sổ"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following article, schedule, and e-mail.","passages":["<h3>New Dean Appointed at Institute</h3><p>YORK (17 January)—The Callard Eye Institute announced on Tuesday that Jennifer Robbins, M.D., has accepted the position of dean, effective immediately.</p><p>Dr. Robbins, who grew up in York, earned her medical degree at Labato School of Medicine and completed a postdoctoral residency at Petersen Medical Center. Before she arrived at the institute, Dr. Robbins was the founder and director of the ophthalmology clinic at Morseville Hospital. Her innovations in treating eye diseases have benefited thousands of patients worldwide.</p><p>On April 17, Dr. Robbins will be in Berlin to receive the Kramer Medal for Medical Excellence at this year’s conference of the International Center for Vision Advancement.</p>","<h3>International Center for Vision Advancement (ICVA) Conference</h3><p><b>JT Pepper Convention Hall (17–19 April)<br>Rosenthaler Strasse 65, Berlin, Germany 25627</b></p><h4>Day 1 Schedule: Monday, 17 April</h4><table><tr><td>8:00–10:00 A.M.</td><td>Breakfast</td><td>Maiwald Lounge</td></tr><tr><td>10:00–11:00 A.M.</td><td>Welcome and keynote address</td><td>Jahn Conference Hall</td></tr><tr><td>11:15 A.M.–1:15 P.M.</td><td>Session 1: New Technologies</td><td>Breakout rooms, as assigned</td></tr><tr><td>1:30–3:30 P.M.</td><td>Lunch group seminar</td><td>Edwards Room</td></tr><tr><td>3:45–5:45 P.M.</td><td>Session 2: Quality Eye Care</td><td>Breakout rooms, as assigned</td></tr><tr><td>6:00–7:30 P.M.</td><td>Free period</td><td>---</td></tr><tr><td>7:30–9:00 P.M.</td><td>Dinner</td><td>Regal Ballroom</td></tr><tr><td>9:00–9:30 P.M.</td><td>Dessert and awards ceremony</td><td>Regal Ballroom</td></tr></table>","<div class=\"hdr\"><p><b>To:</b> Dae-Ho Sohn</p><p><b>From:</b> Paulina Raskin</p><p><b>Subject:</b> Your presentation</p><p><b>Date:</b> 22 April</p></div><p>Dear Dr. Sohn,</p><p>I just wanted to thank you again for speaking at the ICVA conference in Berlin last week. I am sure I am not alone in saying that the highlight of the conference was your keynote address. Your insights into recent advancements in eye-surgery techniques captured the attention of everyone in the room. We were grateful that you could join us and even more appreciative of all the help and guidance you have provided in the past as an active member of the ICVA Board of Directors.</p><p>Sincerely,</p><p>Paulina Raskin<br>President, International Center for Vision Advancement</p>"],"vi":"BÀI BÁO\nBỔ NHIỆM TÂN TRƯỞNG KHOA TẠI VIỆN\n\nYORK (17 tháng 1) — Viện Mắt Callard thông báo vào thứ Ba rằng bác sĩ Jennifer Robbins đã chấp nhận vị trí trưởng khoa, có hiệu lực ngay lập tức.\n\nBác sĩ Robbins, người lớn lên tại York, nhận bằng y khoa tại Trường Y Labato và hoàn thành chương trình nội trú sau tiến sĩ tại Trung tâm Y tế Petersen. Trước khi đến làm việc tại viện, bác sĩ Robbins là người sáng lập và giám đốc phòng khám nhãn khoa tại Bệnh viện Morseville. Những đổi mới của bà trong điều trị các bệnh về mắt đã mang lại lợi ích cho hàng nghìn bệnh nhân trên toàn thế giới.\n\nVào ngày 17 tháng 4, bác sĩ Robbins sẽ có mặt tại Berlin để nhận Huy chương Kramer về Xuất sắc Y khoa tại hội nghị năm nay của Trung tâm Quốc tế về Phát triển Thị giác.\n\nLỊCH TRÌNH\nHội nghị của Trung tâm Quốc tế về Phát triển Thị giác (ICVA)\nHội trường JT Pepper (17–19 tháng 4)\nRosenthaler Strasse 65, Berlin, Đức 25627\n\nLịch trình ngày 1: Thứ Hai, 17 tháng 4\n8:00–10:00 sáng | Ăn sáng | Maiwald Lounge\n10:00–11:00 sáng | Chào mừng và bài phát biểu khai mạc (keynote) | Hội trường Jahn\n11:15 sáng–1:15 chiều | Phiên 1: Công nghệ mới | Các phòng thảo luận nhóm, theo phân công\n1:30–3:30 chiều | Hội thảo nhóm kết hợp ăn trưa | Phòng Edwards\n3:45–5:45 chiều | Phiên 2: Chăm sóc mắt chất lượng | Các phòng thảo luận nhóm, theo phân công\n6:00–7:30 tối | Thời gian tự do | ---\n7:30–9:00 tối | Bữa tối | Sảnh Regal Ballroom\n9:00–9:30 tối | Tráng miệng và lễ trao giải | Sảnh Regal Ballroom\n\nE-MAIL\nGửi: Dae-Ho Sohn\nTừ: Paulina Raskin\nChủ đề: Bài thuyết trình của ông\nNgày: 22 tháng 4\n\nKính gửi Bác sĩ Sohn,\n\nTôi chỉ muốn cảm ơn ông một lần nữa vì đã phát biểu tại hội nghị ICVA ở Berlin tuần trước. Tôi tin rằng không chỉ mình tôi cho rằng điểm nhấn của hội nghị chính là bài phát biểu khai mạc của ông. Những hiểu biết sâu sắc của ông về các tiến bộ gần đây trong kỹ thuật phẫu thuật mắt đã thu hút sự chú ý của mọi người trong khán phòng. Chúng tôi rất biết ơn vì ông đã có thể tham dự cùng chúng tôi, và càng trân trọng hơn mọi sự hỗ trợ và hướng dẫn mà ông đã dành cho chúng tôi trước đây với tư cách là một thành viên tích cực của Ban Giám đốc ICVA.\n\nTrân trọng,\nPaulina Raskin\nChủ tịch, Trung tâm Quốc tế về Phát triển Thị giác","qs":[{"n":186,"q":"What is indicated about Dr. Robbins in the article?","qvi":"Bài báo cho biết điều gì về bác sĩ Robbins?","opts":["She is starting a new job.","She owns a house in York.","She specializes in designing eyeglasses.","She has taught classes in Berlin."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Bài báo đoạn 1: \"Jennifer Robbins, M.D., has accepted the position of dean, effective immediately\" (đã nhận chức trưởng khoa, có hiệu lực ngay) → bà đang bắt đầu công việc mới. (B) sai: bài chỉ nói bà lớn lên ở York.\n(A) Bà đang bắt đầu một công việc mới\n(B) Bà sở hữu một ngôi nhà ở York\n(C) Bà chuyên thiết kế kính mắt\n(D) Bà từng dạy học ở Berlin"},{"n":187,"q":"Where did Dr. Robbins complete her postdoctoral residency?","qvi":"Bác sĩ Robbins đã hoàn thành chương trình nội trú sau tiến sĩ ở đâu?","opts":["At the Callard Eye Institute","At Labato School of Medicine","At Petersen Medical Center","At Morseville Hospital"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Bài báo đoạn 2: \"completed a postdoctoral residency at Petersen Medical Center\". (B) là nơi bà nhận bằng y khoa; (D) là nơi bà sáng lập phòng khám.\n(A) Tại Viện Mắt Callard\n(B) Tại Trường Y Labato\n(C) Tại Trung tâm Y tế Petersen\n(D) Tại Bệnh viện Morseville"},{"n":188,"q":"Where most likely did Dr. Robbins receive the Kramer Medal?","qvi":"Bác sĩ Robbins nhiều khả năng đã nhận Huy chương Kramer ở đâu?","opts":["In the Maiwald Lounge","In the Jahn Conference Hall","In the Edwards Room","In the Regal Ballroom"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Câu hỏi kết hợp 2 văn bản. Bài báo: ngày 17/4 bà Robbins sẽ ở Berlin để nhận Huy chương Kramer tại hội nghị ICVA. Lịch trình ngày 17/4: \"9:00–9:30 P.M. Dessert and awards ceremony – Regal Ballroom\" (lễ trao giải ở Regal Ballroom) → bà nhận huy chương ở Regal Ballroom.\n(A) Ở phòng Maiwald Lounge\n(B) Ở Hội trường Jahn\n(C) Ở phòng Edwards\n(D) Ở sảnh Regal Ballroom"},{"n":189,"q":"Why did Ms. Raskin send the e-mail to Dr. Sohn?","qvi":"Vì sao bà Raskin gửi e-mail cho bác sĩ Sohn?","opts":["To ask him to join the board of the ICVA","To invite him to speak at a conference","To request information about his surgical techniques","To express gratitude for his participation in an event"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: E-mail: \"I just wanted to thank you again for speaking at the ICVA conference in Berlin last week\" → mục đích là cảm ơn ông vì đã tham gia (phát biểu) tại hội nghị. (A) sai: ông đã là thành viên ban giám đốc; (B) sai: hội nghị đã diễn ra.\n(A) Để mời ông tham gia ban giám đốc ICVA\n(B) Để mời ông phát biểu tại một hội nghị\n(C) Để hỏi thông tin về kỹ thuật phẫu thuật của ông\n(D) Để bày tỏ lòng biết ơn vì ông đã tham gia một sự kiện"},{"n":190,"q":"When did Dr. Sohn most likely make a speech on April 17?","qvi":"Vào ngày 17/4, bác sĩ Sohn nhiều khả năng đã phát biểu lúc mấy giờ?","opts":["At 8:00 A.M.","At 10:00 A.M.","At 11:15 A.M.","At 3:45 P.M."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Câu hỏi kết hợp 2 văn bản. E-mail: \"the highlight of the conference was your keynote address\" (ông có bài phát biểu khai mạc). Lịch trình: \"10:00–11:00 A.M. Welcome and keynote address\" → ông phát biểu lúc 10:00 sáng.\n(A) Lúc 8:00 sáng\n(B) Lúc 10:00 sáng\n(C) Lúc 11:15 sáng\n(D) Lúc 3:45 chiều"}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following Web page and e-mails.","passages":["<p>https://www.freewheeloasis.com/trade-in-and-consignment</p><table><tr><td>Home</td><td>Service and Repair</td><td><b>Trade-in and Consignment</b></td><td>Accessories</td></tr></table><p>Freewheel Oasis offers two programs that make selling your bicycle easier: trade-in and consignment. If you select our trade-in program, you give us your bicycle, and, in exchange, we give you credit toward the purchase of a new one. If you opt for our consignment program, we will sell your bicycle for you.</p><p>To take advantage of either option, e-mail us at programs@freewheeloasis.com to schedule an appointment. In your e-mail, you should also indicate whether you wish to trade in your bicycle or place it on consignment. You will receive a response from our customer service manager. We take appointments during regular business hours, Monday through Saturday from 9:00 A.M. to 5:00 P.M.</p><p>When you come in for your appointment, a technician will assess the condition of your bicycle, and a sales associate will determine its current value. If the value specified is acceptable to you and you wish to trade in your bicycle, we deduct that amount from the purchase price of your new bicycle. If you prefer a consignment arrangement, we will sell your bicycle for the agreed-upon amount. Note that we will withhold a service fee equal to 15 percent of this amount at the time your bicycle is sold, while the rest of the earnings will be sent to you.</p>","<div class=\"hdr\"><p><b>To:</b> programs@freewheeloasis.com</p><p><b>From:</b> Nicola Johnson &lt;njohnson92@rapidonet.com&gt;</p><p><b>Date:</b> November 2</p><p><b>Subject:</b> Appointment request</p></div><p>Hello,</p><p>I have a mountain bicycle that is now six years old. However, I only used it for the first three years. I have tried to sell it myself but was not successful, so I would like to place it on consignment with you. Therefore, I would like to schedule an appointment.</p><p>Also, I recently accepted a job in Kuwait and will be leaving on November 30. Do you expect that the bicycle will be sold by then? If not, how can I receive my portion of the selling price?</p><p>Best regards,</p><p>Nicola Johnson</p>","<div class=\"hdr\"><p><b>To:</b> Nicola Johnson &lt;njohnson92@rapidonet.com&gt;</p><p><b>From:</b> programs@freewheeloasis.com</p><p><b>Date:</b> November 2</p><p><b>Subject:</b> RE: Appointment request</p></div><p>Hi, Nicola,</p><p>Thanks for your interest in placing your bicycle on consignment with Freewheel Oasis. Your appointment is scheduled for Friday, November 4, at 3:00 P.M. Let me know if this arrangement works for you.</p><p>Our consignment policy stipulates that once the sale of a bicycle has been finalized, the money owed to the customer must be paid into the person’s bank account. Please note that Freewheel Oasis cannot guarantee the sale of a bicycle by a date specified by the bicycle owner.</p><p>Best of luck with your new endeavor!</p><p>Sincerely,</p><p>Peter Moran</p>"],"vi":"TRANG WEB\nhttps://www.freewheeloasis.com/trade-in-and-consignment\nTrang chủ | Dịch vụ và Sửa chữa | Đổi xe và Ký gửi | Phụ kiện\n\nFreewheel Oasis cung cấp hai chương trình giúp việc bán xe đạp của bạn trở nên dễ dàng hơn: đổi xe (trade-in) và ký gửi (consignment). Nếu bạn chọn chương trình đổi xe, bạn giao xe đạp cho chúng tôi và đổi lại, chúng tôi cho bạn một khoản tín dụng để mua xe mới. Nếu bạn chọn chương trình ký gửi, chúng tôi sẽ bán xe giúp bạn.\n\nĐể sử dụng một trong hai lựa chọn này, hãy gửi e-mail đến programs@freewheeloasis.com để đặt lịch hẹn. Trong e-mail, bạn cũng cần cho biết bạn muốn đổi xe hay ký gửi xe. Bạn sẽ nhận được phản hồi từ quản lý dịch vụ khách hàng của chúng tôi. Chúng tôi nhận lịch hẹn trong giờ làm việc thông thường, từ thứ Hai đến thứ Bảy, 9:00 sáng – 5:00 chiều.\n\nKhi bạn đến buổi hẹn, một kỹ thuật viên sẽ đánh giá tình trạng xe, và một nhân viên bán hàng sẽ xác định giá trị hiện tại của xe. Nếu bạn chấp nhận mức giá đưa ra và muốn đổi xe, chúng tôi sẽ trừ số tiền đó vào giá mua xe mới của bạn. Nếu bạn chọn hình thức ký gửi, chúng tôi sẽ bán xe theo mức giá đã thỏa thuận. Lưu ý rằng chúng tôi sẽ giữ lại phí dịch vụ bằng 15% số tiền này vào thời điểm xe được bán, phần tiền còn lại sẽ được chuyển cho bạn.\n\nE-MAIL 1\nGửi: programs@freewheeloasis.com\nTừ: Nicola Johnson <njohnson92@rapidonet.com>\nNgày: 2 tháng 11\nChủ đề: Yêu cầu đặt lịch hẹn\n\nXin chào,\n\nTôi có một chiếc xe đạp địa hình đến nay đã sáu năm tuổi. Tuy nhiên, tôi chỉ sử dụng nó trong ba năm đầu. Tôi đã cố gắng tự bán nhưng không thành công, vì vậy tôi muốn ký gửi xe tại cửa hàng. Do đó, tôi muốn đặt một lịch hẹn.\n\nNgoài ra, tôi vừa nhận một công việc ở Kuwait và sẽ rời đi vào ngày 30 tháng 11. Cửa hàng có nghĩ rằng xe sẽ được bán trước thời điểm đó không? Nếu không, tôi có thể nhận phần tiền bán xe của mình bằng cách nào?\n\nTrân trọng,\nNicola Johnson\n\nE-MAIL 2\nGửi: Nicola Johnson <njohnson92@rapidonet.com>\nTừ: programs@freewheeloasis.com\nNgày: 2 tháng 11\nChủ đề: RE: Yêu cầu đặt lịch hẹn\n\nChào Nicola,\n\nCảm ơn bạn đã quan tâm đến việc ký gửi xe đạp tại Freewheel Oasis. Lịch hẹn của bạn được sắp xếp vào thứ Sáu, ngày 4 tháng 11, lúc 3:00 chiều. Hãy cho tôi biết nếu thời gian này phù hợp với bạn.\n\nChính sách ký gửi của chúng tôi quy định rằng khi việc bán xe đã hoàn tất, số tiền trả cho khách hàng phải được chuyển vào tài khoản ngân hàng của người đó. Xin lưu ý rằng Freewheel Oasis không thể đảm bảo xe sẽ được bán trước một ngày cụ thể do chủ xe đưa ra.\n\nChúc bạn may mắn với công việc mới!\n\nTrân trọng,\nPeter Moran","qs":[{"n":191,"q":"According to the Web page, what is suggested about Freewheel Oasis?","qvi":"Theo trang web, điều gì được gợi ý về Freewheel Oasis?","opts":["It is currently having a sale on used bicycles.","It performs inspections on certain bicycles.","It has recently increased in popularity.","It is open daily."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Trang web đoạn 3: \"a technician will assess the condition of your bicycle\" (kỹ thuật viên sẽ đánh giá tình trạng xe đạp được đổi/ký gửi) → cửa hàng kiểm tra một số xe đạp. (D) sai: chỉ làm việc thứ Hai – thứ Bảy.\n(A) Đang giảm giá xe đạp cũ\n(B) Kiểm tra (đánh giá) một số xe đạp nhất định\n(C) Gần đây trở nên phổ biến hơn\n(D) Mở cửa hằng ngày"},{"n":192,"q":"What does Ms. Johnson indicate in her e-mail?","qvi":"Cô Johnson cho biết điều gì trong e-mail của mình?","opts":["She regularly travels abroad.","She got her bicycle six years ago.","She prefers an appointment on November 30.","She has made repairs to the bicycle by herself."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: E-mail 1: \"I have a mountain bicycle that is now six years old\" → cô có chiếc xe từ 6 năm trước. (C) sai: 30/11 là ngày cô rời đi Kuwait.\n(A) Cô thường xuyên đi nước ngoài\n(B) Cô có chiếc xe đạp từ sáu năm trước\n(C) Cô muốn hẹn vào ngày 30/11\n(D) Cô đã tự sửa xe đạp"},{"n":193,"q":"What can be concluded about Ms. Johnson?","qvi":"Có thể kết luận gì về cô Johnson?","opts":["She is currently working in Kuwait.","She has done business with Freewheel Oasis before.","She has agreed to let Freewheel Oasis charge her a service fee.","She plans to buy a bicycle from Freewheel Oasis."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Câu hỏi kết hợp 2 văn bản. E-mail 1: \"I would like to place it on consignment with you\" (cô chọn ký gửi). Trang web: với hình thức ký gửi, \"we will withhold a service fee equal to 15 percent\" → khi chọn ký gửi, cô đồng ý để cửa hàng giữ lại phí dịch vụ 15%. (A) sai: cô mới nhận việc và sẽ đi Kuwait vào 30/11.\n(A) Cô hiện đang làm việc ở Kuwait\n(B) Cô từng giao dịch với Freewheel Oasis trước đây\n(C) Cô đã đồng ý để Freewheel Oasis thu phí dịch vụ\n(D) Cô định mua xe đạp của Freewheel Oasis"},{"n":194,"q":"What is one purpose of Mr. Moran’s e-mail?","qvi":"Một trong những mục đích của e-mail của ông Moran là gì?","opts":["To ask for additional information about a service request","To request the rescheduling of an appointment","To indicate the completion date of a service","To state a company rule"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: E-mail 2: \"Our consignment policy stipulates that ... the money owed to the customer must be paid into the person’s bank account\" (Chính sách ký gửi quy định...) → ông Moran nêu quy định của công ty. (C) sai: ông nói không thể đảm bảo bán xe trước một ngày cụ thể.\n(A) Để hỏi thêm thông tin về một yêu cầu dịch vụ\n(B) Để đề nghị dời lịch hẹn\n(C) Để thông báo ngày hoàn thành một dịch vụ\n(D) Để nêu một quy định của công ty"},{"n":195,"q":"Who most likely is Mr. Moran?","qvi":"Ông Moran nhiều khả năng là ai?","opts":["A customer service manager","A bank accountant","A sales associate","A bicycle repair technician"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Câu hỏi kết hợp 2 văn bản. Trang web: khi e-mail đến programs@freewheeloasis.com, \"You will receive a response from our customer service manager\". E-mail 2 là thư trả lời từ programs@freewheeloasis.com, ký tên Peter Moran → ông Moran là quản lý dịch vụ khách hàng.\n(A) Quản lý dịch vụ khách hàng\n(B) Nhân viên kế toán ngân hàng\n(C) Nhân viên bán hàng\n(D) Kỹ thuật viên sửa xe đạp"}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following e-mails and checklist.","passages":["<div class=\"hdr\"><p><b>To:</b> y.kuroda@coralmail.com</p><p><b>From:</b> simoncady@techsolve.com</p><p><b>Date:</b> May 12, 1:30 P.M.</p><p><b>Subject:</b> Paperwork</p><p><b>Attachment:</b> Checklist</p></div><p>Dear Ms. Kuroda,</p><p>We still need a few things for your personnel file. At the training for new hires this morning, we provided you with a checklist of the documents that we need to have on file. For your reference, I’ve attached a scanned copy of your checklist to this e-mail.</p><p>First, our security office requires proof of your identity. Employees usually submit a copy of their driver’s license (front and back) or the personal information page from their passport, but any official government identification is acceptable. We also require your banking information to set up the electronic transfer of your salary to your account.</p><p>The final item on the list will only be needed if you join the company softball team. Do you play? Our company team participates in a league, and it’s a great way to build rapport with the people you will be working alongside. The season is just beginning. I can send you details if you’re interested.</p><p>Finally, I want to encourage you to attend the company picnic, which is always held on the third Friday in May at Briarwood Park. It’s an opportunity to interact with your coworkers in an informal, nonworking environment. It’s always well attended.</p><p>If you have any questions, contact me and we can schedule a chat.</p><p>Simon Cady, Human Resources Division<br>Techsolve, Inc.</p>","<h3>New Employee Forms Checklist</h3><p>Name: Yumiko Kuroda<br>Department: Data entry<br>Start Date: May 15</p><table><tr><td></td><td>1. Proof of identity (copy of driver’s license, passport, or other official ID)</td></tr><tr><td>✓</td><td>2. Personal data form</td></tr><tr><td>✓</td><td>3. Tax withholding form</td></tr><tr><td></td><td>4. Bank account information form</td></tr><tr><td>✓</td><td>5. Insurance selection form</td></tr><tr><td></td><td>6. Release of liability form (if required)</td></tr></table>","<div class=\"hdr\"><p><b>To:</b> simoncady@techsolve.com</p><p><b>From:</b> y.kuroda@coralmail.com</p><p><b>Date:</b> May 12, 3:21 P.M.</p><p><b>Subject:</b> Re: Paperwork</p></div><p>Hello Mr. Cady,</p><p>Thank you for your e-mail. I am excited about starting work. And thanks, too, for sending a copy of the checklist I received in the orientation session. I don’t drive, so I don’t have a driver’s license, but I can provide a copy of the page from my passport. I am about to gather the necessary information for the fourth item on the list. I will bring everything to the office on Monday.</p><p>I’ll have to think about whether I want to join the company softball team. How much of a time commitment is it? I played softball in college. I wasn’t very good, but I did enjoy playing.</p><p>The company picnic sounds like fun. I love Briarwood Park and look forward to the opportunity to get to know my coworkers better. If employees bring dishes for the picnic, I’d be happy to make something. Or is the food being provided by a caterer?</p><p>Thanks again for your support.</p><p>Yumiko Kuroda</p>"],"vi":"E-MAIL 1\nGửi: y.kuroda@coralmail.com\nTừ: simoncady@techsolve.com\nNgày: 12 tháng 5, 1:30 chiều\nChủ đề: Giấy tờ\nĐính kèm: Danh sách kiểm tra\n\nKính gửi cô Kuroda,\n\nChúng tôi vẫn cần thêm một vài giấy tờ cho hồ sơ nhân sự của cô. Tại buổi đào tạo dành cho nhân viên mới sáng nay, chúng tôi đã đưa cho cô một danh sách kiểm tra các tài liệu chúng tôi cần lưu trong hồ sơ. Để cô tiện tham khảo, tôi đã đính kèm bản scan danh sách kiểm tra của cô trong e-mail này.\n\nTrước hết, phòng an ninh của chúng tôi yêu cầu giấy tờ chứng minh danh tính. Nhân viên thường nộp bản sao bằng lái xe (mặt trước và mặt sau) hoặc trang thông tin cá nhân trong hộ chiếu, nhưng bất kỳ giấy tờ tùy thân chính thức nào do nhà nước cấp đều được chấp nhận. Chúng tôi cũng cần thông tin ngân hàng của cô để thiết lập việc chuyển khoản lương vào tài khoản của cô.\n\nMục cuối cùng trong danh sách chỉ cần thiết nếu cô tham gia đội bóng mềm (softball) của công ty. Cô có chơi không? Đội của công ty tham gia một giải đấu, và đó là cách tuyệt vời để xây dựng mối quan hệ với những người cô sẽ làm việc cùng. Mùa giải vừa mới bắt đầu. Tôi có thể gửi thông tin chi tiết nếu cô quan tâm.\n\nCuối cùng, tôi khuyến khích cô tham dự buổi dã ngoại của công ty, luôn được tổ chức vào thứ Sáu thứ ba của tháng Năm tại Công viên Briarwood. Đây là cơ hội để giao lưu với đồng nghiệp trong một môi trường thân mật, ngoài giờ làm việc. Buổi dã ngoại luôn có đông người tham dự.\n\nNếu cô có bất kỳ câu hỏi nào, hãy liên hệ với tôi và chúng ta có thể hẹn một buổi trao đổi.\n\nSimon Cady, Bộ phận Nhân sự\nTechsolve, Inc.\n\nDANH SÁCH KIỂM TRA BIỂU MẪU CHO NHÂN VIÊN MỚI\nTên: Yumiko Kuroda\nBộ phận: Nhập liệu\nNgày bắt đầu làm việc: 15 tháng 5\n\n1. Giấy tờ chứng minh danh tính (bản sao bằng lái xe, hộ chiếu hoặc giấy tờ tùy thân chính thức khác)\n✓ 2. Phiếu thông tin cá nhân\n✓ 3. Biểu mẫu khấu trừ thuế\n4. Biểu mẫu thông tin tài khoản ngân hàng\n✓ 5. Biểu mẫu lựa chọn bảo hiểm\n6. Biểu mẫu miễn trừ trách nhiệm (nếu được yêu cầu)\n\nE-MAIL 2\nGửi: simoncady@techsolve.com\nTừ: y.kuroda@coralmail.com\nNgày: 12 tháng 5, 3:21 chiều\nChủ đề: Re: Giấy tờ\n\nChào ông Cady,\n\nCảm ơn ông vì e-mail. Tôi rất háo hức được bắt đầu công việc. Và cũng cảm ơn ông đã gửi bản sao danh sách kiểm tra mà tôi nhận được trong buổi định hướng. Tôi không lái xe nên không có bằng lái, nhưng tôi có thể cung cấp bản sao trang thông tin trong hộ chiếu. Tôi sắp đi thu thập thông tin cần thiết cho mục thứ tư trong danh sách. Tôi sẽ mang tất cả đến văn phòng vào thứ Hai.\n\nTôi sẽ phải suy nghĩ xem có muốn tham gia đội bóng mềm của công ty hay không. Việc này tốn bao nhiêu thời gian? Tôi từng chơi bóng mềm thời đại học. Tôi chơi không giỏi lắm, nhưng tôi thực sự thích chơi.\n\nBuổi dã ngoại của công ty nghe có vẻ rất vui. Tôi rất thích Công viên Briarwood và mong có cơ hội hiểu rõ hơn về đồng nghiệp. Nếu nhân viên mang món ăn đến buổi dã ngoại, tôi sẵn lòng làm một món. Hay đồ ăn sẽ do một đơn vị cung cấp dịch vụ ăn uống phụ trách?\n\nMột lần nữa cảm ơn ông đã hỗ trợ.\n\nYumiko Kuroda","qs":[{"n":196,"q":"What is the main purpose of the first e-mail?","qvi":"Mục đích chính của e-mail thứ nhất là gì?","opts":["To offer Ms. Kuroda a job","To request some documents","To invite Ms. Kuroda to watch a ball game","To schedule an appointment"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: E-mail 1: \"We still need a few things for your personnel file... a checklist of the documents that we need to have on file\" → mục đích chính là yêu cầu cô nộp các giấy tờ còn thiếu.\n(A) Để mời cô Kuroda nhận một công việc\n(B) Để yêu cầu nộp một số tài liệu\n(C) Để mời cô Kuroda xem một trận bóng\n(D) Để sắp xếp một cuộc hẹn"},{"n":197,"q":"Where most likely was Ms. Kuroda on the morning of May 12?","qvi":"Sáng ngày 12/5, cô Kuroda nhiều khả năng đã ở đâu?","opts":["At a training for new hires","At a job interview","At a security office","At a college reunion"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: E-mail 1 gửi lúc \"May 12, 1:30 P.M.\" và viết: \"At the training for new hires this morning, we provided you with a checklist\" → sáng 12/5 cô ở buổi đào tạo nhân viên mới.\n(A) Tại buổi đào tạo nhân viên mới\n(B) Tại một buổi phỏng vấn xin việc\n(C) Tại phòng an ninh\n(D) Tại buổi họp mặt cựu sinh viên"},{"n":198,"q":"Why might Ms. Kuroda need to submit a release form?","qvi":"Vì sao cô Kuroda có thể cần nộp biểu mẫu miễn trừ trách nhiệm (release form)?","opts":["If she borrows some money","If she plays on a sports team","If she attends a social event","If she gets a promotion"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Câu hỏi kết hợp 2 văn bản. Danh sách kiểm tra: mục cuối cùng (số 6) là \"Release of liability form (if required)\". E-mail 1: \"The final item on the list will only be needed if you join the company softball team\" → cô cần nộp nếu tham gia đội bóng mềm (một đội thể thao).\n(A) Nếu cô vay tiền\n(B) Nếu cô chơi trong một đội thể thao\n(C) Nếu cô tham dự một sự kiện giao lưu\n(D) Nếu cô được thăng chức"},{"n":199,"q":"What does Ms. Kuroda indicate about a company picnic?","qvi":"Cô Kuroda cho biết điều gì về buổi dã ngoại của công ty?","opts":["She does not know where it will take place.","She does not know whether she can go to it.","She is eager to meet her coworkers there.","She would be happy to organize the catering for it."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: E-mail 2: \"The company picnic sounds like fun. I love Briarwood Park and look forward to the opportunity to get to know my coworkers better\" → cô háo hức được làm quen với đồng nghiệp. (D) sai: cô chỉ nói sẵn lòng làm một món ăn, không phải tổ chức dịch vụ ăn uống.\n(A) Cô không biết buổi dã ngoại diễn ra ở đâu\n(B) Cô không biết mình có thể đi được không\n(C) Cô háo hức được gặp gỡ đồng nghiệp ở đó\n(D) Cô sẵn lòng tổ chức phần ăn uống cho buổi dã ngoại"},{"n":200,"q":"What will Ms. Kuroda most likely do next?","qvi":"Cô Kuroda nhiều khả năng sẽ làm gì tiếp theo?","opts":["Eat lunch with her coworkers","Look for details of her bank account","E-mail a list to Mr. Cady","Ask Mr. Cady about applying for a passport"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Câu hỏi kết hợp 2 văn bản. E-mail 2: \"I am about to gather the necessary information for the fourth item on the list\". Danh sách kiểm tra: mục 4 là \"Bank account information form\" → cô sắp đi tìm thông tin tài khoản ngân hàng.\n(A) Ăn trưa với đồng nghiệp\n(B) Tìm thông tin chi tiết về tài khoản ngân hàng của mình\n(C) Gửi e-mail một danh sách cho ông Cady\n(D) Hỏi ông Cady về việc xin cấp hộ chiếu"}]}]}};
